TURATH_CHUNK(11,[{"num":2200,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْصِلُ بَيْنَ الْوَتْرِ وَالشَّفْعِ بِتَسْلِيمَةٍ وَيُسْمِعُنَاهَا."],"takhrij":"حسن: رواه الإمام أحمد (5461) قال: حدثنا عتَّاب بن زياد، حدثنا أبو حمزة، يعني السكري، عن إبراهيم، يعني الصائغ، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تسليمة واحدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (5461); Ibn Hibban authenticated it (2435)","chapter_en":"What has been narrated about a single taslim","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ used to separate the witr from the shaf‘ with a taslim, and he would make it audible for us."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (5461)، وصححه ابن حبان (2435)."},{"num":2201,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَحْدَثَ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيَأْخُذْ بِأَنْفِهِ ثُمَّ لِيَنْصَرِفْ."],"takhrij":"صحيح: رواه أبو داود (1114) وابن ماجه (1222) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة.","grade":"صحيح","chapter_ar":"باب من أحدث في الصلاة كيف ينصرف؟","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1114), Ibn Majah (1222)","chapter_en":"If someone breaks ablution during prayer, how should he leave?","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["The Mother of the Believers ‘A’ishah said: The Prophet ﷺ said: “If one of you breaks ablution during his prayer, let him hold his nose and then leave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1114)، ابن ماجه (1222)."},{"num":2202,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ قَامَ النِّسَاءُ حِينَ يَقْضِي تَسْلِيمَهُ، وَمَكَثَ يَسِيرًا قَبْلَ أَنْ يَقُومَ.","قَالَ ابْنُ شِهَابٍ: فَأُرَى وَاللَّهُ أَعْلَمُ أَنَّ مُكْثَهُ لِكَيْ يَنْفُذَ النِّسَاءُ قَبْلَ أَنْ يُدْرِكَهُنَّ مَنِ انْصَرَفَ مِنَ الْقَوْمِ."],"takhrij":"صحيح: رواه البخاري في الأذان (837) عن موسى بن إسماعيل، حدثنا إبراهيم بن سعدٍ، حدثنا الزهري، عن هند بنت الحارث، أن أم سلمة قالت: فذكرتِ الحديث.","grade":"صحيح","chapter_ar":"باب انصراف النساء بعد السلام قبل الرجال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (837)","chapter_en":"Women leaving after the taslim before the men","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: When the Messenger of Allah ﷺ gave the closing greeting, the women would stand and leave as soon as he finished his taslim, while he remained briefly before standing. Ibn Shihab said: I think—and Allah knows best—that he remained briefly so that the women could depart before they were caught up by those men who left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (837)."},{"num":2203,"demo":false,"sanad":"","matn":["عَنِ السُّدِّيِّ قَالَ: سَأَلْتُ أَنَسًا: كَيْفَ أَنْصَرِفُ إِذَا صَلَّيْتُ عَنْ يَمِينِي أَوْ عَنْ يَسَارِي ؟ قَالَ: أَمَّا أَنَا فَأَكْثَرُ مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْصَرِفُ عَنْ يَمِينِهِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (708) من طريق أبي عوانة وسفيان، كلاهما عن السدي به.","grade":"صحيح","chapter_ar":"باب ما جاء من انصراف النبي ﷺ عن اليمين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (708)","chapter_en":"The Prophet ﷺ turning to the right after prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["Al-Suddi said: I asked Anas: “When I finish praying, should I turn to my right or to my left?” He said: “As for me, I most often saw the Messenger of Allah ﷺ turn to his right.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (708)."},{"num":2204,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: كُنَّا إِذَا صَلَّيْنَا خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَحْبَبْنَا أَنْ نَكُونَ عَنْ يَمِينِهِ، يُقْبِلُ عَلَيْنَا بِوَجْهِهِ، قَالَ: فَسَمِعْتُهُ يَقُولُ: رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ، أَوْ تَجْمَعُ عِبَادَكَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (709) عن أبي كُريب، أخبرنا ابن أبي زائدة، عن مِسْعَر، عن ثابت بن عبيد، عن ابن البراء، عن البراء فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من انصراف النبي ﷺ عن اليمين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (709)","chapter_en":"The Prophet ﷺ turning to the right after prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: When we prayed behind the Messenger of Allah ﷺ, we loved to be on his right so that he would face us. He said: I heard him saying: “My Lord, protect me from Your punishment on the day You resurrect—or gather—Your servants.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (709)."},{"num":2205,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ أَنَّهُ قَالَ: لَا يَجْعَلْ أَحَدُكُمْ لِلشَّيْطَانِ شَيْئًا مِنْ صَلَاتِهِ يَرَى أَنَّ حَقًّا عَلَيْهِ أَنْ لَا يَنْصَرِفَ إِلَّا عَنْ يَمِينِهِ، لَقَدْ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَثِيرًا يَنْصَرِفُ عَنْ يَسَارِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (852)، ومسلم في صلاة المسافرين (707) كلاهما من طريق الأعمش، عن عُمارة بن عُمير، عن الأسود، عن عبدالله بن مسعود فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من انصراف النبي ﷺ عن اليسار","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (852), Muslim (707)","chapter_en":"The Prophet ﷺ turning to the left after prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: Let none of you give Satan any share of his prayer by thinking it is obligatory to turn only to the right. I have seen the Prophet ﷺ often turn to his left."]},"buhuth":{"en":["There is no contradiction between Anas saying: “Most often I saw the Messenger of Allah ﷺ turn to his right,” and Ibn Mas‘ud saying: “I saw the Prophet ﷺ often turn to his left.” Anas is reporting what he generally observed as most common, while Ibn Mas‘ud is also reporting what he frequently observed. Ibn Mas‘ud also clarified why turning to the left was often seen: the Prophet’s room was on his left. It is reported that a man asked Ibn Mas‘ud whether the Messenger of Allah ﷺ would turn to the right or to the left after prayer, and he replied: “He would turn whichever way he wished, and his turning was most often to his left side toward his room.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (852)، مسلم (707)."},{"num":2206,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَقْبَلَ عَلَيْنَا بِوَجْهِهِ."],"takhrij":"صحيح: رواه البخاري في الأذان (845) ومسلم في الفضائل (2275) كلاهما من حديث جرير بن حازم، قال: حدثنا أبو رجاء، عن سمرة بن جندب فذكره. وزاد مسلم فقال: هل رأى أحد منكم رؤيا؟.","grade":"صحيح","chapter_ar":"باب إقبال النبي ﷺ على أصحابه بعد التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (845), Muslim (2275)","chapter_en":"The Prophet ﷺ turning to his Companions after the taslim","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["Samurah ibn Jundub said: When the Prophet ﷺ finished a prayer, he would turn to face us. Muslim adds: “Has any one of you seen a dream?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (845)، مسلم (2275)."},{"num":2207,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ أَنَّهُ قَالَ: صَلَّى لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ بِالْحُدَيْبِيَةِ عَلَى إِثْرِ سَمَاءٍ كَانَتْ مِنَ اللَّيْلَةِ، فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: فَذَكَرَ بَقِيَّةَ الْحَدِيثِ."],"takhrij":"متفق عليه: رواه مالك في الاستسقاء (4) عن صالح بن كيسان، عن عبيدالله بن عبدالله بن عتبة بن مسعو، عن زيد بن خالد الجهني فذكره.","grade":"متفق عليه","chapter_ar":"باب إقبال النبي ﷺ على أصحابه بعد التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (4), al-Bukhari (846), Muslim (71)","chapter_en":"The Prophet ﷺ turning to his Companions after the taslim","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: The Messenger of Allah ﷺ led us in the dawn prayer at al-Hudaybiyah after rainfall that had fallen during the night. When he finished, he turned to the people and spoke… then he mentioned the rest of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4)، البخاري (846)، مسلم (71)."},{"num":2208,"demo":false,"sanad":"","matn":["عَنْ هُلْبٍ (بِضَمِّ الْهَاءِ وَسُكُونِ اللَّامِ، صَحَابِيّ) قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَؤُمُّنَا فَيَنْصَرِفُ عَلَى جَانِبَيْهِ جَمِيعًا عَلَى يَمِينِهِ وَعَلَى شِمَالِهِ."],"takhrij":"حسن: رواه أبو داود (1041)، والترمذي (301)، وابن ماجه (929) كلهم من طريق سماك بن حرب، عن قبيصة بن هُلب، عن أبيه فذكره، واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب ما جاء في انصراف الإمام أحياناً عن اليمين وأحياناً عن الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good\nAbu Dawud (1041), al-Tirmidhi (301), Ibn Majah (929) — al-Tirmidhi said: “Hasan”","chapter_en":"The imam sometimes turning to the right and sometimes to the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Hulb said: The Messenger of Allah ﷺ used to lead us, and he would turn both ways—sometimes to his right and sometimes to his left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1041)، والترمذي (301)، وابن ماجه (929)، وقال الترمذي: حسن."},{"num":2209,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْفَتِلُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ فِي الصَّلَاةِ."],"takhrij":"حسن: رواه ابن ماجه (931) عن بشر بن هلال الصواف، قال: حدثنا يزيد بن زريع، عن حسين المعلم، عن عمرو بن شُعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في انصراف الإمام أحياناً عن اليمين وأحياناً عن الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (931)","chapter_en":"The imam sometimes turning to the right and sometimes to the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: I saw the Prophet ﷺ turn to his right and to his left after prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (931)."},{"num":2210,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي حَافِيًا وَنَاعِلًا وَقَائِمًا وَقَاعِدًا وَيَنْفَتِلُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ."],"takhrij":"حسن: رواه الإمام أحمد (7384)، والحميدي (997) عن سفيان، عن","grade":"حسن","chapter_ar":"باب ما جاء في انصراف الإمام أحياناً عن اليمين وأحياناً عن الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (7384), al-Humaydi (997)","chapter_en":"The imam sometimes turning to the right and sometimes to the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: I saw the Prophet ﷺ pray barefoot and with sandals, standing and sitting, and he would turn to his right and to his left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7384)، والحميدي (997)."},{"num":2211,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَائِمًا وَقَاعِدًا، وَيُصَلِّي مُنْتَعِلًا وَحَافِيًا، وَيَنْصَرِفُ مِنَ الصَّلَاةِ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ ."],"takhrij":"حسن: رواه الطبراني في الأوسط (1213) عن أحمد، قال: حدثنا يحيى بن حكيم المقوِّم، قال: حدثنا مُخلد بن يزيد الحراني، عن يحيى بن سعيد الأنصاري، عن عطاء، عن عائشة فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في انصراف الإمام أحياناً عن اليمين وأحياناً عن الشمال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Awsat (1235)","chapter_en":"The imam sometimes turning to the right and sometimes to the left","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["‘A’ishah said: I saw the Messenger of Allah ﷺ drink standing and sitting, pray with sandals and barefoot, and turn from prayer to his right and to his left."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2579,9563,14390],"tks":"حسن: رواه الطبراني في المعجم الأوسط (1213)."},{"num":2212,"demo":false,"sanad":"","matn":["عَنْ وَرَّاد كَاتِبِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: أَمْلَى عَلَيَّ الْمُغِيرَةُ بْنُ شُعْبَةَ فِي كِتَابٍ إِلَى مُعَاوِيَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي دُبُرِ كُلِّ صَلَاةٍ مَكْتُوبَةٍ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (844)، ومسلم في المساجد (593) كلاهما من طريق ورَّاد مولى المغيرة به مثله.","grade":"متفق عليه","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (844), Muslim (593)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Warrad, the scribe of al-Mughirah ibn Shu‘bah, said: Al-Mughirah dictated to me in a letter to Mu‘awiyah that the Prophet ﷺ used to say after every obligatory prayer: “There is no god worthy of worship except Allah alone with no partner. To Him belongs all dominion and all praise, and He is able to do all things. O Allah, none can withhold what You give, none can give what You withhold, and the wealth or status of a person will not benefit him against You.”"]},"buhuth":{"en":["Regarding “and the wealth/status (al-jadd) will not benefit its owner against You”: the well-known reading is with a fatḥah on the letter jīm, meaning: the person of wealth and worldly fortune is not benefited by his wealth in front of Allah. Al-Hasan said: “al-jadd” means wealth."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11044,12304,13128],"tks":"متفق عليه: رواه البخاري (844)، مسلم (593)."},{"num":2213,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ رَفْعَ الصَّوْتِ بِالذِّكْرِ حِينَ يَنْصَرِفُ النَّاسُ مِنَ الْمَكْتُوبَةِ كَانَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","وَقَالَ ابْنُ عَبَّاسٍ: كُنْتُ أَعْلَمُ إِذَا انْصَرَفُوا بِذَلِكَ إِذَا سَمِعْتُهُ .."],"takhrij":"متفق عليه: رواه البخاري في الأذان (841)، ومسلم في المساجد (583، 121) كلاهما من طريق عبد الرزاق، أخبرنا ابن جريج قال: أخبرني عمرو بن دينار، أن أبا معبد مولى ابن عباس أخبره، أن ابن عباس أخبره، قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (841), Muslim (583/121)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Ibn ‘Abbas said: Raising the voice with remembrance when the people finished the obligatory prayer used to be practiced during the time of the Prophet ﷺ. Ibn ‘Abbas said: I would know they had finished when I heard it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11064],"tks":"متفق عليه: رواه البخاري (841)، مسلم (583/121)."},{"num":2214,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: جَاءَ الْفُقَرَاءُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: ذَهَبَ أَهْلُ الدُّثُورِ مِنَ الْأَمْوَالِ بِالدَّرَجَاتِ الْعُلَا وَالنَّعِيمِ الْمُقِيمِ، يُصَلُّونَ كَمَا نُصَلِّي وَيَصُومُونَ كَمَا نَصُومُ، وَلَهُمْ فَضْلٌ مِنْ أَمْوَالٍ يَحُجُّونَ بِهَا وَيَعْتَمِرُونَ وَيُجَاهِدُونَ وَيَتَصَدَّقُونَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أُحَدِّثُكُمْ بِأَمْرٍ إِنْ أَخَذْتُمْ بِهِ أَدْرَكْتُمْ مَنْ سَبَقَكُمْ وَلَمْ يُدْرِكْكُمْ أَحَدٌ بَعْدَكُمْ وَكُنْتُمْ خَيْرَ مَنْ أَنْتُمْ بَيْنَ ظَهْرَانَيْهِ، إِلَّا مَنْ عَمِلَ مِثْلَهُ تُسَبِّحُونَ وَتَحْمَدُونَ وَتُكَبِّرُونَ خَلْفَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، فَاخْتَلَفْنَا بَيْنَنَا، فَقَالَ: بَعْضُنَا نُسَبِّحُ ثَلَاثًا وَثَلَاثِينَ وَنَحْمَدُ ثَلَاثًا وَثَلَاثِينَ وَنُكَبِّرُ أَرْبَعًا وَثَلَاثِينَ، فَرَجَعْتُ إِلَيْهِ، فَقَالَ: تَقُولُ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ حَتَّى يَكُونَ مِنْهُنَّ كُلِّهِنَّ ثَلَاثًا وَثَلَاثِينَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (843)، ومسلم في المساجد (595) كلاهما من طريق معتمر، عن عبيدالله، عن سُمّيٍ، عن أبي صالح، عن أبي هريرة فذكر مثله واللفظ للبخاري وزاد مسلم: جاء فقراء المهاجرين.","grade":"متفق عليه","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (843) — wording his; Muslim (595) (Muslim adds: “The poor of the Emigrants came…”)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah said: The poor came to the Prophet ﷺ and said: “The people of great wealth have taken the highest ranks and everlasting bliss. They pray as we pray and fast as we fast, but they have surplus wealth by which they perform pilgrimage and lesser pilgrimage, strive, and give charity.” The Messenger of Allah ﷺ said: “Shall I tell you something—if you do it, you will catch up with those who have surpassed you, no one after you will surpass you, and you will be the best among those around you except someone who does the same? Say ‘Glory be to Allah,’ ‘Praise be to Allah,’ and ‘Allāhu akbar’ after every prayer, thirty-three times each.” We then differed among ourselves: some said, “We say ‘Glory be to Allah’ thirty-three times, ‘Praise be to Allah’ thirty-three times, and ‘Allāhu akbar’ thirty-four times.” So I returned to him, and he said: “Say: ‘Subhan Allah,’ ‘Alhamdu lillah,’ and ‘Allahu Akbar’ until each of them totals thirty-three.”"]},"buhuth":{"en":["“Al-duthur” means abundant wealth. “The everlasting bliss” means lasting delight—referring to the joy of the Hereafter and the life of Paradise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (843) واللفظ له، ومسلم (595)، وزاد مسلم: «جاء فقراء المهاجرين...»."},{"num":2215,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَنْ سَبَّحَ اللَّهَ فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَحَمِدَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَكَبَّرَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، فَتْلِكَ تِسْعَةٌ وَتِسْعُونَ، وَقَالَ تَمَامَ الْمِائَةِ: لَا إِلَهَ إِلَّا اللَّهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، غُفِرَتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"صحيح: رواه مسلم في المساجد (597) عن عبدالحميد بن بيان الواسطي، أخبرنا خالد بن عبدالله، عن سُهيل، عن أبي عبيد المذحجِي (قال مسلم: أبو عبيد مولى سليمان بن عبدالملك) عن عطاء بن يزيد الليثي، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (597)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever says ‘Glory be to Allah’ thirty-three times after every prayer, and ‘Praise be to Allah’ thirty-three times, and ‘Allāhu akbar’ thirty-three times—that is ninety-nine—and completes one hundred by saying: ‘There is no god worthy of worship except Allah alone with no partner; to Him belongs all dominion and all praise, and He is able to do all things’—his sins will be forgiven even if they are like the foam of the sea.”"]},"buhuth":{"en":["“Even if they are like the foam of the sea” means: even if they are extremely numerous and great—like the foam that rises on the surface of the sea when it surges."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11054,13394],"tks":"صحيح: رواه مسلم (597)."},{"num":2216,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ أَنَّهُ كَانَ يُعَلِّمُ بَنِيهِ هَؤُلَاءِ الْكَلِمَاتِ كَمَا يُعَلِّمُ الْمُعَلِّمُ الْغِلْمَانَ الْكِتَابَةَ وَيَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَعَوَّذُ مِنْهُنَّ دُبُرَ الصَّلَاة:ِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2822) من طريق أبي عوانة، عن عبدالملك بن عمير، قال: سمعتُ عمرو بن ميمون الأوْدي قال:كان سعد فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (2822)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas used to teach his children these words the way a teacher teaches boys writing, and he would say: The Messenger of Allah ﷺ used to seek refuge with Allah from them after prayer: “O Allah, I seek refuge in You from cowardice; I seek refuge in You from being returned to the most feeble stage of life; I seek refuge in You from the trials of this world; and I seek refuge in You from the punishment of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2822)."},{"num":2217,"demo":false,"sanad":"","matn":["عَنْ أَبِي الزُّبَيْرِ قَالَ: كَانَ ابْنُ الزُّبَيْرِ يَقُولُ فِي دُبُرِ كُلِّ صَلَاةٍ حِينَ يُسَلِّمُ: لَا إِلَهَ إِلَّا اللَّهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لَا إِلَهَ إِلَّا اللَّهُ، مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ، وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُهَلِّلُ بِهِنَّ دُبُرَ كُلِّ صَلَاةٍ."],"takhrij":"صحيح: رواه مسلم في المساجد (594) عن محمد بن عبدالله بن نمير، حدثنا أبي، حدثنا هشام، عن أبي الزبير فذكره. ورواه من طريق الحجاج بن أبي عثمان قال: حدثني أبو الزبير قال: سمعتُ عبدالله بن الزبير يخطب على هذا المنبر وهو يقول: كان رسول الله صلى الله عليه وسلم يقول إذا سلَّم في دبر الصلاة، أو الصلوات فذكر مثله.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (594)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Abu al-Zubayr said: Ibn al-Zubayr used to say after every prayer, when he finished the taslim: “There is no god worthy of worship except Allah alone with no partner. To Him belongs all dominion and all praise, and He is able to do all things. There is no power and no strength except with Allah. There is no god worthy of worship except Allah, and we worship none but Him. To Him belong blessing, favor, and beautiful praise. There is no god worthy of worship except Allah, making the religion sincerely for Him even if the disbelievers dislike it.” And he said: The Messenger of Allah ﷺ used to say these declarations after every prayer."]}},"tuhfa":{},"full":1,"rep":[11046,13214],"tks":"صحيح: رواه مسلم (594)."},{"num":2218,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا انْصَرَفَ مِنْ صَلَاتِهِ، اسْتَغْفَرَ ثَلَاثًا وَقَالَ: اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ ذَا الْجَلَالِ وَالإِكْرَامِ، قَالَ الْوَلِيدُ: فَقُلْتُ لِلأَوْزَاعِيِّ، كَيْفَ الْاسْتِغْفَارُ ؟ قَالَ: تَقُولُ: أَسْتَغْفِرُ اللَّهَ، أَسْتَغْفِرُ اللَّهَ."],"takhrij":"صحيح: رواه مسلم في المساجد (591) عن داود بن رُشيد، حدثنا الوليد، عن الأوزاعي، عن أبي عمار (اسمه شدَّاد بن عبدالله) عن أبي أسماء، عن ثوبان فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (591)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Thawban said: When the Messenger of Allah ﷺ finished his prayer, he would seek Allah’s forgiveness three times and say: “O Allah, You are Peace, and from You is peace. Blessed are You, Possessor of majesty and honor.” Al-Walid said: I asked al-Awza‘i, “How is the seeking of forgiveness?” He said: You say: “I seek Allah’s forgiveness, I seek Allah’s forgiveness.”"]}},"tuhfa":{},"full":1,"rep":[11041,13475],"tks":"صحيح: رواه مسلم (591)."},{"num":2219,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ لَمْ يَقْعُدْ إِلَّا مِقْدَارَ مَا يَقُولُ: اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ ذَا الْجَلَالِ وَالإِكْرَامِ، وَفِي رِوَايَةِ ابْنِ نُمَيْرٍ: يَا ذَا الْجَلَالِ وَالإِكْرَامِ."],"takhrij":"صحيح: رواه مسلم في المساجد (592) من طريق أبي معاوية، عن عاصم، عن عبدالله بن الحارث، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (592)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["‘A’ishah said: When the Prophet ﷺ gave the taslim, he would not remain seated except for the time it takes to say: “O Allah, You are Peace and from You is peace. Blessed are You, Possessor of majesty and honor.” In the narration of Ibn Numayr: “O Possessor of majesty and honor.”"]}},"tuhfa":{},"full":1,"rep":[11042],"tks":"صحيح: رواه مسلم (592)."},{"num":2220,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ لَمْ يَجْلِسُ إِلا مِقْدَارَ مَا يَقُولُ: اللَّهُمَّ أَنْتَ السَّلامُ وَمِنْكَ السَّلامُ تَبَارَكْتَ يَا ذَا الْجِلالِ وَالإِكْرَامِ."],"takhrij":"حسن: رواه ابن أبي شيبة في مصنفه (3085)، والنسائي في الكبرى (10126)، وابن حبان (2002) كلهم من طرقٍ عن عاصم الأحول، عن عوسجة بن الرماح، عن عبدالله بن أبي الهذيل، عن عبدالله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Abi Shaybah in al-Musannaf (3085); al-Nasa’i in al-Kubra (10126); Ibn Hibban (2002)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: When the Messenger of Allah ﷺ gave the taslim, he would not sit except for the time it takes to say: “O Allah, You are Peace and from You is peace. Blessed are You, O Possessor of majesty and honor.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة في المصنف (3085)، النسائي في الكبرى (10126)، ابن حبان (2002)."},{"num":2221,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مُعَقِّبَاتٌ لَا يَخِيبُ قَائِلُهُنَّ أَوْ فَاعِلُهُنَّ، دُبُرَ كُلِّ صَلَاةٍ مَكْتُوبَةٍ، ثَلَاثٌ وَثَلَاثُونَ تَسْبِيحَةً، وَثَلَاثٌ وَثَلَاثُونَ تَحْمِيدَةً، وَأَرْبَعٌ وَثَلَاثُونَ تَكْبِيرَةً."],"takhrij":"صحيح: رواه مسلم في المساجد (596) عن الحسن بن عيسى، أخبرنا ابن المبارك، أخبرنا مالك بن مِغْول، قال: سمعتُ الحكم بن عتيبة، يحدث عن عبدالرحمن بن أبي ليلى، عن كعب بن عُجرة فذكر مثله.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (596)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Ka‘b ibn ‘Ujrah reported that the Messenger of Allah ﷺ said: “Consecutive remembrances—whoever says them after every obligatory prayer will not be disappointed: thirty-three glorifications, thirty-three praises, and thirty-four repetitions of ‘Allāhu akbar’.”"]},"buhuth":{"en":["“Muʿaqqibāt” means remembrances performed immediately after the prayer. It is said they are called that because they are done repeatedly, one after another. Regarding the saying of Allah, “For him are successive [angels] before him and behind him,” it means angels who follow one another."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11056],"tks":"صحيح: رواه مسلم (596)."},{"num":2222,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: يَا رَسُولَ اللَّهِ! ذَهَبَ أَصْحَابُ الدُّثُورِ بِالْأُجُورِ يُصَلُّونَ كَمَا نُصَلِّي وَيَصُومُونَ كَمَا نَصُومُ، وَلَهُمْ فُضُولُ أَمْوَالٍ يَتَصَدَّقُونَ بِهَا وَلَيْسَ لَنَا مَالٌ نَتَصَدَّقُ بِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا ذَرٍّ، أَلَا أُعَلِّمُكَ كَلِمَاتٍ تُدْرِكُ بِهِنَّ مَنْ سَبَقَكَ، وَلَا يَلْحَقُكَ مَنْ خَلْفَكَ إِلَّا مَنْ أَخَذَ بِمِثْلِ عَمَلِكَ؟ قَالَ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: تُكَبِّرُ اللَّهَ عَزَّ وَجَلَّ دُبُرَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَتَحْمَدُهُ ثَلَاثًا وَثَلَاثِينَ، وَتُسَبِّحُهُ ثَلَاثًا وَثَلَاثِينَ، وَتَخْتِمُهَا بِلَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، غُفِرَتْ لَهُ ذُنُوبُهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"صحيح: رواه أبو داود (1504) عن عبدالرحمن بن إبراهيم (وهو دُحيم) حدثنا الوليد بن مسلم، حدثنا الأوزاعي، حدثني حسان بن عطية قال: حدثني محمد بن أبي عائشة قال: حدثني أبو هريرة قال: قال أبو ذر فذكره. وإسناده صحيح، والوليد بن مسلم مدلس، ولكنه صرّح بالتحديث وأخرجه أيضاً ابن حبان في صحيحه (2015) وهو عند الإمام أحمد (7243) عن الوليد بن مسلم بهذا الإسناد. ورواه ابن ماجه (927) عن الحسين بن الحسن المروزي، قال: حدثنا سفيان بن عيينة، عن بشر بن عاصم، عن أبيه، عن أبي ذر قال: قيل للنبي صلى الله عليه وسلم، وربما قال سفيان: قلت: يا رسول الله وجاء فيه: ألا أُخبركم بأمر إذا فعلتموه أدركتم من قبلكم، وفُتُّمْ من بعدكم. تحمدون الله في دبر كل صلاة، وتُسبِّحونه، وتكبرونه، ثلاثاً وثلاثين، وثلاثاً وثلاثين، وأربعاً وثلاثين.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (1504) and Ibn Ḥibbān (2015).","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Abū Dharr said: “O Messenger of Allah ﷺ, the people of wealth have taken all the rewards. They pray as we pray and fast as we fast, but they possess surplus wealth from which they give charity, while we have no wealth from which to give charity.” The Messenger of Allah ﷺ said: “O Abū Dharr, shall I teach you words by which you will catch up with those who have surpassed you, and no one after you will catch up with you except one who does the same deed as you?” He said: “Yes, O Messenger of Allah ﷺ.” He said: “Magnify Allah, Mighty and Majestic, by saying ‘Allāhu akbar’ thirty-three times after every prayer, praise Him thirty-three times and glorify Him thirty-three times, and conclude with: ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs the dominion and to Him belongs all praise, and He has power over all things.’ His sins will be forgiven even if they are like the foam of the sea.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11055],"tks":"صحيح: رواه أبو داود (1504)، وابن حبان (2015)."},{"num":2223,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ قَالَ: أُمِرْنَا أَنْ نُسَبِّحَ دُبُرَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَنَحْمَدَهُ ثَلَاثًا وَثَلَاثِينَ، وَنُكَبِّرَهُ أَرْبَعًا وَثَلَاثِينَ، قَالَ: فَرَأَى رَجُلٌ مِنَ الْأَنْصَارِ فِي الْمَنَامِ، فَقَالَ: أَمَرَكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُسَبِّحُوا فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَتَحْمَدُوا اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَتُكَبِّرُوا أَرْبَعًا وَثَلَاثِينَ، قَالَ: نَعَمْ، قَالَ: فَاجْعَلُوا خَمْسًا وَعِشْرِينَ، وَاجْعَلُوا التَّهْلِيلَ مَعَهُنَّ، فَغَدَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثَهُ، فَقَالَ: افْعَلُوا.","(أَيْ التَّسْبِيحِ خَمْسٌ وَعِشْرُونَ، وَالتَّحْمِيد خَمْسٌ وَعِشْرُونَ، وَالتَّكْبِير خَمْسٌ وَعِشْرُونَ، وَلَا إلَهَ إلَّا اللَّهُ خَمْسَ وَعِشْرُون فَتِلْكَ مِائَةٌ)."],"takhrij":"صحيح: رواه الترمذي (3413)، والنسائي (1350) كلاهما من طريق هشام ابن حسان، عن محمد بن سيرين، عن كثير بن أفلح، عن زيد بن ثابت فذكر مثله.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3413) and al-Nasāʾī (1350).","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Zayd ibn Thābit said: “We were commanded to glorify Allah thirty-three times after every prayer, praise Him thirty-three times, and say ‘Allāhu akbar’ thirty-four times. Then a man from the Anṣār saw in a dream someone saying to him: ‘Did the Messenger of Allah ﷺ command you to glorify Allah thirty-three times after every prayer, praise Allah thirty-three times, and say ‘Allāhu akbar’ thirty-four times?’ He replied: ‘Yes.’ He said: ‘Make them twenty-five, and include the declaration of Allah’s oneness among them.’","The next morning he went to the Prophet ﷺ and told him about it, and he said: ‘Do so.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3413)، والنسائي (1350)."},{"num":2224,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ رَجُلًا رَأَى فِيمَا يَرَى النَّائِمُ، قِيلَ لَهُ: بِأَيِّ شَيْءٍ أَمَرَكُمْ نَبِيُّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم؟ قَالَ: أَمَرَنَا أَنْ نُسَبِّحَ ثَلَاثًا وَثَلَاثِينَ، وَنَحْمَدَ ثَلَاثًا وَثَلَاثِينَ، وَنُكَبِّرَ أَرْبَعًا وَثَلَاثِينَ فَتِلْكَ مِائَةٌ، قَالَ: سَبِّحُوا خَمْسًا وَعِشْرِينَ، وَاحْمَدُوا خَمْسًا وَعِشْرِينَ , وَكَبِّرُوا خَمْسًا وَعِشْرِينَ، وَهَلِّلُوا خَمْسًا وَعِشْرِينَ، وَاحْمَدُوا خَمْسًا وَعِشْرِينَ، وَكَبِّرُوا خَمْسًا وَعِشْرِينَ وَهَلِّلُوا خَمْسًا وَعِشْرِينَ فَتِلْكَ مِائَةٌ فَلَمَّا أَصْبَحَ ذَكَرَ ذَلِك للنَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: افْعَلُوا كَمَا قَالَ الْأَنْصَارِيُّ."],"takhrij":"حسن: رواه النسائي (1351) أخبرنا عبيدالله بن عبدالكريم أبوزرعة الرازي، قال: حدثنا أحمد بن عبدالله بن يونس، قال: حدثني علي بن الفُضَيل ابن عياض، عن عبد العزيز بن أبي روَّاد، عن نافع، عن ابن عمر فذكر مثله.","grade":"حسن","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good and authentic: Narrated by al-Nasāʾī (1351).","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported: A man saw in a dream that someone asked him: “What has your Prophet ﷺ commanded you to do?” He replied: “He commanded us to glorify Allah thirty-three times, praise Him thirty-three times, and say ‘Allāhu akbar’ thirty-four times, making one hundred.” He said: “Glorify Allah twenty-five times, praise Him twenty-five times, say ‘Allāhu akbar’ twenty-five times, and declare His oneness twenty-five times. That makes one hundred.” When morning came, he mentioned this to the Prophet ﷺ, and the Messenger of Allah ﷺ said: “Do as the Anṣārī said.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1351)."},{"num":2225,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَلَّتَانِ لَا يُحْصِيهِمَا رَجُلٌ مُسْلِمٌ إِلَّا دَخَلَ الْجَنَّةَ أَلَا وَهُمَا يَسِيرٌ، وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ: يُسَبِّحُ اللَّهَ فِي دُبُرِ كُلِّ صَلَاةٍ عَشْرًا، وَيَحْمَدُهُ عَشْرًا، وَيُكَبِّرُهُ عَشْرًا، قَالَ: فَأَنَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُهَا بِيَدِهِ، قَالَ: فَتِلْكَ خَمْسُونَ وَمِائَةٌ بِاللِّسَانِ وَأَلْفٌ وَخَمْسُ مِائَةٍ فِي الْمِيزَانِ، وَإِذَا أَخَذْتَ مَضْجَعَكَ تُسَبِّحُهُ وَتُكَبِّرُهُ وَتَحْمَدُهُ مِائَةً، فَتِلْكَ مِائَةٌ بِاللِّسَانِ وَأَلْفٌ فِي الْمِيزَانِ، فَأَيُّكُمْ يَعْمَلُ فِي الْيَوْمِ وَاللَّيْلَةِ أَلْفَيْنِ وَخَمْسَ مِائَةِ سَيِّئَةٍ، قَالُوا: فَكَيْفَ لَا يُحْصِيهَا ؟ قَالَ: يَأْتِي أَحَدَكُمُ الشَّيْطَانُ وَهُوَ فِي صَلَاتِهِ، فَيَقُولُ: اذْكُرْ كَذَا اذْكُرْ كَذَا حَتَّى يَنْفَتِلَ، فَلَعَلَّهُ لَا أَنْ يَفْعَلُ، وَيَأْتِيهِ وَهُوَ فِي مَضْجَعِهِ فَلَا يَزَالُ يُنَوِّمُهُ حَتَّى يَنَامَ."],"takhrij":"صحيح: رواه الترمذي (3410) وهذا لفظه، من طريق إسماعيل بن علية، وابن ماجه (926) قرنه بإسماعيل محمد بن فُضيل، وأبو يحيى التيمي وابن الأجلح، والنسائي (1348) من طريق حماد، وأبو داود (1502) من طريق الأعمش مختصراً، وabudawud(5065) عن طريق شعبة مطولا كلهم عن عطاء بن السائب، عن أبيه، عن عبدالله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3410), Abū Dāwūd (5065), al-Nasāʾī (1348), and Ibn Mājah (926).","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr reported that the Messenger of Allah ﷺ said: “There are two characteristics which no Muslim man keeps count of except that he will enter Paradise. Indeed, they are easy, yet those who practice them are few: After every prayer, he glorifies Allah ten times, praises Him ten times, and says ‘Allāhu akbar’ ten times.” He said: “I saw the Messenger of Allah ﷺ counting them on his hand.” He continued: “That is one hundred and fifty upon the tongue and one thousand five hundred upon the Scale. When you go to bed, glorify Him, magnify Him, and praise Him one hundred times. That is one hundred upon the tongue and one thousand upon the Scale. So which of you commits two thousand five hundred sins in a day and a night?” They said: “How could we fail to keep count of them?” He said: “Satan comes to one of you while he is praying and says, ‘Remember such-and-such, remember such-and-such,’ until he finishes the prayer and perhaps does not do it. And he comes to him while he is in bed and continues making him drowsy until he falls asleep.”"]},"buhuth":{"en":["“Fifty and one hundred” means: thirty (10+10+10) after each prayer, across five daily prayers equals 150. “One thousand five hundred on the scale” is because each good deed is multiplied tenfold."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3410)، وأبو داود (1502)، والنسائي (1348)، وابن ماجه (926)."},{"num":2226,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ بِيَدِهِ وَقَالَ: يَا مُعَاذُ وَاللَّهِ إِنِّي لَأُحِبُّكَ، وَاللَّهِ إِنِّي لَأُحِبُّكَ، فَقَالَ: أُوصِيكَ يَا مُعَاذُ لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُولُ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ."],"takhrij":"صحيح: رواه أبو داود (1522) وهذا لفظه، والنسائي (1303) كلاهما من طريق حيوة بن شريح، قال: سمعتُ عقبة بن مسلم يقول: حدثني أبو عبدالرحمن الحُبُلي، عن الصُنابحي، عن معاذ بن جبل فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1522) — wording his; al-Nasa’i (1303)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Mu‘adh ibn Jabal reported that the Messenger of Allah ﷺ took him by the hand and said: “O Mu‘adh, by Allah, I truly love you.” Then he said: “I advise you, O Mu‘adh: do not leave off saying after every prayer: O Allah, help me to remember You, to thank You, and to worship You well.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11047],"tks":"صحيح: رواه أبو داود (1522)، واللفظ له، النسائي (1303)."},{"num":2227,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْرَأَ بِالْمُعَوِّذَاتِ دُبُرَ كُلِّ صَلَاةٍ."],"takhrij":"حسن: رواه أبو داود (1523)، والنسائي (1336) كلاهما عن محمد بن سلمة المرادي، قال: حدثنا ابن وهب، عن الليث بن سعد، أن حنين بن أبي حكيم، حدَّثه عن علي بن رباح، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (1523), al-Nasa’i (1336)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir said: The Messenger of Allah ﷺ commanded me to recite the chapters of seeking refuge after every prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11060],"tks":"حسن: رواه أبو داود (1523)، النسائي (1336)."},{"num":2228,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ مِنَ الصَّلَاةِ قَالَ: اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ."],"takhrij":"صحيح: وهذا القدر رواه أبو داود (1509) ونص على أنه كان يقول ذلك عند انصرافه من الصلاة، وفي مسلم (771، 201، 202) في سياق طويل: يقول بين التشهد والتسليم، وفي رواية: إذا سلّم فلعله كان يقول مرة بين التشهد والتسليم، وأخرى بعد الانصراف من الصلاة.","grade":"صحيح","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: When the Prophet ﷺ finished the prayer with the taslim, he would say: “O Allah, forgive me what I have sent ahead and what I have left behind, what I have concealed and what I have made public, what I have gone to excess in, and what You know better than I. You are the One who brings forward and the One who delays. There is no god worthy of worship except You.”"]},"buhuth":{"en":["Abu Dawud (1509). Also appears in Muslim (771/201–202) in a longer context with wording “between the tashahhud and taslim,” and in another wording “when he gave the taslim,” so it may have been said in both places at different times."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11050],"tks":"صحيح: رواه أبو داود (1509)، ورواه مسلم (771/201-202) في سياق أطول بلفظ: «بين التشهد والتسليم»، وفي رواية: «حين سلم»، فيحتمل أنه قاله في الموضعين في أوقات مختلفة."},{"num":2229,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَرَأَ آيَةَ الْكُرْسِيِّ دُبُرَ كُلِّ صَلَاةٍ مَكْتُوبَةٍ لَمْ يَمْنَعْهُ مِنْ دُخُولِ الْجَنَّةِ إِلَّا أَنْ يَمُوتَ."],"takhrij":"حسن: رواه النسائي في اليوم والليلة (100) قال: أخبرنا الحسين بن بشر بطرسوس، كتبنا عنه قال: حدثنا محمد بن حِمْيَر، حدثنا محمد بن زياد، عن أبي أمامة فذكر الحديث.","grade":"حسن","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i in ‘Amal al-Yawm wa al-Laylah (100)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Abu Umamah reported that the Messenger of Allah ﷺ said: “Whoever recites Ayat al-Kursi after every obligatory prayer, nothing prevents him from entering Paradise except death.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (100)."},{"num":2230,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَرْوَانَ أَنَّ كَعْبًا حَلَفَ لَهُ بِاللَّهِ الَّذِي فَلَقَ الْبَحْرَ لِمُوسَى إِنَّا لَنَجِدُ فِي التَّوْرَاةِ أَنَّ دَاوُدَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ إِذَا انْصَرَفَ مِنْ صَلَاتِهِ قَالَ: اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي جَعَلْتَهُ لِي عِصْمَةً، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي جَعَلْتَ فِيهَا مَعَاشِي، اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَأَعُوذُ بِعَفْوِكَ مِنْ نِقْمَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ قَالَ: وَحَدَّثَنِي كَعْبٌ أَنَّ صُهَيْبًا حَدَّثَهُ، أَنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُهُنَّ عِنْدَ انْصِرَافِهِ مِنْ صَلَاتِهِ."],"takhrij":"حسن: رواه النسائي (1346) أخبرنا عمرو بن سَوَّاد بن الأسود بن عمرو، قال: حدثنا ابن وهب، قال: أخبرني حفص بن ميسرة، عن موسى بن عُقبة، عن عطاء بن أبي مروان، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب الأذكار دبر الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (1346); Ibn Khuzaymah authenticated it (745); Ibn Hibban (2026)","chapter_en":"Remembrances after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب التشهد والسلام","group_en":"Chapters on the testimony of faith and the closing greetings","part_no":9,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Abu Marwan narrated that Ka‘b swore to him by the One who split the sea for Musa: “We find in the Torah that Dawud, the Prophet of Allah, would say when he finished his prayer: ‘O Allah, set right for me my religion which You have made my protection, and set right for me my worldly life in which You have placed my livelihood. O Allah, I seek refuge in Your pleasure from Your anger, and I seek refuge in Your pardon from Your retribution, and I seek refuge in You from You. None can withhold what You give, none can give what You withhold, and the wealth or status of a person will not benefit him against You.’” He said: Ka‘b told me that Suhayb told him that Muhammad ﷺ used to say these words when he finished his prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8454],"tks":"حسن: رواه النسائي (1346)، وصححه ابن خزيمة (745)، ورواه ابن حبان (2026)."},{"num":2231,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الأَنْصَارِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَؤُمُّ الْقَوْمَ، أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ، فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَعْلَمُهُمْ بِالسُّنَّةِ، فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً فَأَقْدَمُهُمْ هِجْرَةً، فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً، فَأَقْدَمُهُمْ سِلْمًا، وَلَا يَؤُمَّنَّ الرَّجُلُ الرَّجُلَ فِي سُلْطَانِهِ، وَلَا يَقْعُدْ فِي بَيْتِهِ عَلَى تَكْرِمَتِهِ إِلَّا بِإِذْنِهِ. وَفِي رِوَايَةِ: مَكَانَ سِلْمًا، سِنًّا."],"takhrij":"صحيح: رواه مسلم في المساجد (673) من طريق أبي خالد الأحمر، عن الأعمش، عن إسماعيل بن رَجاء، عن أوس بن ضَمْعَجٍ، عن أبي مسعود الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب من أحق بالإمامة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (673)","chapter_en":"Who has the most right to lead","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari reported that the Messenger of Allah ﷺ said: “The one who should lead a people is the one who recites the Book of Allah best. If they are equal in recitation, then the most knowledgeable of them in the Sunnah. If they are equal in the Sunnah, then the one who migrated earlier. If they are equal in migration, then the one who accepted Islam earlier.” In another narration: “the older in age.” “And a man should not lead another man in his place of authority, and he should not sit in his home in his special seat except with his permission.”"]},"buhuth":{"en":["“Silman” means: earlier in Islam (i.e., earlier acceptance of Islam)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (673)."},{"num":2232,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَانُوا ثَلَاثَةً فَلْيَؤُمَّهُمْ أَحَدُهُمْ، وَأَحَقُّهُمْ بِالإِمَامَةِ أَقْرَؤُهُمْ."],"takhrij":"صحيح: رواه مسلم في المساجد (672) عن قتيبة بن سعيد، حدثنا أبو عوانة، عن قتادة، عن أبي نضرة، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب من أحق بالإمامة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (672)","chapter_en":"Who has the most right to lead","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Prophet ﷺ said: “If they are three, then let one of them lead them. The one most entitled to lead is the one who recites best.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (672)."},{"num":2233,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَنَحْنُ شَبَبَةٌ مُتَقَارِبُونَ، فَأَقَمْنَا عِنْدَهُ عِشْرِينَ لَيْلَةً، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، رَحِيمًا رَقِيقًا. فَظَنَّ أَنَّا قَدِ اشْتَقْنَا أَهْلَنَا، فَسَأَلَنَا عَنْ مَنْ تَرَكْنَا مِنْ أَهْلِنَا، فَأَخْبَرْنَاهُ فَقَالَ: ارْجِعُوا إِلَى أَهْلِيكُمْ فَأَقِيمُوا فِيهِمْ، وَعَلِّمُوهُمْ وَمُرُوهُمْ، فَإِذَا حَضَرَتِ الصَّلَاةُ، فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ، ثُمَّ لِيَؤُمَّكُمْ أَكْبَرُكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (631)، ومسلم في المساجد (674) كلاهما من طريق أيوب، عن أبي قلابة، عن مالك بن الحويرث فذكره.","grade":"متفق عليه","chapter_ar":"باب تقديم ذوي السِّنِّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (631), Muslim (674)","chapter_en":"Giving precedence to those older in age","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Malik ibn al-Huwayrith said: We came to the Messenger of Allah ﷺ while we were young men of similar age, and we stayed with him for twenty nights. The Messenger of Allah ﷺ was merciful and gentle. He thought we had longed for our families, so he asked us about those we left behind, and we told him. He said: “Return to your families, stay among them, teach them, and command them. When prayer time comes, let one of you call the adhan, then let the oldest of you lead.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13912],"tks":"متفق عليه: رواه البخاري (631)، مسلم (674)."},{"num":2234,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ قَالَتْ (فَذَكَرَهَا فِي حَدِيثِ طَوِيل): فَأَرْسَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَبِي بَكْرٍ بِأَنْ يُصَلِّيَ بِالنَّاسِ ، فَأَتَاهُ الرَّسُولُ فَقَالَ : إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تُصَلِّيَ بِالنَّاسِ ، فَقَالَ أَبُو بَكْرٍ : وَكَانَ رَجُلًا رَقِيقًا ، يَا عُمَرُ صَلِّ بِالنَّاسِ ، فَقَالَ لَهُ عُمَرُ : أَنْتَ أَحَقُّ بِذَلِكَ ، فَصَلَّى أَبُو بَكْرٍ تِلْكَ الْأَيَّامَ... الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (687)، ومسلم في الصلاة (418) كلاهما عن أحمد بن عبدالله بن يونس، حدثنا زائدة، حدثنا موسى بن أبي عائشة، عن عبيدالله بن عبدالله بن عتبة قال: دخلت على عائشة فقلت: ألا تحدثيني عن مرض رسول الله صلى الله عليه وسلم ؟ قالت: بلى، ثَقُل النبيّ صلى الله عليه وسلم فقال: أصَلَّى الناس؟ فذكرت القصة التي ستأتي في سيرة النبيّ صلى الله عليه وسلم .","grade":"متفق عليه","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (687), Muslim (418)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, reported that the Prophet ﷺ sent word to Abu Bakr to lead the people in prayer during the illness in which he died. The messenger came to Abu Bakr and said: “The Messenger of Allah ﷺ commands you to lead the people in prayer.” Abu Bakr—who was a soft-hearted man—said: “O ‘Umar, lead the people.” ‘Umar said to him: “You have more right to that.” So Abu Bakr led those days."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (687)، مسلم (418)."},{"num":2235,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ لِلنَّاسِ فَقَالَتْ عَائِشَةُ: إِنَّ أَبَا بَكْرٍ يَا رَسُولَ اللَّهِ، إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعِ النَّاسَ مِنَ الْبُكَاءِ. فَمُرْ عُمَرَ فَلْيُصَلِّ لِلنَّاسِ، قَالَ: مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ لِلنَّاسِ، قَالَتْ عَائِشَةُ: فَقُلْتُ لِحَفْصَةَ: قُولِي لَهُ إِنَّ أَبَا بَكْرٍ إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعِ النَّاسَ مِنَ الْبُكَاءِ، فَمُرْ عُمَرَ فَلْيُصَلِّ لِلنَّاسِ، فَفَعَلَتْ حَفْصَةُ.","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّكُنَّ لَأَنْتُنَّ صَوَاحِبُ يُوسُفَ، مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ لِلنَّاسِ. فَقَالَتْ حَفْصَةُ لِعَائِشَةَ: مَا كُنْتُ لِأُصِيبَ مِنْكِ خَيْرًا."],"takhrij":"صحيح: رواه مالك في قصر الصلاة (83) عن هشام بن عروة، عن أبيه، عن عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (83), al-Bukhari (679)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ said: “Tell Abu Bakr to lead the people in prayer.” ‘A’ishah said: “O Messenger of Allah, when Abu Bakr stands in your place, he will not be able to make the people hear because of weeping. Tell ‘Umar to lead the people.” He said: “Tell Abu Bakr to lead the people.” ‘A’ishah said: I told Hafsah: “Tell him: Abu Bakr, if he stands in your place, will not be able to make the people hear due to weeping, so tell ‘Umar to lead the people.” Hafsah did so, and the Messenger of Allah ﷺ said: “You are like the women of Yusuf. Tell Abu Bakr to lead the people in prayer.” Hafsah then said to ‘A’ishah: “I would never get anything good from you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (83)، البخاري (679)."},{"num":2236,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: مَرِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاشْتَدَّ مَرَضُهُ فَقَالَ: مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، قَالَتْ عَائِشَةُ: إِنَّهُ رَجُلٌ رَقِيقٌ، إِذَا قَامَ مَقَامَكَ لَمْ يَسْتَطِعْ أَنْ يُصَلِّيَ بِالنَّاسِ، قَالَ: مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، فَعَادَتْ فَقَالَ: مُرِي أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، فَإِنَّكُنَّ صَوَاحِبُ يُوسُفَ، فَأَتَاهُ الرَّسُولُ، فَصَلَّى بِالنَّاسِ فِي حَيَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (678)، ومسلم في الصلاة (420) كلاهما من طريق حسين بن علي، عن زائدة، عن عبد الملك بن عمير، قال: حدثني أبو بُردة، عن أبي موسى فذكره.","grade":"متفق عليه","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (678), Muslim (420)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Prophet ﷺ fell ill and his illness became severe. He said: “Tell Abu Bakr to lead the people in prayer.” ‘A’ishah said: “He is a soft-hearted man; if he stands in your place, he will not be able to lead the people in prayer.” He said: “Tell Abu Bakr to lead the people.” She repeated it, so he said: “Tell Abu Bakr to lead the people, for you are like the women of Yusuf.” So the messenger came to him, and Abu Bakr led the people while the Prophet ﷺ was still alive."]}},"tuhfa":{},"full":1,"rep":[8408,9842],"tks":"متفق عليه: رواه البخاري (678)، مسلم (420)."},{"num":2237,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ الْأَنْصَارِيِّ، وَكَانَ تَبِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَخَدَمَهُ وَصَحِبَهُ، أَنَّ أَبَا بَكْرٍ كَانَ يُصَلِّي لَهُمْ فِي وَجَعِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي تُوُفِّيَ فِيهِ حَتَّى إِذَا كَانَ يَوْمُ الِاثْنَيْنِ وَهُمْ صُفُوفٌ فِي الصَّلَاةِ، فَكَشَفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتْرَ الْحُجْرَةِ يَنْظُرُ إِلَيْنَا وَهُوَ قَائِمٌ كَأَنَّ وَجْهَهُ وَرَقَةُ مُصْحَفٍ، ثُمَّ تَبَسَّمَ يَضْحَكُ فَهَمَمْنَا أَنْ نَفْتَتِنَ مِنَ الْفَرَحِ بِرُؤْيَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَكَصَ أَبُو بَكْرٍ عَلَى عَقِبَيْهِ لِيَصِلَ الصَّفَّ وَظَنَّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَارِجٌ إِلَى الصَّلَاةِ، فَأَشَارَ إِلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتِمُّوا صَلَاتَكُمْ وَأَرْخَى السِّتْرَ فَتُوُفِّيَ مِنْ يَوْمِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (680)، ومسلم في الصلاة (419) كلاهما من طريق ابن شهاب، عن أنس بن مالك فذكره واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (680) — wording his; Muslim (419)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Malik al-Ansari—who followed the Prophet ﷺ, served him, and kept his company—reported that Abu Bakr was leading the prayer during the illness in which the Prophet ﷺ died. On Monday, while they were standing in rows in prayer, the Prophet ﷺ lifted the curtain of his room and looked at us while standing. It was as if his face were a page of a mushaf. Then he smiled, laughing. We almost became overcome with joy at seeing him. Abu Bakr stepped back on his heels to join the row, thinking the Prophet ﷺ was coming out to pray. The Prophet ﷺ signaled to us to complete our prayer, then he let down the curtain—and he died later that day."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (680)، واللفظ له، مسلم (419)."},{"num":2238,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: لَمَّا اشْتَدَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعُهُ قِيلَ لَهُ فِي الصَّلَاةِ، فَقَالَ: مُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، قَالَتْ عَائِشَةُ: إِنَّ أَبَا بَكْرٍ رَجُلٌ رَقِيقٌ إِذَا قَرَأَ غَلَبَهُ الْبُكَاءُ، قَالَ: مُرُوهُ فَيُصَلِّي، فَعَاوَدَتْهُ، قَالَ: مُرُوهُ فَيُصَلِّي، إِنَّكُنَّ صَوَاحِبُ يُوسُفَ."],"takhrij":"صحيح: رواه البخاري (682) عن يحيى بن سليمان قال: حدثنا ابن وهب، قال: حدثني يونس، عن ابن شهاب، عن حمزة بن عبدالله بن عمر أنه أخبره عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (682)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: When the illness of the Messenger of Allah ﷺ became severe, he was told: “The prayer.” He said: “Tell Abu Bakr to lead the people in prayer.” ‘A’ishah said: “Abu Bakr is a soft-hearted man; when he recites, weeping overcomes him.” He said: “Tell him to lead.” She repeated it, so he said: “Tell him to lead—indeed you are like the women of Yusuf.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8409,9843,12568],"tks":"صحيح: رواه البخاري (682)."},{"num":2239,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: لَمَّا قُبِضَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتِ الْأَنْصَارُ: مِنَّا أَمِيرٌ وَمِنْكُمْ أَمِيرٌ. فَأَتَاهُمْ عُمَرُ فَقَالَ: يَا مَعْشَرَ الْأَنْصَارِ، أَلَسْتُمْ تَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَمَرَ أَبَا بَكْرٍ أَنْ يَؤُمَّ النَّاسَ؟ فَأَيُّكُمْ تَطِيبُ نَفْسُهُ أَنْ يَتَقَدَّمَ أَبَا بَكْرٍ؟ فَقَالَتِ الْأَنْصَارُ: نَعُوذُ بِاللهِ أَنْ نَتَقَدَّمَ أَبَا بَكْرٍ."],"takhrij":"حسن: رواه النسائي (777) عن إسحاق بن إبراهيم وهنَّاد بن السري، عن حسين بن علي، عن زائدة، عن عاصم، عن زِر، عن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (777), Ahmad (133)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: When the Messenger of Allah ﷺ passed away, the Ansar said: “From us an amir and from you an amir.” ‘Umar came to them and said: “O Ansar, do you not know that the Messenger of Allah ﷺ commanded Abu Bakr to lead the people in prayer? Which of you would feel at ease to go ahead of Abu Bakr?” The Ansar said: “We seek refuge in Allah from going ahead of Abu Bakr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (777)، أحمد (133)."},{"num":2240,"demo":false,"sanad":"","matn":["عَنْ سَالِمِ بْنِ عُبَيْدٍ قَالَ: أُغْمِيَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ، ثُمَّ أَفَاقَ، فَقَالَ: أَحَضَرَتِ الصَّلَاةُ؟ قَالُوا: نَعَمْ، قَالَ: مُرُوا بِلَالًا فَلْيُؤَذِّنْ، وَمُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، ثُمَّ أُغْمِيَ عَلَيْهِ، فَأَفَاقَ، فَقَالَ: أَحَضَرَتِ الصَّلَاةُ؟ قَالُوا: نَعَمْ، قَالَ: مُرُوا بِلَالًا فَلْيُؤَذِّنْ، وَمُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، ثُمَّ أُغْمِيَ عَلَيْهِ، فَأَفَاقَ، فَقَالَ: أَحَضَرَتِ الصَّلَاةُ؟ قَالُوا: نَعَمْ، قَالَ: مُرُوا بِلَالًا فَلْيُؤَذِّنْ، وَمُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ\"، فَقَالَتْ عَائِشَةُ: إِنَّ أَبِي رَجُلٌ أَسِيفٌ، فَإِذَا قَامَ ذَلِكَ الْمَقَامَ يَبْكِي لَا يَسْتَطِيعُ، فَلَوْ أَمَرْتَ غَيْرَهُ، ثُمَّ أُغْمِيَ عَلَيْهِ، فَأَفَاقَ، فَقَالَ: مُرُوا بِلَالًا فَلْيُؤَذِّنْ، وَمُرُوا أَبَا بَكْرٍ فَلْيُصَلِّ بِالنَّاسِ، فَإِنَّكُنَّ صَوَاحِبُ يُوسُفَ أَوْ صَوَاحِبَاتُ يُوسُفَ، قَالَ: فَأُمِرَ بِلَالٌ فَأَذَّنَ، وَأُمِرَ أَبُو بَكْرٍ فَصَلَّى بِالنَّاسِ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَدَ خِفَّةً، فَقَالَ: انْظُرُوا لِي مَنْ أَتَّكِئُ عَلَيْهِ، فَجَاءَتْ بَرِيرَةُ وَرَجُلٌ آخَرُ فَاتَّكَأَ عَلَيْهِمَا، فَلَمَّا رَآهُ أَبُو بَكْرٍ ذَهَبَ لِيَنْكِصَ، فَأَوْمَأَ إِلَيْهِ أَنِ اثْبُتْ مَكَانَكَ، ثُمَّ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى جَلَسَ إِلَى جَنْبِ أَبِي بَكْرٍ حَتَّى قَضَى أَبُو بَكْرٍ صَلَاتَهُ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُبِضَ.","قَالَ أَبُو عَبْد اللَّهِ: هَذَا حَدِيثٌ غَرِيبٌ، لَمْ يُحَدِّثْ بِهِ غَيْرُ نَصْرِ بْنِ عَلِيٍّ."],"takhrij":"صحيح: رواه ابن ماجه (1234)، والترمذي في الشمائل (379) كلاهما عن نصر بن علي الجهضميّ، حدثنا عبدالله بن داود، قال: حدثنا سلمة بن نُبَيط، عن نعيم بن أبي هند، عن نُبيط بن شريط، عن سالم بن عبيد فذكر مثله.","grade":"صحيح","chapter_ar":"باب تقديم أهل العلم والفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1234); al-Tirmidhi in al-Shama’il (379)","chapter_en":"Giving precedence to people of knowledge and virtue","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Salim ibn ‘Ubayd said: The Messenger of Allah ﷺ fainted during his illness, then regained consciousness and said: “Has the prayer time come?” They said: “Yes.” He said: “Tell Bilal to call the adhan, and tell Abu Bakr to lead the people in prayer.” Then he fainted again, then regained consciousness and said: “Has the prayer time come?” They said: “Yes.” He said: “Tell Bilal to call the adhan, and tell Abu Bakr to lead the people in prayer.” Then he fainted again, then regained consciousness and said: “Has the prayer time come?” They said: “Yes.” He said: “Tell Bilal to call the adhan, and tell Abu Bakr to lead the people in prayer.” ‘A’ishah said: “Abu Bakr is a tender-hearted man; if he stands in that place, he will weep and be unable (to lead). If only you would command someone else.” Then he fainted again, and when he awoke he said: “Tell Bilal to call the adhan, and tell Abu Bakr to lead the people in prayer. You are like the women of Yusuf—or the female companions of Yusuf.” Bilal was commanded and called the adhan, and Abu Bakr was commanded and led the people in prayer. Then the Messenger of Allah ﷺ felt some strength and said: “Find for me someone I can lean on.” Barirah and another man came and he leaned on them. When Abu Bakr saw him, he began to step back, but the Prophet signaled to him: “Stay where you are.” Then the Messenger of Allah ﷺ came and sat beside Abu Bakr until Abu Bakr completed the prayer. Then the Messenger of Allah ﷺ passed away."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1234)، الترمذي في الشمائل (379)."},{"num":2241,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَقُومَ الْإِمَامُ فَوْقَ شَيْءٍ وَالنَّاسُ خَلْفَهُ يَعْنِي أَسْفَلَ مِنْهُ."],"takhrij":"حسن: رواه الدّارقطني (1882) عن أحمد بن محمد بن زياد، ثنا محمد بن غالب، ثنا زكريا بن يحيى الواسطي زحمويه، ثنا زياد بن عبدالله بن الطفيل، عن الأعمش، عن إبراهيم، عن همام، عن أبي مسعود الأنصاري فذكره مثله.","grade":"حسن","chapter_ar":"باب النهي أن يقوم الإمام فوق شيء والناس خلفه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Daraqutni (2/88); al-Hakim (1/210)","chapter_en":"Prohibition of the imam standing above while people are below","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari said: The Messenger of Allah ﷺ forbade the imam from standing on something elevated while the people behind him are below him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (1882)، الحاكم (1/210)."},{"num":2242,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمِ بْنِ دِينَارٍ أَنَّ رِجَالًا أَتَوْا سَهْلَ بْنَ سَعْدٍ السَّاعِدِيَّ وَقَدِ امْتَرَوْا فِي الْمِنْبَرِ مِمَّ عُودُهُ فَسَأَلُوهُ عَنْ ذَلِكَ فَقَالَ: وَاللَّهِ إِنِّي لَأَعْرِفُ مِمَّا هُوَ وَلَقَدْ رَأَيْتُهُ أَوَّلَ يَوْمٍ وُضِعَ وَأَوَّلَ يَوْمٍ جَلَسَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى فُلَانَةَ امْرَأَةٍ قَدْ سَمَّاهَا سَهْلٌ مُرِي غُلَامَكِ النَّجَّارَ أَنْ يَعْمَلَ لِي أَعْوَادًا أَجْلِسُ عَلَيْهِنَّ إِذَا كَلَّمْتُ النَّاسَ، فَأَمَرَتْهُ فَعَمِلَهَا مِنْ طَرْفَاءِ الْغَابَةِ ثُمَّ جَاءَ بِهَا، فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِهَا فَوُضِعَتْ هَا هُنَا،\" ثُمَّ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى عَلَيْهَا وَكَبَّرَ وَهُوَ عَلَيْهَا، ثُمَّ رَكَعَ وَهُوَ عَلَيْهَا، ثُمَّ نَزَلَ الْقَهْقَرَى فَسَجَدَ فِي أَصْلِ الْمِنْبَرِ، ثُمَّ عَادَ فَلَمَّا فَرَغَ أَقْبَلَ عَلَى النَّاسِ، فَقَالَ: أَيُّهَا النَّاسُ إِنَّمَا صَنَعْتُ هَذَا لِتَأْتَمُّوا وَلِتَعَلَّمُوا صَلَاتِي."],"takhrij":"متفق عليه: رواه البخاري في الجمعة (917)، ومسلم في المساجد (544) كلاهما عن قتيبة بن سعيد قال: حدثنا يعقوب بن عبدالرحمن بن محمد ابن عبدالله بن عبدٍ القارئ القرشي الإسكندراني قال: حدثنا أبو حازم بن دينار فذكر مثله، واللفظ للبخاري. وفي رواية: فعمل هذه الثلاث درجات.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز ذلك للتعليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (917), Muslim (544)","chapter_en":"Permissibility of standing elevated for teaching","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Abu Hazim ibn Dinar said: Some men came to Sahl ibn Sa‘d al-Sa‘idi, disputing about what wood the pulpit was made from. They asked him, and he said: “By Allah, I know what it was made from. I saw it the first day it was placed and the first day the Messenger of Allah ﷺ sat on it. The Messenger of Allah ﷺ sent to a woman—Sahl named her—saying: ‘Tell your carpenter servant to make for me wooden pieces that I can sit on when I speak to the people.’ She commanded him and he made it from tamarisk wood from al-Ghabah. Then he brought it and she sent word to the Messenger of Allah ﷺ, so he ordered it to be placed here. Then I saw the Messenger of Allah ﷺ pray on it, saying “Allāhu akbar” while on it, then bowing while on it, then he stepped down backward and prostrated at the base of the pulpit, then returned. When he finished, he turned to the people and said: ‘O people, I only did this so that you would follow me and learn my prayer.’”"]},"buhuth":{"en":["“Amataru” means they argued and disputed. “Tarfā’ al-Ghābah” refers to tamarisk trees; al-Ghābah was a wooded area toward the direction of the Levant from Madinah. This hadith shows that it is permissible for the imam to be in an elevated spot when the purpose is to teach people; otherwise, it is disliked."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3296],"tks":"متفق عليه: رواه البخاري (917)، مسلم (544)."},{"num":2243,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ سَلَمَةَ قَالَ: كُنَّا بِمَاءٍ مَمَرَّ النَّاسِ، وَكَانَ يَمُرُّ بِنَا الرُّكْبَانُ، فَنَسْأَلُهُمْ: مَا لِلنَّاسِ، مَا لِلنَّاسِ، مَا هَذَا الرَّجُلُ؟ فَيَقُولُونَ: يَزْعُمُ أَنَّ اللَّهَ أَرْسَلَهُ أَوْحَى إِلَيْهِ، أَوْ أَوْحَى اللَّهُ بِكَذَا، فَكُنْتُ أَحْفَظُ ذَلِكَ الْكَلَامَ وَكَأَنَّمَا يُقَرُّ فِي صَدْرِي، وَكَانَتْ الْعَرَبُ تَلَوَّمُ بِإِسْلَامِهِمُ الْفَتْحَ، فَيَقُولُونَ: اتْرُكُوهُ وَقَوْمَهُ، فَإِنَّهُ إِنْ ظَهَرَ عَلَيْهِمْ فَهُوَ نَبِيٌّ صَادِقٌ، فَلَمَّا كَانَتْ وَقْعَةُ أَهْلِ الْفَتْحِ بَادَرَ كُلُّ قَوْمٍ بِإِسْلَامِهِمْ، وَبَدَرَ أَبِي قَوْمِي بِإِسْلَامِهِمْ، فَلَمَّا قَدِمَ، قَالَ: جِئْتُكُمْ وَاللَّهِ مِنْ عِنْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَقًّا، فَقَالَ:\" صَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا، وَصَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا، فَإِذَا حَضَرَتِ الصَّلَاةُ، فَلْيُؤَذِّنْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْثَرُكُمْ قُرْآنًا\"، فَنَظَرُوا فَلَمْ يَكُنْ أَحَدٌ أَكْثَرَ قُرْآنًا مِنِّي لِمَا كُنْتُ أَتَلَقَّى مِنَ الرُّكْبَانِ، فَقَدَّمُونِي بَيْنَ أَيْدِيهِمْ وَأَنَا ابْنُ سِتٍّ أَوْ سَبْعِ سِنِينَ، وَكَانَتْ عَلَيَّ بُرْدَةٌ كُنْتُ إِذَا سَجَدْتُ تَقَلَّصَتْ عَنِّي، فَقَالَتِ امْرَأَةٌ مِنَ الْحَيِّ: أَلَا تُغَطُّوا عَنَّا اسْتَ قَارِئِكُمْ؟ فَاشْتَرَوْا، فَقَطَعُوا لِي قَمِيصًا فَمَا فَرِحْتُ بِشَيْءٍ فَرَحِي بِذَلِكَ الْقَمِيصِ."],"takhrij":"صحيح: رواه البخاري في المغازي (4302) عن سليمان بن حرب، حدثنا حماد بن زيد، عن أيوب، عن أبي قلابة، عن عمرو بن سلمة قال: قال لي أبو قِلابة: ألا تلقاه فتسأله؟ قال: فلقيتُه فسألتُه فقالَ: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب إمامة الغلام المميز قبل أن يحتلم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4302).","chapter_en":"A discerning boy leading prayer before puberty","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Salamah reported:Abū Qilābah said to me:“Why do you not meet him and ask him?” So I met him and asked him, and he said:“We lived by a watering place situated along the route traveled by the people. Travelers would pass by us, and we would ask them:‘What is happening with the people? What is happening? Who is this man?’They would reply:‘He claims that Allah has sent him and that revelation has been sent to him,’ or, ‘Allah has revealed such-and-such.’I would memorize those words, and it was as though they were firmly fixed in my chest.The Arabs used to delay accepting Islam until the Conquest. They would say:‘Leave him and his people. If he defeats them, then he is a true Prophet.’When the Conquest took place, every tribe hurried to embrace Islam, and my father hastened with my people to accept Islam.When he returned, he said:‘By Allah, I have come to you truly from the Prophet ﷺ. He said:“Pray such-and-such prayer at such-and-such time, and pray such-and-such prayer at such-and-such time. When the time for prayer arrives, let one of you call the adhān, and let the one among you who knows the most Qur’an lead you.”’They looked and found no one who knew more Qur’an than I did because of what I had learned from the travelers. So they put me forward to lead them while I was six or seven years old.I wore a cloak which would draw up when I prostrated.A woman from the tribe said:‘Will you not cover from us the backside of your reciter?’So they bought cloth and made a shirt for me. I had never been happier about anything than I was about that shirt.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4302)."},{"num":2244,"demo":false,"sanad":"","matn":["عَنْ مَحْمُودِ بْنِ الرَّبِيعِ الأَنْصَارِيِّ، أَنَّ عِتْبَانَ بْنَ مَالِكٍ، كَانَ يَؤُمُّ قَوْمَهُ وَهْوَ أَعْمَى."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (86) عن ابن شهاب، عن محمود ابن الربيع فذكره. ورواه البخاري في الأذان (667) عن إسماعيل، عن مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إمامة الأعمى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (86), al-Bukhari (667), Muslim (33)","chapter_en":"Reports about a blind person leading the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Mahmud ibn al-Rabi‘ al-Ansari reported that ‘Itban ibn Malik used to lead his people in prayer while he was blind."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (86)، البخاري (667)، مسلم (33)."},{"num":2245,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ؛ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَخْلَفَ ابْنَ أُمِّ مَكْتُومٍ عَلَى الْمَدِينَةِ يُصَلِّي بِالنَّاسِ."],"takhrij":"حسن: رواه أبو يعلى - المقصد العلى- (306) وعنه البيهقي في المعرفة (5768) عن أمية بن بِسْطام، ثنا يزيد بن زُريع، ثنا حبيب المعلم، عن هشام ابن عروة، عن أبيه، عن عائشة فذكرت مثله.","grade":"حسن","chapter_ar":"باب ما جاء في إمامة الأعمى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Ya‘la (al-Maqsad al-‘Ali, 306); Ibn Hibban authenticated it (2134)","chapter_en":"Reports about a blind person leading the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ appointed Ibn Umm Maktum as deputy over Madinah to lead the people in prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (المقصد العلي، 306)، وصححه ابن حبان (2134)."},{"num":2246,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَخْلَفَ ابْنَ أُمِّ مَكْتُومٍ يَؤُمُّ النَّاسَ وَهُوَ أَعْمَى."],"takhrij":"حسن: رواه أبو داود (595) عن محمد بن عبدالرحمن العنبري أبي عبدالله، حدثنا ابن مهدي، حدثنا عمران القطان، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إمامة الأعمى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (595)","chapter_en":"Reports about a blind person leading the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ appointed Ibn Umm Maktum to lead the people in prayer while he was blind."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (595)."},{"num":2247,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللهِ بْنِ عُمَيْرٍ، أَنَّهُ كَانَ إِمَامَ بَنِي خَطْمَةَ، وَهُوَ أَعْمَى عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَجَاهَدَ مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ أَعْمَى."],"takhrij":"صحيح: رواه أبو نعيم في معرفة الصحابة (4392) وابن قانع (548) كلاهما من طريق جرير، عن هشام بن عروة، عن أبيه، عن عبد الله بن عمير، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إمامة الأعمى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Nu‘aym in Ma‘rifat al-Sahabah (4392); Ibn Qani‘ (2/99)","chapter_en":"Reports about a blind person leading the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["‘Abdullah ibn ‘Umayr—the imam of Banu Khatmah—was the imam of Banu Khatmah during the time of the Messenger of Allah ﷺ while he was blind, and he also went out with him on campaign while blind."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو نعيم في معرفة الصحابة (4392)، وابن قانع (548)."},{"num":2248,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: لَمَّا قَدِمَ الْمُهَاجِرُونَ الأَوَّلُونَ الْعُصْبَةَ ـ مَوْضِعٌ بِقُبَاءٍ ـ قَبْلَ مَقْدَمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَؤُمُّهُمْ سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ، وَكَانَ أَكْثَرَهُمْ قُرْآنًا."],"takhrij":"صحيح: رواه البخاري في الأذان (692) عن إبراهيم بن المنذر قال: حدثنا أنس بن عياض، عن عبيدالله، عن نافع، عن ابن عمر فذكره. ورواه أبو داود (588) عن الهيثم بن خالد الجهني، حدثنا ابن نمير، عن عبيدالله به وزاد الهيثم: وفيهم عمر بن الخطاب، وأبو سلمة بن عبدالأسد .","grade":"صحيح","chapter_ar":"باب إمامة العبد والمولى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (692), Abu Dawud (588)","chapter_en":"A servant or freedman leading the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Umar said: When the first emigrants arrived at al-‘Usbah (a place in Quba’) before the Messenger of Allah ﷺ arrived, Salim—the freedman of Abu Hudhayfah—used to lead them in prayer, and he knew the most Qur’an among them."]}},"tuhfa":{},"full":1,"rep":[10203],"tks":"صحيح: رواه البخاري (692)، أبو داود (588)."},{"num":2249,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ وَاثِلَةَ؛  أَنَّ نَافِعَ بْنَ عَبْدِ الْحَارِثِ لَقِيَ عُمَرَ بِعُسْفَانَ. - وَكَانَ عُمَرُ يَسْتَعْمِلُهُ عَلَى مَكَّةَ. - فَقَالَ: مَنِ اسْتَعْمَلْتَ عَلَى أَهْلِ الْوَادِي؟ فَقَالَ: ابْنَ أَبْزَى. قَالَ: وَمَنِ ابْنُ أَبْزَى؟ قَالَ: مَوْلًى مِنْ مَوَالِينَا. قَالَ: فَاسْتَخْلَفْتَ عَلَيْهِمْ مَوْلًى، قَالَ: إِنَّهُ قَارِئٌ لِكِتَابِ اللهِ عَزَّ وَجَلَّ. وَإِنَّهُ عَالِمٌ بِالْفَرَائِضِ.","قَالَ عُمَرُ: أَمَا إِنَّ نَبِيَّكُمْ قَدْ قَالَ: إِنَّ اللهَ يَرْفَعُ بِهَذَا الْكِتَابِ أَقْوَامًا، وَيَضَعُ بِهِ آخَرِينَ .."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (817) عن زهير بن حرب، حدثنا يعقوب بن إبراهيم، حدثني أبي، عن ابن شهاب، عن عامر بن واثلة فذكره.","grade":"صحيح","chapter_ar":"باب إمامة العبد والمولى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (817)","chapter_en":"A servant or freedman leading the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["‘Amir ibn Wathilah said: Nafi‘ ibn ‘Abd al-Harith met ‘Umar at ‘Usfan—while ‘Umar had appointed him over Makkah. ‘Umar asked: “Whom did you appoint over the people of the valley?” He said: “Ibn Abza.” ‘Umar said: “And who is Ibn Abza?” He said: “A freedman from our freedmen.” ‘Umar said: “So you appointed a freedman over them?” He said: “He is a reciter of the Book of Allah, Mighty and Majestic, and he is knowledgeable in the laws of inheritance.” ‘Umar said: “Indeed, your Prophet ﷺ said: ‘Allah raises some people by this Book and lowers others by it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (817)."},{"num":2250,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُصَلُّونَ لَكُمْ، فَإِنْ أَصَابُوا فَلَكُمْ، وَإِنْ أَخْطَئُوا فَلَكُمْ وَعَلَيْهِمْ."],"takhrij":"صحيح: رواه البخاري في الأذان (694) عن الفضل بن سهل قال: حدثنا الحسن بن موسى الأشيب، قال: حدثنا عبد الرحمن بن عبد الله بن دينار، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إمامة المفتون والمبتدع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (694)","chapter_en":"Leading prayer by one involved in tribulation or by an innovator","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “They lead you in prayer; if they are correct, it is for you; and if they err, it is for you and against them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (694)."},{"num":2251,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ خِيَارٍ، أَنَّهُ دَخَلَ عَلَى عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ وَهْوَ مَحْصُورٌ، فَقَالَ: إِنَّكَ إِمَامُ عَامَّةٍ، وَنَزَلَ بِكَ مَا تَرَى وَيُصَلِّي لَنَا إِمَامُ فِتْنَةٍ، وَنَتَحَرَّجُ. فَقَالَ: الصَّلاَةُ أَحْسَنُ مَا يَعْمَلُ النَّاسُ، فَإِذَا أَحْسَنَ النَّاسُ فَأَحْسِنْ مَعَهُمْ، وَإِذَا أَسَاءُوا فَاجْتَنِبْ إِسَاءَتَهُمْ."],"takhrij":"صحيح: قال البخاري في الأذان (695) وقال لنا محمد بن يوسف، حدثنا الأوزاعي، حدثنا الزهري، عن حميد بن عبد الرحمن، عن عبيد الله بن عدي بن خيار فذكره.","grade":"صحيح","chapter_ar":"باب إمامة المفتون والمبتدع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (695)","chapter_en":"Leading prayer by one involved in tribulation or by an innovator","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["‘Ubaydullah ibn ‘Adi ibn Khiyar said that he entered upon ‘Uthman ibn ‘Affan (may Allah be pleased with him) while he was under siege and said: “You are the leader of the people, and what we see has happened to you. An imam of turmoil leads us in prayer, and we feel uneasy about it.” He said: “Prayer is the best thing people do. If people do good, then do good with them; and if they do wrong, then avoid their wrongdoing.”"]},"buhuth":{"en":["The phrase “an imam of turmoil” was interpreted by some as referring to a specific leader among those who besieged ‘Uthman, and others said it referred to someone else. The report also indicates that the prayer behind such a person remains valid, since ‘Uthman did not invalidate their prayers and emphasized that prayer is among the best deeds. Scholars also discussed this under the broader issue of praying behind a person with innovation, generally allowing it unless the innovation involves Rafḍ or manifest shirk."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (695)."},{"num":2252,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: أُقِيمَتِ الصَّلاَةُ، وَعُدِّلَتِ الصُّفُوفُ قِيَامًا، فَخَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا قَامَ فِي مُصَلاَّهُ ذَكَرَ أَنَّهُ جُنُبٌ، فَقَالَ لَنَا: مَكَانَكُمْ. ثُمَّ رَجَعَ فَاغْتَسَلَ، ثُمَّ خَرَجَ إِلَيْنَا وَرَأْسُهُ يَقْطُرُ، فَكَبَّرَ فَصَلَّيْنَا مَعَهُ.","وَفِي رِوَايَةِ: فَعَدَّلْنَا الصُّفُوفَ، قَبْلَ أَنْ يَخْرُجَ."],"takhrij":"متفق عليه: رواه البخاري في الغسل (275) واللفظ له، ومسلم في المساجد (605) كلاهما من طريق يونس، عن الزهري، عن أبي سلمة، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب يتذكر الإمام أنه جنب بعد أن أقيمت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (275) — wording his; Muslim (605)","chapter_en":"The imam remembers he is in a state of major ritual impurity after the prayer has been established","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah said: The prayer was established and the rows were straightened while standing. The Messenger of Allah ﷺ came out to us, and when he stood in his place of prayer he remembered that he was in a state of major impurity. He said to us: “Stay where you are.” Then he went back, performed ghusl, then came out to us with water dripping from his head. He then said “Allāhu akbar” and we prayed with him. In another narration: We straightened the rows before he came out."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1502],"tks":"متفق عليه: رواه البخاري (275)، واللفظ له، مسلم (605)."},{"num":2253,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ فِي صَلاَةِ الْفَجْرِ فَأَوْمَأَ بِيَدِهِ: أَنْ مَكَانَكُمْ ثُمَّ جَاءَ وَرَأْسُهُ يَقْطُرُ فَصَلَّى بِهِمْ."],"takhrij":"صحيح: رواه أبو داود (233)، وأحمد (20420)، وابن خزيمة (1629)، وابن حبان (2235)، والبيهقي (4063) كلهم من طريق حماد بن سلمة، عن زياد الأعلم، عن الحسن، عن أبي بكرة فذكره.واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب يتذكر الإمام أنه جنب بعد أن يكبر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (233) — wording his; Ahmad (20420); Ibn Khuzaymah (1629); Ibn Hibban (2235)","chapter_en":"The imam remembers he is in a state of major impurity after beginning with the opening declaration","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Abu Bakrah reported that the Messenger of Allah ﷺ began the dawn prayer and gestured with his hand: “Stay where you are.” Then he came back with water dripping from his head and led them in prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (233)، واللفظ له، أحمد (20420)، ابن خزيمة (1629)، ابن حبان (2235)."},{"num":2254,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلاَثَةٌ لاَ تَرْتَفِعُ صَلاَتُهُمْ فَوْقَ رُءُوسِهِمْ شِبْرًا. رَجُلٌ أَمَّ قَوْمًا وَهُمْ لَهُ كَارِهُونَ، وَامْرَأَةٌ بَاتَتْ وَزَوْجُهَا عَلَيْهَا سَاخِطٌ، وَأَخَوَانِ مُتَصَارِمَانِ."],"takhrij":"حسن: رواه ابن ماجه (971) قال: حدثنا محمد بن عمر بن هيَّاج، قال: حدثنا يحيى بن عبدالرحمن الأرحبي، قال: حدثنا عبيدة بن الأسود، عن القاسم بن الوليد، عن المنهال بن عمرو، عن سعيد بن جبير، عن ابن عباس فذكر الحديث.","grade":"حسن","chapter_ar":"باب من أمَّ قوماً وهم له كارهون","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (971)","chapter_en":"One who leads people while they dislike him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Three— their prayer is not raised above their heads by even a handspan: a man who leads people while they dislike him, a woman who spends the night while her husband is displeased with her, and two brothers who have cut each other off.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6323],"tks":"حسن: رواه ابن ماجه (971)."},{"num":2255,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اثْنَانِ لَا تُجَاوِزُ صَلَاتُهُمَا رُءُوسَهُمَا: عَبْدٌ آبِقٌ مِنْ مَوَالِيهِ حَتَّى يَرْجِعَ، وَامْرَأَةٌ عَصَتْ زَوْجَهَا حَتَّى تَرْجِعَ."],"takhrij":"حسن: رواه الطبراني في الأوسط والصغير –مجمع البحرين (2313)، والحاكم (7330) كلاهما من طريق عمر بن عبيد الطنافسي، عن إبراهيم بن مهاجر، عن نافع، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب من أمَّ قوماً وهم له كارهون","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Awsat and al-Saghir (as cited in Majma‘ al-Bahrayn 2313); al-Hakim (7330)","chapter_en":"One who leads people while they dislike him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “Two— their prayer does not go beyond their heads: a runaway slave from his masters until he returns to them, and a woman who disobeys her husband until she returns (to obedience).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط والصغير (كما في مجمع البحرين 2313)، والحاكم (7330)."},{"num":2256,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ ، يَرْفَعُهُ: ثَلاثَةٌ لا تُقْبَلُ مِنْهُمْ صَلاةٌ، ، وَلا تَصْعَدُ إِلَى السَّمَاءِ، ، وَلا تُجَاوِزُ رُءُوسَهُمْ : رَجُلٌ أَمَّ قَوْمًا وَهُمْ لَهُ كَارِهُونَ، ، وَرَجُلٌ صَلَّى عَلَى جَنَازَةٍ وَلَمْ يُؤْمَرْ، ، وَامْرَأَةٌ دَعَاهَا زَوْجُهَا مِنَ اللَّيْلِ فَأَبَتْ عَلَيْهِ."],"takhrij":"حسن: رواه ابن خزيمة (1519) عن عيسى بن إبراهيم، نا ابن وهب، عن عمرو بن الحارث، عن يزيد بن أبي حبيب، عن عمرو بن الوليد، عن أنس بن مالك قال: فذكره.","grade":"حسن","chapter_ar":"باب من أمَّ قوماً وهم له كارهون","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (1519)","chapter_en":"One who leads people while they dislike him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Anas narrated it as raised (to the Prophet ﷺ): “Three— no prayer is accepted from them, nor does it rise to the sky, nor does it go beyond their heads: a man who leads people while they dislike him, a man who prayed over a funeral without being instructed (to do so), and a woman whose husband called her at night and she refused.”"]},"buhuth":{"en":["These narrations warn strongly against such wrongdoing. They do not mean the prayer is invalid; rather, “not accepted” means the prayer is not accepted in its full, complete reward."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (1519)."},{"num":2257,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَهَبَ إِلَى بَنِي عَمْرِو بْنِ عَوْفٍ لِيُصْلِحَ بَيْنَهُمْ، فَحَانَتِ الصَّلاَةُ، فَجَاءَ الْمُؤَذِّنُ إِلَى أَبِي بَكْرٍ فَقَالَ: أَتُصَلِّي لِلنَّاسِ فَأُقِيمَ؟ قَالَ: نَعَمْ. فَصَلَّى أَبُو بَكْرٍ، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالنَّاسُ فِي الصَّلاَةِ، فَتَخَلَّصَ حَتَّى وَقَفَ فِي الصَّفِّ، فَصَفَّقَ النَّاسُ، ـ وَكَانَ أَبُو بَكْرٍ لاَ يَلْتَفِتُ فِي صَلاَتِهِ، ـ فَلَمَّا أَكْثَرَ النَّاسُ التَّصْفِيقَ، الْتَفَتَ فَرَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَشَارَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِ امْكُثْ مَكَانَكَ، فَرَفَعَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ يَدَيْهِ، فَحَمِدَ اللَّهَ عَلَى مَا أَمَرَهُ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ ذَلِكَ، ثُمَّ اسْتَأْخَرَ أَبُو بَكْرٍ حَتَّى اسْتَوَى فِي الصَّفِّ، وَتَقَدَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى، فَلَمَّا انْصَرَفَ، قَالَ يَا أَبَا بَكْرٍ، مَا مَنَعَكَ أَنْ تَثْبُتَ إِذْ أَمَرْتُكَ. فَقَالَ أَبُو بَكْرٍ: مَا كَانَ لاِبْنِ أَبِي قُحَافَةَ أَنْ يُصَلِّيَ بَيْنَ يَدَىْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا لِي رَأَيْتُكُمْ أَكْثَرْتُمُ التَّصْفِيقَ؟ مَنْ رَابَهُ شَىْءٌ فِي صَلاَتِهِ فَلْيُسَبِّحْ، فَإِنَّهُ إِذَا سَبَّحَ الْتُفِتَ إِلَيْهِ، وَإِنَّمَا التَّصْفِيقُ لِلنِّسَاءِ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (61) عن أبي حازم سلمة بن دينار، عن سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا تأخر الإمام تقام الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (61), al-Bukhari (684), Muslim (421)","chapter_en":"If the imam is delayed, the prayer may be established","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Sahl ibn Sa‘d al-Sa‘idi reported that the Messenger of Allah ﷺ went to Banu ‘Amr ibn ‘Awf to reconcile between them. When prayer time came, the caller came to Abu Bakr and said: “Will you lead the people so I may establish the prayer?” He said: “Yes.” So Abu Bakr led them. The Messenger of Allah ﷺ arrived while they were praying and made his way until he stood in the row. The people began clapping, while Abu Bakr did not turn around in his prayer. When the clapping increased, Abu Bakr turned and saw the Messenger of Allah ﷺ. The Prophet signaled to him to remain in his place. Abu Bakr raised his hands and praised Allah for what the Messenger of Allah ﷺ commanded him to do, then he stepped back until he was in the row, and the Messenger of Allah ﷺ stepped forward and led the prayer. When he finished, he said: “O Abu Bakr, what prevented you from remaining when I commanded you?” Abu Bakr said: “It is not for the son of Abu Quhafah to lead prayer in front of the Messenger of Allah ﷺ.” The Messenger of Allah ﷺ said: “Why did I see you clapping so much? If something happens to one of you in prayer, let him say ‘Subhan Allah,’ for if he says it, attention will be drawn to him. Clapping is only for women.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (61)، البخاري (684)، مسلم (421)."},{"num":2258,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ أَنَّهُ غَزَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ تَبُوكَ، ، قَالَ الْمُغِيرَةُ: : فَتَبَرَّزَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبَلَ الْغَائِطِ ، فَحَمَلْتُ مَعَهُ إِدَاوَةً قَبْلَ صَلَاةِ الْفَجْرِ.... قَالَ الْمُغِيرَةُ: : فَأَقْبَلْتُ مَعَهُ حَتَّى نَجِدَ النَّاسَ قَدْ قَدَّمُوا عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ يُصَلِّي بِهِمْ ، فَأَدْرَكَ إِحْدَى الرَّكْعَتَيْنِ، ، قَالَ عَبْدُ الرَّزَّاقِ وَابْنُ بَكْرٍ : فَصَلَّى مَعَ النَّاسِ الرَّكْعَةَ الْآخِرَةَ، ، فَلَمَّا سَلَّمَ عَبْدُ الرَّحْمَنِ ، قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُتِمُّ صَلَاتَهُ، ، فَأَفْزَعَ ذَلِكَ الْمُسْلِمِينَ. ، فَأَكْثَرُوا التَّسْبِيحَ، ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ ، أَقْبَلَ عَلَيْهِمْ، ، ثُمَّ قَالَ: : أَحْسَنْتُمْ ، أَوْ قَدْ أَصَبْتُمْ. يَغْبِطُهُمْ أَنْ صَلَّوْا الصَّلَاةَ لِوَقْتِهَا.","وفي رواية: قَالَ الْمُغِيرَةُ : فَأَرَدْتُ تَأْخِيرَ عَبْدِ الرَّحْمَنِ ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : دَعْهُ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (41) عن ابن شهاب، عن عباد بن زياد - من ولد المغيرة بن شعبة، عن أبيه، عن المغيرة بن شعبة. رواه البخاري في الوضوء (203) ورواه الشيخان من غير طريق مالك لأسباب. ذكرتها في المسح على الخفين - عن طريق عروة بن المغيرة، عن أبيه، واللفظ لمسلم (274).","grade":"متفق عليه","chapter_ar":"باب إذا تأخر الإمام تقام الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (41). Also narrated by al-Bukhari and Muslim through other chains; the wording here is Muslim (274).","chapter_en":"If the imam is delayed, the prayer may be established","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Al-Mughirah ibn Shu‘bah reported that he went with the Messenger of Allah ﷺ on the expedition to Tabuk. He said: The Messenger of Allah ﷺ went out to relieve himself, and I carried a water-skin with him before the dawn prayer. Al-Mughirah said: We returned and found that the people had put ‘Abd al-Rahman ibn ‘Awf forward and he was leading them in prayer. The Messenger of Allah ﷺ caught one of the two units, and he prayed the final unit with the people. When ‘Abd al-Rahman ibn ‘Awf gave the taslim, the Messenger of Allah ﷺ stood to complete his prayer. That alarmed the Muslims, and they began saying “Subhan Allah” repeatedly. When the Prophet ﷺ completed his prayer, he turned to them and said: “You did well,” or: “You were correct,” pleased with them that they had prayed the prayer at its proper time.","In another narration, al-Mughirah said: I wanted to delay ‘Abd al-Rahman, but the Prophet ﷺ said: “Leave him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (41)، ورواه البخاري ومسلم من طرق أخرى، واللفظ هنا لمسلم (274)."},{"num":2259,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَكُونُ فِي الْمَسْجِدِ حِينَ تُقَامُ الصَّلَاةُ، فَإِذَا رَآهُمْ قَلِيلًا جَلَسَ، ثُمَّ صَلَّى، وَإِذَا رَآهُمْ جَمَاعَةً صَلَّى.","وفي رواية: أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَخْرُجُ بَعْدَ النِّدَاءِ إِلَى الْمَسْجِدِ، فَإِذَا رَأَى أَهْلَ الْمَسْجِدِ قَلِيلًا جَلَسَ، حَتَّى يَرَى مِنْهُمْ جَمَاعَةً ثُمَّ يُصَلِّي، وَكَانَ إِذَا خَرَجَ فَرَأَى جَمَاعَةً أَقَامَ الصَّلَاةَ."],"takhrij":"صحيح: رواه الحاكم (724) عن أبي محمد أحمد بن عبد الله المزني، ثنا يوسف بن موسى، ثنا محمود بن خالد الدمشقي، و داود بن رشيد قالا : ثنا الوليد بن مسلم، ثنا ابن جريج، عن موسى بن عقبة، عن نافع بن جبير، عن مسعود الزرقي، عن علي بن أبي طالب قال: فذكره.","grade":"صحيح","chapter_ar":"باب يجوز للإمام تأخير الصلاة إذا رأى قلة الحاضرين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Hakim (724). The second narration is in al-Bayhaqi (2/20).","chapter_en":"The imam may delay the prayer if he sees few attendees","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ would be in the mosque when the prayer was established. If he saw them few in number, he would sit, then pray; and if he saw them as a congregation, he would pray. In another narration: The Prophet ﷺ would come out after the call and go to the mosque; if he found the people of the mosque few, he would sit until he saw a group gather, then he would pray. And if he came out and saw a group already present, he would establish the prayer."]},"buhuth":{"en":["The second wording is stronger, supported by the long narration of Jabir ibn ‘Abdullah: if the Prophet ﷺ saw they had gathered, he hastened (the prayer), and if he saw they were late (in gathering), he delayed it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (724). والرواية الثانية عند البيهقي (2283)."},{"num":2260,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا صَلَّى أَحَدُكُمْ لِلنَّاسِ فَلْيُخَفِّفْ، فَإِنَّ مِنْهُمُ الضَّعِيفَ وَالسَّقِيمَ وَالْكَبِيرَ، وَإِذَا صَلَّى أَحَدُكُمْ لِنَفْسِهِ فَلْيُطَوِّلْ مَا شَاءَ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (13) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (13), al-Bukhari (703), Muslim (467). Muslim adds in some routes: “and among them is the child,” and in some narrations: “and among them is one with a need.”","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you leads people in prayer, let him make it light, for among them are the weak, the ill, and the elderly. But when one of you prays by himself, let him lengthen as he wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (13)، والبخاري (703)، ومسلم (467). وزاد مسلم في بعض الطرق: «وفيهم الصبي»، وفي بعض الروايات: «وفيهم ذو الحاجة»."},{"num":2261,"demo":false,"sanad":"","matn":["أَخْبَرَنِي أَبُو مَسْعُودٍ، أَنَّ رَجُلاً، قَالَ: وَاللَّهِ يَا رَسُولَ اللَّهِ إِنِّي لأَتَأَخَّرُ عَنْ صَلاَةِ الْغَدَاةِ مِنْ أَجْلِ فُلاَنٍ مِمَّا يُطِيلُ بِنَا. فَمَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَوْعِظَةٍ أَشَدَّ غَضَبًا مِنْهُ يَوْمَئِذٍ، ثُمَّ قَالَ: إِنَّ مِنْكُمْ مُنَفِّرِينَ، فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ فَلْيَتَجَوَّزْ، فَإِنَّ فِيهِمُ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (702)، ومسلم في الصلاة (466) كلاهما من طريق إسماعيل بن أبي خالد، قال: سمعتُ قيساً، قال: أخبرني أبو مسعود الأنصاري فذكر الحديث، واللفظ للبخاري، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (702) — wording his; Muslim (466)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Abu Mas‘ud reported that a man said: “By Allah, O Messenger of Allah, I delay coming to the dawn prayer because of so-and-so, due to how long he makes it for us.” Abu Mas‘ud said: I never saw the Messenger of Allah ﷺ more angry in an admonition than he was that day. Then he said: “Among you are those who drive people away. So whoever leads the people, let him be brief, for among them are the weak, the elderly, and those with needs.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (702)، واللفظ له، مسلم (466)."},{"num":2262,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله قَالَ: كَانَ مُعَاذُ بْنُ جَبَلٍ يُصَلِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يَرْجِعُ فَيَؤُمُّ قَوْمَهُ، فَصَلَّى الْعِشَاءَ فَقَرَأَ بِالْبَقَرَةِ، فَانْصَرَفَ الرَّجُلُ، فَكَأَنَّ مُعَاذًا تَنَاوَلَ مِنْهُ، فَبَلَغَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: فَتَّانٌ فَتَّانٌ فَتَّانٌ ثَلاَثَ مِرَارٍ أَوْ قَالَ: فَاتِنًا فَاتِنًا فَاتِنٌ وَأَمَرَهُ بِسُورَتَيْنِ مِنْ أَوْسَطِ الْمُفَصَّلِ. قَالَ عَمْرٌو: لاَ أَحْفَظُهُمَا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (701)، ومسلم في الصلاة (465) كلاهما من طريق عمرو بن دينار، عن جابر بن عبدالله به، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (701) and Muslim (465).","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported:Muʿādh ibn Jabal used to pray with the Prophet ﷺ and then return and lead his people in prayer. He prayed ʿIshāʾ and recited Sūrat al-Baqarah, so a man left. It was as though Muʿādh criticized him for doing so.When this reached the Prophet ﷺ, he said:“A cause of trial! A cause of trial! A cause of trial!”three times—or he said:“One who causes trial! One who causes trial! One who causes trial!”He then instructed him to recite two surahs from the middle-length portion of al-Mufaṣṣal.ʿAmr said:“I do not remember which two they were.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (701)، ومسلم (465)."},{"num":2263,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ مُعَاذُ بْنُ جَبَلٍ يَؤُمُّ قَوْمَهُ، فَدَخَلَ حَرَامٌ، وَهُوَ يُرِيدُ أَنْ يَسْقِيَ نَخْلَهُ، فَدَخَلَ المسْجِدَ لِيُصَلِّيَ مَعَ الْقَوْمِ، فَلَمَّا رَأَى مُعَاذًا طَوَّلَ، تَجَوَّزَ فِي صَلَاتِهِ، وَلَحِقَ بِنَخْلِهِ يَسْقِيهِ، فَلَمَّا قَضَى مُعَاذٌ الصَّلَاةَ، قِيلَ لَهُ: إِنَّ حَرَامًا دَخَلَ المسْجِدَ، فَلَمَّا رَآكَ طَوَّلْتَ، تَجَوَّزَ فِي صَلَاتِهِ، وَلَحِقَ بِنَخْلِهِ يَسْقِيهِ، قَالَ: إِنَّهُ لَمُنَافِقٌ، أَيَعْجَلُ عَنْ الصَّلَاةِ مِنْ أَجْلِ سَقْيِ نَخْلِهِ؟ قَالَ: فَجَاءَ حَرَامٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَمُعَاذٌ عِنْدَهُ، فَقَالَ: يَا نَبِيَّ اللَّهِ، إِنِّي أَرَدْتُ أَنْ أَسْقِيَ نَخْلًا لِي، فَدَخَلْتُ الْمَسْجِدَ لِأُصَلِّيَ مَعَ الْقَوْمِ، فَلَمَّا طَوَّلَ، تَجَوَّزْتُ فِي صَلَاتِي، وَلَحِقْتُ بِنَخْلِي أَسْقِيهِ، فَزَعَمَ أَنِّي مُنَافِقٌ، فَأَقْبَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مُعَاذٍ، فَقَالَ: أَفَتَّانٌ أَنْتَ؟ أَفَتَّانٌ أَنْتَ؟ لَا تُطَوِّلْ بِهِمْ، اقْرَأْ بِـ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى، وَالشَّمْسِ وَضُحَاهَا وَنَحْوِهِمَا ."],"takhrij":"صحيح: رواه الإمام أحمد (12247)، والنسائي في الكبرى (11610)، والبزار – كشف الأستار (481) كلهم من طريق إسماعيل بن إبراهيم (هو ابن عُليّة)، وحدثنا عبدالعزيز بن صهيب، عن أنس بن مالك قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (12247); al-Nasa’i in al-Kubra (11610); al-Bazzar in Kashf al-Astar (481)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Malik said: Mu‘adh ibn Jabal used to lead his people in prayer. Ḥarām entered intending to water his date-palms… The Prophet ﷺ said to Mu‘adh: “Are you putting people to trial? Are you putting people to trial? Do not prolong the prayer for them. Recite: ‘Glorify the Name of your Lord, the Most High,’ and ‘By the sun and its brightness,’ and similar surahs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12247)، النسائي في الكبرى (11610)، البزار في كشف الأستار (481)."},{"num":2264,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُوجِزُ الصَّلاَةَ وَيُكْمِلُهَا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (706)، ومسلم في الصّلاة (469) كلاهما من طريق عبد العزيز بن صهيب، عن أنس فذكره واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (706) — wording his; Muslim (469)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ would make the prayer brief while completing it properly. Muslim’s wording: “He would make the prayer brief and complete it.”"]},"buhuth":{"en":["In another wording: “The Messenger of Allah ﷺ was among the lightest of people in prayer while still being complete.” “Briefness with completeness” means performing the minimum that fulfills each pillar and required part—without rushing or neglect."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (706)، واللفظ له، مسلم (469)."},{"num":2265,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  مَا صَلَّيْتُ خَلْفَ أَحَدٍ أَوْجَزَ صَلَاةً مِنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي تَمَامٍ. كَانَتْ صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَقَارِبَةً، وَكَانَتْ صَلَاةُ أَبِي بَكْرٍ مُتَقَارِبَةً. فَلَمَّا كَانَ عُمَرُ بْنُ الْخَطَّابِ مَدَّ فِي صَلَاةِ الْفَجْرِ. وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَامَ حَتَّى نَقُولَ: قَدْ أَوْهَمَ. ثُمَّ يَسْجُدُ وَيَقْعُدُ بَيْنَ السَّجْدَتَيْنِ حَتَّى نَقُولَ: قَدْ أَوْهَمَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (473) عن أبي بكر بن نافع العَبْدي، ثنا بهز، حدثنا حماد، أخبرنا ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (473)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Malik said: I have not prayed behind anyone whose prayer was briefer—while still complete—than the prayer of the Messenger of Allah ﷺ. The Prophet’s prayer was well-balanced and consistent, and Abu Bakr’s prayer was also well-balanced. When ‘Umar ibn al-Khattab led, he lengthened the dawn prayer. The Messenger of Allah ﷺ would say, “Allah hears the one who praises Him,” then remain standing until we would think he had forgotten, then he would prostrate. And he would sit between the two prostrations until we would think he had forgotten."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (473)."},{"num":2266,"demo":false,"sanad":"","matn":["عَنْ طَارِقِ بْنِ أشيم الأشجعي قَالَ: مَا صلّيتُ خلفَ أحدٍ أخفَّ مِنْ صَلَاةً رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي تَمَامٍ."],"takhrij":"حسن: رواه البزار (2770) عن عمار بن خالد الواسطي، أخبرنا القاسم بن مالك المزني، أخبرنا أبو مالك الأشجعي، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bazzar (2770)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Tariq ibn Ashyam al-Ashja‘i said: I have not prayed behind anyone whose prayer was lighter—while still complete—than the prayer of the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (2770)."},{"num":2267,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: مَا صَلَّيْتُ خَلْفَ أَحَدٍ بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَفَّ صَلَاةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي تَمَامٍ."],"takhrij":"حسن: رواه الطبراني في الأوسط – مجمع البحرين (730) عن محمد بن عثمان بن أبي شيبة، حدثنا يحيى بن معين، حدثنا أبو عبيدة الحدّاد (واسمه: عبد الواحد بن واصل)، حدثنا هشام بن حسان، حدثنا بكر بن عبد الله المزني، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: I have not prayed behind anyone after the Messenger of Allah ﷺ whose prayer was lighter—while still complete—than the prayer of the Messenger of Allah ﷺ."]},"buhuth":{"en":["al-Tabarani in al-Awsat (as cited in Majma‘ al-Bahrayn 730)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (كما في مجمع البحرين 730)."},{"num":2268,"demo":false,"sanad":"","matn":["عن عُثْمَانَ بن أَبِي الْعَاصِ الثقفي أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: أُمَّ قَوْمَكَ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي أَجِدُ فِي نَفْسِي شَيْئًا. قَالَ: ادْنُهْ. فَجَلَّسَنِي بَيْنَ يَدَيْهِ، ثُمَّ وَضَعَ كَفَّهُ فِي صَدْرِي بَيْنَ ثَدْيَيَّ. ثُمَّ قَالَ: تَحَوَّلْ، فَوَضَعَهَا فِي ظَهْرِي بَيْنَ كَتِفَيَّ، ثُمَّ قَالَ: أُمَّ قَوْمَكَ! فَمَنْ أَمَّ قَوْمًا فَلْيُخَفِّفْ، فَإِنَّ فِيهِمُ الْكَبِيرَ، وَإِنَّ فِيهِمُ الْمَرِيضَ، وَإِنَّ فِيهِمُ الضَّعِيفَ، وَإِنَّ فِيهِمْ ذَا الْحَاجَةِ. وَإِذَا صَلَّى أَحَدُكُمْ وَحْدَهُ فَلْيُصَلِّ كَيْفَ شَاءَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (468) عن محمد بن عبدالله بن نُمير، قال: حدثنا أبي، حدثنا عمرو بن عثمان، حدثنا موسى بن طلحة، حدثني عثمان بن أبي العاص فذكره.","grade":"صحيح","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (468)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["‘Uthman ibn Abi al-‘As al-Thaqafi reported that the Prophet ﷺ said to him: “Lead your people.” He said: “O Messenger of Allah, I feel something (unease) within myself.” He said: “Come close.” He seated me in front of him, placed his hand on my chest between my breasts, then said: “Turn around,” and he placed it on my back between my shoulder blades. Then he said: “Lead your people. Whoever leads people should make the prayer light, for among them are the elderly, the sick, the weak, and those with needs. And if one of you prays alone, let him pray as he wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10275],"tks":"صحيح: رواه مسلم (468)."},{"num":2269,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ بِالتَّخْفِيفِ، وَيَؤُمُّنَا بِالصَّافَّاتِ."],"takhrij":"حسن: رواه النسائي (826) عن إسماعيل بن مسعود، قال: حدثنا خالد ابن الحارث، عن ابن أبي ذئب، قال: أخبرني الحارث بن عبدالرحمن، عن سالم بن عبدالله، عن عبدالله بن عمر فذكره.","grade":"حسن","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (826); Ibn Khuzaymah authenticated it (1606); Ibn Hibban (1817)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Messenger of Allah ﷺ used to command that the prayer be made light, yet he would lead us (at times) reciting Surat al-Saffat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (826)، وصححه ابن خزيمة (1606)، ورواه ابن حبان (1817)."},{"num":2270,"demo":false,"sanad":"","matn":["عَنْ نَافِعِ بْنِ سَرْجِسَ، قَالَ: عُدْنَا أَبَا وَاقِدٍ الْبَكْرِيَّ، وَقَالَ ابْنُ بَكْرٍ: الْبَدْرِيَّ، فِي وَجَعِهِ الَّذِي مَاتَ فِيهِ، فَسَمِعَهُ يَقُولُ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَفَّ النَّاسِ صَلَاةً عَلَى النَّاسِ، وَأَطْوَلَ النَّاسِ صَلَاةً لِنَفْسِهِ."],"takhrij":"حسن: رواه الإمام أحمد (21899)، والطبراني في الكبير (3310) كلاهما من حديث عبد الرزاق ـ وهو في مصنفه abdrazzaq(3819) ـ وقرنه الإمام أحمد بابن بكر ـ كلاهما عن ابن جريج، أخبرني عبدالله بن عثمان، عن نافع ابن سرجس، قال (فذكره).","grade":"حسن","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (21899); al-Tabarani in al-Kabir (3/250); ‘Abd al-Razzaq (3819)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Nafi‘ ibn Sarjis said: We visited Abu Waqid al-Bakri (and Ibn Bakr said: al-Badri) during the illness in which he died, and I heard him say: The Prophet ﷺ was the lightest of people in prayer when leading others, and the longest of people in prayer when praying by himself."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (21899)، الطبراني في المعجم الكبير (3310)، عبد الرزاق (3819)."},{"num":2271,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بن حَاتِمٍ، أَنَّهُ خَرَجَ إِلَى مَجْلِسِهِمْ، فَأُقِيمَتِ الصَّلاةُ، فَتَقَدَّمَ إِمَامُهُمْ فَأَطَالَ الصَّلاةَ وَالْجُلُوسَ، فَلَمَّا انْصَرَفَ، قَالَ: مَنْ أَمَّنَا مِنْكُمْ، فَلْيُتِمَّ الرُّكُوعَ وَالسُّجُودَ، فَإِنَّ خَلْفَهُ الصَّغِيرَ وَالْكَبِيرَ، وَالْمَرِيضَ، وَابْنَ السَّبِيلِ، وَذَا الحاجَةِ، فَلَمَّا حَضَرَتِ الصَّلاةُ، تَقَدَّمَ عَدِيٌّ، وَأَتَمَّ الرُّكُوعَ وَالسُّجُودَ، وَتَجَوَّزَ فِي الصَّلاةِ، فَلَمَّا انْصَرَفَ، قَالَ: هَكَذَا كُنَّا نُصَلِّي خَلْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"صحيح: رواه أحمد (18261)، والطبراني (17/ح 222)، وابنُ أبي عاصم في الآحاد والمثاني (2489) كلهم من طرقٍ عن يحيى بن الوليد بن مسيّر الطائي قال: أخبرني مُحِلّ الطائي، عن عدي بن حاتم فذكره. والسياق للطبراني، ولفظ أحمد مختصر.","grade":"صحيح","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (18261); al-Tabarani (17/93–94); Ibn Abi ‘Asim in al-Ahad wa al-Mathani (2489)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["‘Adi ibn Hatim reported that he went to their gathering, and the prayer was established. Their imam stepped forward but was slow in bowing, prostration, and sitting. When he finished, ‘Adi said: Whoever among you leads us should complete the bowing and prostration properly, for behind him are the young, the elderly, the sick, the traveler, and the one with a need. When the next prayer came, ‘Adi stepped forward, completed the bowing and prostration properly, and made the prayer brief. When he finished, he said: This is how we used to pray behind the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (18261)، والطبراني (17/ح 222)، وابن أبي عاصم في الآحاد والمثاني (2489)."},{"num":2272,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَجَاوَزُوا فِي الصَّلَاةِ، فَإِنَّ خَلْفَكُمُ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ."],"takhrij":"صحيح: رواه الإمام أحمد (10793) عن يحيى بن حماد، أخبرنا أبو عوانة، عن الأعمش، حدثنا إبراهيم التيمي، عن الحارث بن سويد، عن عبدالله بن مسعود قال: فذكره.","grade":"صحيح","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (10793)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ said: “Be brief in the prayer, for behind you are the weak, the elderly, and those with needs.”"]},"buhuth":{"en":["“Be brief” here means: lighten the prayer—without neglecting what is required."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (10793)."},{"num":2273,"demo":false,"sanad":"","matn":["عَنْ إِبْرَاهِيمَ التَّيْمِيِّ ، قَالَ: : كَانَ أَبِي قَدْ تَرَكَ الصَّلاةَ مَعَنَا، ، قُلْتُ: : مَا لَكَ لا تُصَلِّي مَعَنَا ؟ قَالَ: : إِنَّكُمْ تُخَفِّفُونَ الصَّلاةَ، ، قُلْتُ: : فَأَيْنَ قَوْلُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّ فِيكُمُ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ؟ قَالَ : قَدْ سَمِعْتُ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ يَقُولُ ذَلِكَ، ، ثُمَّ صَلَّى بِنَا ثَلاثَةَ أَضْعَافِ مَا تُصَلُّونَ.","وزاد في روايةٍ: وَكَانَ يَمْكُثُ فِي الرُّكُوعِ وَالسُّجُودِ."],"takhrij":"حسن: رواه ابنُ خزيمة (1607)، والسرّاج في مسنده (241)-تحقيق الأثري، والطبراني في الكبير (10/264)، وفي الأوسط -مجمع البحرين (732)، وابن الأعرابي في معجمه (932) كلهم من طرقٍ عن أبي أحمد الزبيري، حدثنا عبد الجبار بن العباس الشبامي الهمداني، عن عمّار الدهني، عن إبراهيم التيمي فذكره. والزيادة عند الطبراني.","grade":"حسن","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (1607); al-Sarraj in his Musnad (241) (tahqiq al-Athari); al-Tabarani (10/264)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Ibrahim al-Taymi said: My father had stopped praying with us, so I said: “Why don’t you pray with us?” He said: “You make the prayer too light.” I said: “Then what about the Prophet ﷺ’s statement: ‘Among you are the weak, the elderly, and those with needs’?” He said: “I heard ‘Abdullah ibn Mas‘ud say that.” Then he led us in prayer and it was three times as long as you pray. In another narration it adds: He would remain in the bowing and prostration."]}},"tuhfa":{},"voc":["mujamkabir",10456],"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (1607)، والسراج في مسنده (241) بتحقيق الأثري، والطبراني (10/264)."},{"num":2274,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَجَاوَزُوا فِي الصَّلَاةِ، فَإِنَّ خَلْفَكُمُ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ."],"takhrij":"صحيح: رواه الإمام أحمد (10793) عن يحيى بن حماد، أخبرنا أبو عوانة، عن الأعمش، حدثنا إبراهيم التيمي، عن الحارث بن سويد، عن عبدالله بن مسعود قال: فذكره.","grade":"صحيح","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (10793); al-Tabarani in al-Kabir (17/12)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Be brief in the prayer, for behind you are the weak, the elderly, and those with needs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (10793)، الطبراني في المعجم الكبير (17/12)."},{"num":2275,"demo":false,"sanad":"","matn":["عَنْ حَيَّانَ يَعْنِي الْبَارِقِيَّ قَالَ: قِيلَ لِابْنِ عُمَرَ: إِنَّ إِمَامَنَا يُطِيلُ الصَّلَاةَ، فَقَالَ ابْنُ عُمَرَ: رَكْعَتَانِ مِنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَفُّ أَوْ مِثْلُ رَكْعَةٍ مِنْ صَلَاةِ هَذَا."],"takhrij":"حسن: رواه ابن الجعد في مسنده (866، 1358)، وأحمد (5044) كلاهما من حديث شعبة، عن حيّان البارقي قال: فذكره.","grade":"حسن","chapter_ar":"باب أمر الأئمة بتخفيف الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn al-Ja‘d in his Musnad (866, 1358); Ahmad (5044)","chapter_en":"Commanding imams to lighten the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Hayyan al-Bariqi said: It was said to Ibn ‘Umar: “Our imam makes the prayer long.” Ibn ‘Umar said: “Two units of the prayer of the Messenger of Allah ﷺ are lighter than—or equal to—one unit of this man’s prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن الجعد في مسنده (866، 1358)، وأحمد (5044)."},{"num":2276,"demo":false,"sanad":"","matn":["عن أنس قَالَ: مَا صَلَّيْتُ وَرَاءَ إِمَامٍ قَطُّ أَخَفَّ صَلاَةً، وَلاَ أَتَمَّ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنْ كَانَ لَيَسْمَعُ بُكَاءَ الصَّبِيِّ فَيُخَفِّفُ مَخَافَةَ أَنْ تُفْتَنَ أُمُّهُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (708) عن خالد بن مخلد، قال: حدّثنا سليمان بن بلال، قال: حدثنا شريك بن عبدالله (ابن أبي نمر) قال سمعتُ أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب في تخفيف الصلاة عند سماع بكاء الصبي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (708) and also (709); Muslim (469/190) and also (470/192)","chapter_en":"Shortening the prayer when hearing a baby cry","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Anas said: I have never prayed behind an imam whose prayer was lighter—while still more complete—than the Messenger of Allah ﷺ. And if he heard the crying of a baby, he would shorten the prayer out of fear that the mother might be distressed. In another narration: “I begin the prayer intending to make it long, then I hear a baby crying, so I make my prayer brief because I know how intensely the mother feels because of the child’s crying.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (708)، ورواه أيضا bukhari(709)، ومسلم (469/190، 470/192)."},{"num":2277,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنِّي لأَقُومُ فِي الصَّلاَةِ أُرِيدُ أَنْ أطوِّل فِيهَا، فَأَسْمَعُ بُكَاءَ الصَّبِيِّ فأتجوَّزُ فِي صَلاَتِي كَرَاهِيَةَ أَنْ أشقّ عَلَى أمِّه ."],"takhrij":"صحيح: رواه البخاري في الأذان (707) عن إبراهيم بن موسى، قال: أخبرنا الوليد، قال: حدثنا الأوزاعي، عن يحيى بن أبي كثير، عن عبدالله بن أبي قتادة، عن أبيه أبي قتادة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في تخفيف الصلاة عند سماع بكاء الصبي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (707)","chapter_en":"Shortening the prayer when hearing a baby cry","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Abu Qatadah reported that the Prophet ﷺ said: “I stand in prayer intending to make it long, then I hear a baby crying, so I make my prayer brief because I dislike causing hardship for his mother.”"]},"buhuth":{"en":["“To make it brief” means to lighten and shorten it—without neglecting what is required."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (707)."},{"num":2278,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنِّي لأَسْمَعُ صَوْتَ الصَّبِيِّ، وَأَنَا فِي الصَّلاةِ، فَأُخَفِّفُ مَخَافَةَ أَنْ تُفْتَنَ أُمُّهُ."],"takhrij":"حسن: رواه البزار في مسنده (9307)عن علي بن سعيد المسروقي، حدثنا عبدالرحيم بن سليمان، حدثنا الحسن بن عمرو، عن عطاء، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب في تخفيف الصلاة عند سماع بكاء الصبي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bazzar (9307)","chapter_en":"Shortening the prayer when hearing a baby cry","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “I hear the sound of a baby while I am in prayer, so I shorten it out of fear that his mother may be distressed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (9307)."},{"num":2279,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَوْتَ صَبِيٍّ فِي الصَّلَاةِ، فَخَفَّفَ الصَّلَاةَ."],"takhrij":"حسن: رواه الإمام أحمد (9581) عن يحيى (هو القطان)، عن ابن عجلان قال: سمعتُ أبي، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب في تخفيف الصلاة عند سماع بكاء الصبي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (9581)","chapter_en":"Shortening the prayer when hearing a baby cry","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ heard the sound of a baby during prayer, so he shortened the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (9581)."},{"num":2280,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكِب فَرَسًا فَصُرِعَ، فجُحِش شِقُّه الأَيْمَنُ. فصَلَّى صَلاَةً مِنَ الصَّلَوَاتِ وَهْوَ قَاعِدٌ. وصلَّينا وَرَاءَهُ قُعوداً فَلَمَّا انْصَرَفَ قَالَ: إِنَّمَا جُعل الإِمَامُ ليؤُتمَّ بِهِ، فَإِذَا صَلَّى قَائِمًا فصَلُّوا قِياماً، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا رَفَعَ فارْفَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: رَبَّنَا وَلَكَ الْحَمْدُ، وَإِذَا صلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (16) عن ابن شهاب، عن أنس بن مالك فذكره. ورواه البخاري في الأذان (689) عن عبدالله بن يوسف عن مالك، ومسلم في الصّلاة (411/80) عن ابن أبي عمر، حدثنا معن بن عيسى، عن مالك به،","grade":"متفق عليه","chapter_ar":"باب ما جاء إذا صلّى الإمام جالساً صلّوا جلوساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (16); al-Bukhari (689); Muslim (411/80)","chapter_en":"If the imam prays sitting, then pray sitting","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ rode a horse and fell, injuring his right side. He led one of the prayers while sitting, and we prayed behind him sitting. When he finished, he said: “The imam is only appointed to be followed. If he prays standing, then pray standing; if he bows, then bow; if he rises, then rise; if he says, ‘Allah hears the one who praises Him,’ then say, ‘Our Lord, to You belongs all praise.’ And if he prays sitting, then pray sitting, all of you.” In another narration: “And if he prostrates, then prostrate.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (16)، البخاري (689)، مسلم (411/80)."},{"num":2281,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، أَنَّهَا قَالَتْ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهِ وَهْوَ شَاكٍ، فَصَلَّى جَالِسًا وَصَلَّى وَرَاءَهُ قَوْمٌ قِيَامًا، فَأَشَارَ إِلَيْهِمْ أَنِ اجْلِسُوا، فَلَمَّا انْصَرَفَ قَالَ: إِنَّمَا جُعِلَ الإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا رَفَعَ فَارْفَعُوا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (17) عن هشام بن عروة، عن أبيه، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء إذا صلّى الإمام جالساً صلّوا جلوساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (17); al-Bukhari (688); Muslim (412)","chapter_en":"If the imam prays sitting, then pray sitting","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ prayed while ill. Some people prayed behind him standing, so he gestured to them to sit. When he finished, he said: “The imam is only appointed to be followed. If he bows, then bow; if he rises, then rise; and if he prays sitting, then pray sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (17)، البخاري (688)، مسلم (412)."},{"num":2282,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا جُعِلَ الإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. فَقُولُوا: رَبَّنَا وَلَكَ الْحَمْدُ. وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (734)، ومسلم في الصلاة (414) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء إذا صلّى الإمام جالساً صلّوا جلوساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (734); Muslim (414)","chapter_en":"If the imam prays sitting, then pray sitting","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The imam is only appointed to be followed. So when he says ‘Allāhu akbar,’ then say ‘Allāhu akbar’; when he bows, bow; when he says, ‘Allah hears the one who praises Him,’ then say, ‘Our Lord, to You belongs all praise.’ When he prostrates, prostrate; and if he prays sitting, then pray sitting, all of you.”"]},"buhuth":{"en":["Al-Bukhari (722) and Muslim also narrated it with the wording: “The imam is only appointed to be followed, so do not differ from him…” and it adds at the end: “And straighten the rows in prayer, for straightening the rows is part of the excellence of prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (734)، مسلم (414)."},{"num":2283,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ، وَأَبُو بَكْرٍ يُسْمِعُ النَّاسَ تَكْبِيرَهُ. فَالْتَفَتَ إِلَيْنَا فَرَآنَا قِيَامًا، فَأَشَارَ إِلَيْنَا فَقَعَدْنَا، فَصَلَّيْنَا بِصَلَاتِهِ قُعُودًا. فَلَمَّا سَلَّمَ قَالَ: إِنْ كِدْتُمْ آنِفًا لَتَفْعَلُونَ فِعْلَ فَارِسَ وَالرُّومِ، يَقُومُونَ عَلَى مُلُوكِهِمْ وَهُمْ قُعُودٌ. فَلَا تَفْعَلُوا، ائْتَمُّوا بِأَئِمَّتِكُمْ، إِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا، وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (413) من طريق الليث، عن أبي الزبير، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء إذا صلّى الإمام جالساً صلّوا جلوساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (413). Abu Dawud (602) also narrates a related wording from Jabir describing the incident of the Prophet ﷺ falling from a horse and praying sitting.","chapter_en":"If the imam prays sitting, then pray sitting","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ became ill, so we prayed behind him while he was sitting, and Abu Bakr was making the people hear his takbir. The Prophet ﷺ turned toward us and saw us standing, so he gestured for us to sit, and we prayed sitting following his prayer. When he gave the taslim, he said: “You almost just did what the Persians and Romans do: they stand over their kings while the kings are sitting. Do not do that. Follow your imams: if he prays standing, then pray standing; and if he prays sitting, then pray sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1231,2608,13937],"tks":"صحيح: رواه مسلم (413). وروى أبو داود (602) لفظا قريبا عن جابر في قصة سقوط النبي ﷺ عن فرس وصلاته قاعدا."},{"num":2284,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ كَانَ يَوْمًا مِنَ الْأَيَّامِ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي نَفَرٍ مِنْ أَصْحَابِهِ، فَقَالَ لَهُمْ:.... فَإِنَّ مِنْ طَاعَةِ اللهِ أَنْ تُطِيعُونِي، وَإِنَّ مِنْ طَاعَتِي أَنْ تُطِيعُوا أَئِمَّتَكُمْ، فَإِنْ صَلَّوْا قُعُودًا، فَصَلُّوا قُعُودًا أَجْمَعِينَ."],"takhrij":"صحيح: رواه الإمام أحمد (5679)، وأبو يعلى (5450)، والطبراني في الكبير (13278) شرح معاني الآثار (2351) كلهم من طريق عقبة بن أبي الصهباء، حدثنا سالم بن عبدالله، أن عبدالله بن عمر حدَّثه فذكر الحديث، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء إذا صلّى الإمام جالساً صلّوا جلوساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (5679), Abu Ya‘la (5450), al-Tabarani in al-Kabir (13278)","chapter_en":"If the imam prays sitting, then pray sitting","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Ibn ‘Umar reported that one day he was with the Messenger of Allah ﷺ along with a group of his Companions, and among what he said to them was: “Part of obeying Allah is that you obey me, and part of obeying me is that you obey your leaders. So if they pray sitting, then pray sitting, all of you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (5679)، وأبو يعلى (5450)، والطبراني في المعجم الكبير (13278)."},{"num":2285,"demo":false,"sanad":"","matn":["عن مُعَاوِيَةَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا صَلَّى الْأَمِيرُ جَالِسًا فَصَلُّوا جُلُوسًا قَالَ: فَعَجِبَ النَّاسُ مِنْ صِدْقِ مُعَاوِيَةَ."],"takhrij":"صحيح: رواه ابن أبي شيبة (7142) عن خالد بن مخلد، عن سليمان ابن بلال، عن جعفر بن محمد، قال: سمعتُ القاسم بن محمد يقول: قال معاوية فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء إذا صلّى الإمام جالساً صلّوا جلوساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Abi Shaybah (2/327)","chapter_en":"If the imam prays sitting, then pray sitting","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Mu‘awiyah said: The Messenger of Allah ﷺ said: “If the leader prays sitting, then pray sitting.” He said: The people were amazed at Mu‘awiyah’s truthfulness."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي شيبة (7142)."},{"num":2286,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا بَكْرٍ أَنْ يُصلِّي بِالنَّاسِ فِي مَرَضِهِ، فَكَانَ يُصَلِّي بِهِمْ، قــال عُرْوَةُ: فَوَجَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَفْسِهِ خِفَّةً فَخَرَجَ، فَإِذَا أَبُو بَكْرٍ يؤمُّ النَّاسَ، فَلَمَّا رَآهُ أَبُو بَكْرٍ اسْتَأْخَرَ، فَأَشَارَ إِلَيْهِ أَنْ كَمَا أَنْتَ، فَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِذاءَ أَبِي بَكْرٍ إِلَى جَنْبِهِ، فَكَانَ أَبُو بَكْرٍ يُصَلّي بِصَلاَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَالنَّاسُ يُصَلُّونَ بِصَلاَةِ أَبِي بَكْرٍ ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (683)، ومسلم في الصلاة (418/97) كلاهما من طريق ابن نمير، قال: أخبرنا هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب من قال بنسخ قعود المأمومين خلف الإمام القاعد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (683), Muslim (418/97)","chapter_en":"Those who held that praying sitting behind a sitting imam was later abrogated","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ ordered Abu Bakr to lead the people in prayer during his illness, so Abu Bakr led them. ‘Urwah said: The Messenger of Allah ﷺ felt some strength and came out, and Abu Bakr was leading the people. When Abu Bakr saw him, he stepped back, but the Prophet ﷺ signaled to him: “Stay as you are.” The Messenger of Allah ﷺ then sat beside Abu Bakr. Abu Bakr was praying following the prayer of the Messenger of Allah ﷺ, and the people were praying following the prayer of Abu Bakr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (683)، مسلم (418/97)."},{"num":2287,"demo":false,"sanad":"","matn":["عَنْ عبيدالله بن عبدالله، قَالَ: دَخَلْتُ عَلَى عَائِشَةَ فَقُلْتُ لَهَا: أَلا تُحدِّثيني عَنْ مَرَضِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَتْ: بَلَى. ثَقُلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَ: أصلَّى النَّاسُ؟ قُلْنَا: لَا. وَهُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ! قَالَ: ضَعُوا لِي مَاءً فِي المِخْضَبِ فَفَعَلْنَا فَاغْتَسَلَ، ثُمَّ ذَهَبَ ليَنُوءَ فأُغْمِي عَلَيْهِ، ثُمَّ أَفَاقَ فَقَالَ: أصَلَّى النَّاسُ؟ قُلْنَا: لَا. وَهُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ! فَقَالَ: ضَعُوا لِي مَاءً فِي المِخْضَبِ فَفَعَلْنَا فَاغْتَسَلَ، ثُمَّ ذَهَبَ ليَنُوءَ فأُغْمِي عَلَيْهِ، ثُمَّ أَفَاقَ فَقَالَ: أصَلَّى النَّاسُ؟ قُلْنَا: لَا. وَهُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ! فَقَالَ: ضَعُوا لِي مَاءً فِي المِخْضَبِ فَفَعَلْنَا فَاغْتَسَلَ، ثُمَّ ذَهَبَ ليَنُوءَ فأُغْمِي عَلَيْهِ، ثُمَّ أَفَاقَ فَقَالَ: أصَلَّى النَّاسُ؟ قُلْنَا: لَا. وَهُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ! قَالَتْ: وَالنَّاسُ عُكُوفٌ فِي الْمَسْجِدِ يَنْتَظِرُونَ رسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِصَلَاةِ الْعِشَاءِ الْآخِرَةِ. قَالَتْ: فَأَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَبِي بَكْرٍ، أَنْ يُصَلَّي بِالنَّاسِ، فَأَتَاهُ الرَّسُولُ فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يأمُرُكَ أَنْ تُصَلِّيَ بِالنَّاسِ، فَقَالَ أَبُو بَكْرٍ، وَكَانَ رجُلاً رَقِيقًا، يَا عُمَرُ! صلِّ بِالنَّاسِ، قَالَ فَقَالَ عُمَرُ: أَنْتَ أحقُّ بِذَلِكَ، قَالَتْ: فصلَّى بِهِمْ أَبُو بَكْرٍ تِلْكَ الْأَيَّامَ. ثُمَّ إنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَدَ مِنْ نَفْسِهِ خِفَّةً فَخَرَجَ بَيْنَ رَجُلَيْنِ، أَحَدُهُمَا الْعَبَّاسُ، لِصَلَاةِ الظُّهْرِ، وَأَبُو بَكْرٍ يُصلِّي بِالنَّاسِ، فَلَمَّا رَآهُ أَبُو بَكْرٍ ذَهَبَ لِيَتَأَخَّرَ، فأَومأَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا يتأخَّرَ، وَقَالَ لَهُمَا أَجْلِسَانِي إلَى جَنْبِه فَأَجْلَسَاهُ إِلَى جَنْبِ أَبِي بَكْرٍ، وَكَانَ أَبُو بَكْرٍ يُصَلِّي وَهُوَ قَائِمٌ بِصَلَاةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . وَالنَّاسُ يُصلُّون بِصَلَاةِ أَبِي بَكْرٍ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ.","قال عبيدالله: فدخلتُ على عبدالله بن عباس فقلت له: ألا أعرضُ عليك ما حدثتْني عائشةُ عن مَرَضِ رسول الله صلى الله عليه وسلم ؟ فقال: هاتِ. فعرضتُ حديثَها عليه فما أنْكَرَ منه شيئاً. غيرَ أنَّه قال: أسَمَّتْ لك الرجلَ الذي كان مع العَبَّاس؟ قلتُ: لا. قال: هُوَ عَليٌّ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (687)، ومسلم في الصلاة (418) كلاهما عن أحمد بن عبدالله بن يونس، حدثنا زائدة، حدثنا موسى بن أبي عائشة، عن عبيدالله بن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب من قال بنسخ قعود المأمومين خلف الإمام القاعد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (687), Muslim (418)","chapter_en":"Those who held that praying sitting behind a sitting imam was later abrogated","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":18,"content":{"translation":{"en":["‘Ubaydullah ibn ‘Abdullah said: I entered upon ‘A’ishah and said: “Will you not tell me about the illness of the Messenger of Allah ﷺ?” She said: “Yes.” The Prophet ﷺ became very ill and said: “Have the people prayed?” We said: “No. They are waiting for you, O Messenger of Allah ﷺ.” He said: “Put water for me in the wash-basin.” We did so and he bathed, then he tried to stand but fainted. Then he regained consciousness and said: “Have the people prayed?” We said: “No. They are waiting for you, O Messenger of Allah ﷺ.” He said: “Put water for me in the wash-basin.” We did so and he bathed, then he tried to stand but fainted. Then he regained consciousness and said: “Have the people prayed?” We said: “No. They are waiting for you, O Messenger of Allah ﷺ.” He said: “Put water for me in the wash-basin.” We did so and he bathed, then he tried to stand but fainted. Then he regained consciousness and said: “Have the people prayed?” We said: “No. They are waiting for you, O Messenger of Allah ﷺ.” She said: The people were staying in the mosque, waiting for the Messenger of Allah ﷺ for the late ‘Isha’ prayer. She said: So the Messenger of Allah ﷺ sent to Abu Bakr, telling him to lead the people in prayer. The messenger came to him and said: “The Messenger of Allah ﷺ commands you to lead the people in prayer.” Abu Bakr—who was soft-hearted—said: “O ‘Umar, lead the people.” ‘Umar said: “You have more right to that.” So Abu Bakr led them in those days. Then the Messenger of Allah ﷺ felt some strength, so he came out supported between two men—one of them was al-‘Abbas—for the noon prayer, while Abu Bakr was leading the people. When Abu Bakr saw him, he began to step back, but the Prophet ﷺ signaled to him not to step back. He said to the two men: “Seat me beside him.” So they seated him next to Abu Bakr. Abu Bakr was praying standing, following the prayer of the Prophet ﷺ, and the people were praying following Abu Bakr, while the Prophet ﷺ was sitting. ‘Ubaydullah said: I then went to ‘Abdullah ibn ‘Abbas and said: “Shall I present to you what ‘A’ishah told me about the illness of the Messenger of Allah ﷺ?” He said: “Go ahead.” I presented it to him and he did not object to anything in it, except he said: “Did she name for you the man who was with al-‘Abbas?” I said: “No.” He said: “It was ‘Ali.”"]},"buhuth":{"en":["Regarding her words, “Abu Bakr led them in those days”: Ibn Nasir al-Din al-Dimashqi stated that in those days up to the Prophet ﷺ’s passing, Abu Bakr led seventeen prayers—beginning with the late ‘Isha’ on Friday night and ending with the dawn prayer on Monday.","Al-Bukhari (713) and Muslim (418/95) also narrate that when the Prophet ﷺ became very ill, Bilal came to call him for prayer and the Prophet said: “Tell Abu Bakr to lead the people.” In it, the Prophet ﷺ came out supported between two men, his feet dragging on the ground, until he entered the mosque. He signaled to Abu Bakr to remain, sat to Abu Bakr’s left, and Abu Bakr followed the Prophet’s prayer while the people followed Abu Bakr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (687)، مسلم (418)."},{"num":2288,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ قَالَ: إنهم كَانُوا يُصَلُّونَ خلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ لَمْ أَرَ أَحَدًا يَحْنِي ظَهْرَهُ حَتَّى يضـعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَبْهَتَهُ عَلَى الْأَرْضِ. ثُمَّ يَخِرُّ مَنْ وَرَاءَهُ سُجَّداً.","وفي رواية: فَإِذَا رَكَعَ رَكَعُوا، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَقَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ لَمْ نَزَلْ قِيَامًا حَتَّى نَرَاهُ قَدْ وَضَعَ وَجْهَهُ فِي الْأَرْضِ، ثُمَّ نَتَّبِعُهُ.","وفي رواية: كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم : لَا يَحْنُو أَحَدٌ مِنَّا ظَهْرَهُ حَتَّى نَرَاهُ قَدْ سَجَدَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (690)، ومسلم في الصلاة (474) كلاهما من طريق أبي إسحاق، قال: حدثني عبدالله بن يزيد، قال: حدثني البراء وهو غير كذوب.","grade":"متفق عليه","chapter_ar":"باب متابعة الإمام والعمل بعده","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (690), Muslim (474) (the additional wordings are in Muslim)","chapter_en":"Following the imam and acting after him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":19,"content":{"translation":{"en":["Al-Bara’ said: They used to pray behind the Messenger of Allah ﷺ. When he raised his head from bowing, I did not see anyone bend his back until the Messenger of Allah ﷺ placed his forehead on the ground; then those behind him would fall into prostration. In another narration: When he bowed, they bowed, and when he raised his head from bowing and said, “Allah hears the one who praises Him,” we would remain standing until we saw that he had placed his face on the ground, then we would follow him. In another narration: We were with the Prophet ﷺ; none of us would bend his back until we saw that he had prostrated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (690)، ومسلم (474)، والزيادات اللفظية عند مسلم."},{"num":2289,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ، فَلَمَّا قَضَى الصَّلَاةَ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: أَيُّهَا النَّاسُ! إِنِّي إِمَامُكُمْ، فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ، وَلَا بِالْقِيَامِ، وَلَا بِالِانْصِرَافِ، فَإِنِّي أَرَاكُمْ أَمَامِي وَمِنْ خَلْفِي. ثُمَّ قَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ! لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا، وَلَبَكَيْتُمْ كَثِيرًا!!","قَالُوا: وَمَا رَأَيْتَ يَا رَسُولَ اللهِ؟ قَالَ: رَأَيْتُ الْجَنَّةَ وَالنَّارَ .."],"takhrij":"صحيح: رواه مسلم في الصلاة (426) من طريق علي بن مسهر، عن المختار بن فُلْفُلٍ، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن سبق الإمام بركوع وسجود وانصراف قبله","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (426). Also narrated by Abu Dawud (624) with wording that he urged them regarding the prayer and forbade them from leaving before he left the prayer.","chapter_en":"Prohibition of getting ahead of the imam in bowing, prostration, or leaving before him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":20,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ led us in prayer one day. When he finished, he turned to face us and said: “O people! I am your imam, so do not precede me in bowing, prostration, standing, or concluding the prayer. I can see you in front of me and behind me.” Then he said: “By the One in whose hand is the soul of Muhammad: if you were to see what I have seen, you would laugh little and weep much.” They said: “What did you see, O Messenger of Allah?” He said: “I saw Paradise and the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (426). ورواه أبو داود (624) بلفظ أنه حضهم على الصلاة ونهاهم أن ينصرفوا قبل انصرافه منها."},{"num":2290,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تُبَادِرُونِي بِرُكُوعٍ وَلاَ بِسُجُودٍ، فَإِنَّهُ مَهْمَا أَسْبِقْكُمْ بِهِ إِذَا رَكَعْتُ تُدْرِكُونِي بِهِ إِذَا رَفَعْتُ، إِنِّي قَدْ بَدَّنْتُ."],"takhrij":"صحيح: رواه أبو داود (619)، وابن ماجه (963) كلاهما من طريق يحيى بن سعيد، عن ابن عجلان، حدثني محمد بن يحيى بن حِبَّان، عن ابن محيريز، عن معاوية بن أبي سفيان فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن سبق الإمام بركوع وسجود وانصراف قبله","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (619); Ibn Majah (963); Ibn Khuzaymah (1594); Ibn Hibban (2230)","chapter_en":"Prohibition of getting ahead of the imam in bowing, prostration, or leaving before him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":20,"content":{"translation":{"en":["Mu‘awiyah ibn Abi Sufyan said: The Messenger of Allah ﷺ said: “Do not get ahead of me in bowing or prostration. For even if I precede you in bowing, you will catch up with it when I rise. Indeed, I have grown heavier.”"]},"buhuth":{"en":["“You will catch up when I rise” means: even if the imam rises sooner, the followers still complete what remains of the posture before moving to the next one; the Prophet ﷺ also used to make a longer supplication after rising from bowing. “I have become heavier” is narrated in two ways: one meaning he had become older, and the other meaning his body had increased in weight—both of which make movement slower. (This explanation is attributed to al-Khattabi.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (619)، ابن ماجه (963)، ابن خزيمة (1594)، ابن حبان (2230)."},{"num":2291,"demo":false,"sanad":"","matn":["عن جُبَيْرِ بْنِ مُطْعِمٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي قَدْ بَدَّنْتُ، فَلَا تُبَادِرُونِي بِالْقِيَامِ فِي الصَّلَاةِ، وَالرُّكُوعِ، وَالسُّجُودِ."],"takhrij":"صحيح: رواه الطبراني في الكبير (1579) عن علي بن عبد العزيز، ثنا عاصم بن علي، ثنا إسحاق الأزرق، عن زكريا بن أبي زائدة، عن سعد بن إبراهيم، عن نافع بن جبير بن مطعم، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن سبق الإمام بركوع وسجود وانصراف قبله","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tabarani in al-Kabir (1579)","chapter_en":"Prohibition of getting ahead of the imam in bowing, prostration, or leaving before him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":20,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: The Messenger of Allah ﷺ said: “I have grown heavier, so do not get ahead of me in standing (transitions) in prayer, bowing, or prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في المعجم الكبير (1579)."},{"num":2292,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَمَا يَخْشَى أَحَدُكُمْ -أَوْ لاَ يَخْشَى أَحَدُكُمْ- إِذَا رَفَعَ رَأْسَهُ قَبْلَ الإِمَامِ أَنْ يَجْعَلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ، أَوْ يَجْعَلَ اللَّهُ صُورَتَهُ صُورَةَ حِمَارٍ ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (691) عن حجاج بن مِنهال، قال: حدثنا شعبة، عن محمد بن زياد سمعتُ أبا هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب إثم من رفع رأسه قبل الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)","chapter_en":"The sin of raising the head before the imam","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Does one of you not fear—if he raises his head before the imam—that Allah may turn his head into the head of a donkey, or turn his form into the form of a donkey?”"]},"buhuth":{"en":["al-Bukhari (691); Muslim (427) (Muslim’s wording includes: “that Allah may make his face the face of a donkey”). Abu Dawud (623) has wording mentioning raising the head while the imam is still prostrating."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (691)، ومسلم (427)، وفي لفظ مسلم: «أن يجعل الله وجهه وجه حمار». ورواه أبو داود (623) بلفظ فيه رفع الرأس والإمام ساجد."},{"num":2293,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن أَبْزَى أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صلَّى الْفَجْرِ، فَتَرَكَ آيَةً، فَلَمَّا صلَّى قَالَ: أ فِي الْقَوْمِ أبيُّ بْنُ كَعْبٍ؟ قَالَ أبيٌّ: يَا رَسُولَ اللَّهِ! نُسختْ آيَةُ كَذَا وَكَذَا، أَوْ نُسِّيتَهَا؟ قَالَ: نُسِّيتُها ."],"takhrij":"صحيح: رواه أحمد (15365)، والنسائي في الكبرى (8183) كلاهما من حديث يحيى بن سعيد، عن سفيان، حدثنا سَلَمة بن كُهيل، عن ذر، عن سعيد بن عبدالرحمن بن أبْزى، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الفتح على الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (15365); al-Nasa’i in al-Kubra (8183)","chapter_en":"Prompting the imam if he forgets or makes a mistake in recitation","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":22,"content":{"translation":{"en":["‘Abd al-Rahman ibn Abza reported that the Prophet ﷺ prayed Fajr and left out a verse. When he finished, he said: “Is Ubayy ibn Ka‘b among the people?” Ubayy said: “O Messenger of Allah, was such-and-such a verse abrogated, or did you forget it?” He said: “I was made to forget it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15365)، النسائي في الكبرى (8183)."},{"num":2294,"demo":false,"sanad":"","matn":["عَنِ الْمُسَوَّرِ بْنِ يَزِيدَ الأسدي قَالَ: شَهِدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الصَّلَاةِ، فَتَرَكَ شَيْئًا لَمْ يَقْرَأْهُ، فَقَالَ لَهُ رَجُلٌ: يَا رَسُولَ اللَّهِ! تَرَكْتَ آيَةَ كَذَا وَكَذَا. فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هلا أذكرتنيها ."],"takhrij":"حسن: رواه أبو داود (907) قال: حدثنا محمد بن العلاء وسليمان ابن عبدالرحمن الدمشقي، قالا: أخبرنا مروان بن معاوية، عن يحيى الكاهلي، عن المسور بن يزيد المالكي فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الفتح على الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (907); Ibn Hibban authenticated it (2240); Ibn Khuzaymah (1648)","chapter_en":"Prompting the imam if he forgets or makes a mistake in recitation","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":22,"content":{"translation":{"en":["Al-Miswar ibn Yazid al-Asadi said: I witnessed the Messenger of Allah ﷺ reciting in prayer and he left something out that he did not recite. A man said: “O Messenger of Allah, you left out such-and-such a verse.” The Messenger of Allah ﷺ said: “Why didn’t you remind me of it?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (907)، وصححه ابن حبان (2240)، ورواه ابن خزيمة (1648)."},{"num":2295,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى صَلَاةً فَقَرَأَ فِيهَا، فَلُبِسَ عَلَيْهِ، ، فَلَمَّا انْصَرَفَ قَالَ لِأُبَيٍّ: : أَصَلَّيْتَ مَعَنَا؟ ، قَالَ: : نَعَمْ. ، قَالَ: : فَمَا مَنَعَكَ."],"takhrij":"صحيح: رواه أبو داود (907) عن يزيد بن محمد الدمشقي، حدثنا هشام بن إسماعيل، حدثنا محمد بن شُعيب، أخبرنا عبدالله بن العلاء بن زُبْر، عن سالم بن عبدالله، عن عبدالله بن عمر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الفتح على الإمام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (907); Ibn Hibban (2242) (with the explicit wording about prompting)","chapter_en":"Prompting the imam if he forgets or makes a mistake in recitation","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":22,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that the Prophet ﷺ prayed a prayer and recited in it, but became confused. When he finished, he said to Ubayy: “Did you pray with us?” He said: “Yes.” He said: “Then what prevented you?” In Ibn Hibban’s wording: “What prevented you from prompting me?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (907)، وابن حبان (2242)، وفيه التصريح بالتلقين."},{"num":2296,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِيَليني مِنْكُمْ أُولُو الْأَحْلَامِ وَالنُّهَى، ثُمَّ الَّذِينَ يَلُونَهُم -ثَلَاثًا- وَإِيَّاكُمْ وَهَيْشَاتِ الْأَسْوَاقِ ."],"takhrij":"صحيح: رواه مسلم في الصلاة (433/123) من طريق أبي معشر، عن إبراهيم، عن علقمة، عن عبدالله بن مسعود فذكر الحديث.","grade":"صحيح","chapter_ar":"باب من يُستحب أن يَلِيَ الإمامَ في الصف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (433/123)","chapter_en":"Who is recommended to stand closest to the imam in the row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":23,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ said: “Let those among you who possess maturity and sound understanding stand closest to me, then those who come after them—(he repeated it) three times—and beware of the commotions of marketplaces.”"]},"buhuth":{"en":["“The commotions of marketplaces” refers to the noise, loud voices, and disturbances—and the turmoil that can occur there. The root conveys mixing and jostling, meaning people crowding and conflicting with one another. (Explanation attributed to al-Khattabi.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (433/123)."},{"num":2297,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحب أَنْ يَلِيَهُ الْمُهَاجِرُونَ وَالأَنْصَارُ لِيَأْخُذُوا عَنْهُ."],"takhrij":"صحيح: رواه ابن ماجه (977) قال: حدثنا نصر بن علي الجَهْضَمِي قال: حدثنا عبدالوهاب، قال: حدثنا حُميد، عن أنس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب من يُستحب أن يَلِيَ الإمامَ في الصف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (977); Ahmad (11963)","chapter_en":"Who is recommended to stand closest to the imam in the row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":23,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ liked the Emigrants and the Helpers to stand closest to him so that they could learn from him. In Ahmad’s narration: “He liked the Emigrants and the Helpers to stand closest to him in prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (977)، أحمد (11963)."},{"num":2298,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ عَبَّادٍ، قَالَ: بَيْنَا أَنَا فِي الْمَسْجِدِ، فِي الصَّفِّ الْمُقَدَّمِ فَجَبَذَنِي رَجُلٌ مِنْ خَلْفِي جَبْذَةً، فَنَحَّانِي، وَقَامَ مَقَامِي. فَوَاللَّهِ مَا عَقَلْتُ صَلاَتِي. فَلَمَّا انْصَرَفَ فَإِذَا هُوَ أُبَىُّ بْنُ كَعْبٍ، فَقَالَ: يَا فَتَى لاَ يَسُؤْكَ اللَّهُ: إِنَّ هَذَا عَهْدٌ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْنَا أَنْ نَلِيَهُ، ثُمَّ اسْتَقْبَلَ الْقِبْلَةَ، فَقَالَ: هَلَكَ أَهْلُ الْعُقَدِ وَرَبِّ الْكَعْبَةِ ثَلاَثًا ثُمَّ قَالَ: وَاللَّهِ مَا عَلَيْهِمْ آسَى، وَلَكِنْ آسَى عَلَى مَنْ أَضَلُّوا. قُلْتُ: يَا أَبَا يَعْقُوبَ! مَا يَعْنِي بِأَهْلِ الْعُقَدِ قَالَ: الأُمَرَاءُ."],"takhrij":"صحيح: رواه النسائي (808) قال: أخبرنا محمد بن عمر بن علي بن مُقَدَّم، حدثنا يوسف بن يعقوب، قال: أخبرني التيمي، عن أبي مجلز، عن قيس ابن عُبَاد فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من يُستحب أن يَلِيَ الإمامَ في الصف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (808)","chapter_en":"Who is recommended to stand closest to the imam in the row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":23,"content":{"translation":{"en":["Qays ibn ‘Abbad said: While I was in the mosque in the front row, a man behind me pulled me back strongly, moved me aside, and stood in my place. By Allah, I could not attend to my prayer. When I finished, it turned out to be Ubayy ibn Ka‘b. He said: “Young man, may Allah not grieve you. This is a directive from the Prophet ﷺ to us—that we should be close to him.” Then he faced the qiblah and said: “The people of authority have perished, by the Lord of the Ka‘bah,” three times. Then he said: “By Allah, I do not grieve for them, but I grieve for those whom they misled.” I said: “O Abu Ya‘qub, what do you mean by ‘the people of authority’?” He said: “The rulers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (808)."},{"num":2299,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ ، قَالَ: : بِتُّ فِي بَيْتِ خَالَتِي مَيْمُونَةَ، ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ، فَأَطْلَقَ الْقِرْبَةَ فَتَوَضَّأَ، ثُمَّ أَوْكَأَ الْقِرْبَةَ، ثُمَّ قَامَ إِلَى الصَّلَاةِ، ، فَقُمْتُ فَتَوَضَّأْتُ كَمَا تَوَضَّأَ، ثُمَّ جِئْتُ ، فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَنِي بِيَمِينِهِ فَأَدَارَنِي مِنْ وَرَائِهِ فَأَقَامَنِي عَنْ يَمِينِهِ، فَصَلَّيْتُ مَعَهُ.","وفي رواية: فَأَخَذَ بِرَأْسِي أَوْ بِذُؤَابَتِي فَأَقَامَنِي عَنْ يَمِينِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (698) ومسلم في صلاة المسافرين (763/184) كلاهما من طريق ابن وهب، ثنا عمرو، عن عبد ربه بن سعيد، عن مخرمة بن سليمان، عن كريب مولى ابن عباس، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب موقف المأموم الواحد عن يمين الإمام بحذائه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (698), Muslim (763/184). The second wording is in Abu Dawud (610).","chapter_en":"The position of a single follower: to the imam’s right, aligned with him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Abbas said: I spent the night in the house of my aunt Maymunah. The Messenger of Allah ﷺ got up at night, opened the water-skin, made wudu, then tied it up, and stood to pray. I got up, made wudu as he did, then came and stood on his left. He took me with his right hand, moved me around behind him, and placed me on his right, so I prayed with him. In another narration: He took me by my head or by my forelock and placed me on his right."]},"buhuth":{"en":["“Dhu’abah” means the forelock—hair at the front/top of the head."]}},"tuhfa":{},"voc":["abudawud",610],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (698)، ومسلم (763/184). واللفظ الثاني عند أبي داود (610)."},{"num":2300,"demo":false,"sanad":"","matn":["عن ابن عَبَّاسٍ قَالَ: أَتَيْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ آخِرِ اللَّيْلِ، فَصَلَّيْتُ خَلْفَهُ، فَأَخَذَ بِيَدِي، فَجَرَّنِي، فَجَعَلَنِي حِذَاءَهُ، فَلَمَّـــا أَقْبَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى صَلَاتِهِ، خَنَسْتُ، فَصَلَّى رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَلَمَّا انْصَرَفَ، قَالَ لِي: مَا شَأْنِي أَجْعَلُكَ حِذَائِي فَتَخْنِسُ؟ فَقُلْتُ: يَا رَسُولَ الله ، أَوَ يَنْبَغِي لِأَحَدٍ أَنْ يُصَلِّيَ حِذَاءَكَ، وَأَنْتَ رَسُولُ الله الَّذِي أَعْطَاكَ الله! قَالَ: فَأَعْجَبْتُهُ، فَدَعَا الله لِي أَنْ يَزِيدَنِي عِلْمًا وَفَهْمًا، قَالَ: ثُمَّ رَأَيْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَامَ، حَتَّى سَمِعْتُهُ يَنْفُخُ، ثُمَّ أَتَاهُ بِلَالٌ، فَقَــالَ: يَا رَسُولَ الله، الصَّلَاةَ، فَقَامَ، فَصَلَّى، مَا أَعَادَ وُضُوءًا."],"takhrij":"صحيح: رواه الإمام أحمد (3060) عن عبد الله بن بكر، حدثنا حاتم بن أبي صغيرة أبو يونس، عن عمرو بن دينار، أن كريبا أخبره، أن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب موقف المأموم الواحد عن يمين الإمام بحذائه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (3060)","chapter_en":"The position of a single follower: to the imam’s right, aligned with him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Abbas said: I came to the Messenger of Allah ﷺ late at night and prayed behind him. He took my hand, pulled me, and placed me aligned beside him. When the Messenger of Allah ﷺ turned to his prayer, I stepped back. The Messenger of Allah ﷺ prayed, and when he finished, he said to me: “What is the matter with me that I place you beside me and you step back?” I said: “O Messenger of Allah, is it appropriate for anyone to stand aligned with you while you are the Messenger of Allah, to whom Allah has given [what He has given]?” That pleased him, so he supplicated that Allah increase me in knowledge and understanding… Then I saw the Messenger of Allah ﷺ sleep until I heard him breathing deeply, then Bilal came and said: “O Messenger of Allah, the prayer.” He stood and prayed without renewing wudu."]},"buhuth":{"en":["“Khannastu” means: I moved back / stepped behind."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (3060)."},{"num":2301,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ، وَصَلَّى، فَأَقَامَنِي عَلَى يَمِينِهِ."],"takhrij":"حسن: أخرجه الطبراني في الأوسط (8105) عن موسى بن هارون، ثنا إسحاق بن راهويه، أنا الفضل بن موسى، عن عبدالمؤمن بن خالد، عن عبدالله بن بريدة، عن المغيرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب موقف المأموم الواحد عن يمين الإمام بحذائه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Awsat (8105)","chapter_en":"The position of a single follower: to the imam’s right, aligned with him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":24,"content":{"translation":{"en":["Al-Mughirah ibn Shu‘bah said: The Prophet ﷺ performed wudu and wiped over his leather socks, then prayed, and placed me on his right."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (8105)."},{"num":2302,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ليُصلِّي، فَجِئْتُ حَتَّى قُمت عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَأَخَذَ بِيَدِي فَأَدَارَنِي خلْفَه حَتَّى أَقَامَنِي عَنْ يَمِينِهِ، ثُمَّ جَاءَ جَبَّـارُ بْنُ صَخْر فَقَامَ عَنْ يَسَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخَذَ بِيَدَيْنَا جَمِيعًا فَدَفَعَنَا حَتَّى أَقَامَنَا خلْفَه."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق في حديث جابر الطويل (3010) وسيعاد الحديث بالكامل في الزهد.","grade":"صحيح","chapter_ar":"باب موقف الإمام مع الاثنين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (3010) (in the long hadith of Jabir in al-Zuhd wa al-Raqa’iq)","chapter_en":"The imam’s position when there are two followers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: The Messenger of Allah ﷺ stood to pray. I came and stood on his left, so he took my hand and turned me behind him until he placed me on his right. Then Jabbar ibn Sakhr came and stood on the Prophet’s left, so the Prophet took both of our hands and moved us until he placed us behind him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (3010) في حديث جابر الطويل في الزهد والرقائق."},{"num":2303,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ، وَالْأَسْوَدِ  أَنَّهُمَا دَخَلَا عَلَى عَبْدِ اللَّهِ فَقَالَ: أَصَلَّى مَنْ خَلْفَكُمْ؟ قَالَا: نَعَمْ. فَقَامَ بَيْنَهُمَا، وَجَعَلَ أَحَدَهُمَا عَنْ يَمِينِهِ، وَالْآخَرَ عَنْ شِمَالِهِ، ثُمَّ رَكَعْنَا. فَوَضَعْنَا أَيْدِيَنَا عَلَى رُكَبِنَا فَضَرَبَ أَيْدِيَنَا، ثُمَّ طَبَّقَ بَيْنَ يَدَيْهِ، ثُمَّ جَعَلَهُمَا بَيْنَ فَخِذَيْهِ. فَلَمَّا صَلَّى قَالَ: هَكَذَا فَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (534/28)، من طريق منصور، عن إبراهيم، عن علقمة والأسود به.","grade":"صحيح","chapter_ar":"باب موقف الإمام مع الاثنين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (534/28).","chapter_en":"The imam’s position when there are two followers","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":25,"content":{"translation":{"en":["Al-Aswad and ʿAlqamah said: We came to ʿAbdullāh ibn Masʿūd in his house. He asked: “Have those people behind you prayed?” We said: “No.” He said: “Then stand and pray.” He did not order us to give an adhān or iqāmah. We went to stand behind him, but he took us by our hands and placed one of us on his right and the other on his left. When he bowed, we placed our hands on our knees, so he struck our hands away, joined his palms together, and placed them between his thighs. When he finished praying, he said: “There will be rulers over you who will delay the prayer beyond its proper time and constrict it until the time when the sun is at the edge of setting. When you see them doing that, pray the prayer at its proper time and regard your prayer with them as a voluntary prayer. When you are three, pray together; and when you are more than that, let one of you lead. When one of you bows, let him spread his forearms upon his thighs, bend forward, and join his palms together. It is as though I can see the differing position of the fingers of the Messenger of Allah ﷺ.” In another narration: “It is as though I can see the differing position of the fingers of the Messenger of Allah ﷺ while he was bowing.”"]},"buhuth":{"en":["Ibn Masʿūd’s statement, “This is how the Messenger of Allāh ﷺ did it,” suggests that the report is marfūʿ—attributed to the Prophet ﷺ. However, some scholars held that only the portion concerning clasping the hands together (taṭbīq) is established as marfūʿ, and that this practice was subsequently abrogated.","Al-Nawawī said in al-Khulāṣah (2510):","“What is established in Ṣaḥīḥ Muslim and elsewhere is that Ibn Masʿūd did this. It does not say: ‘This is how the Messenger of Allāh ﷺ used to do it.’”","For this reason, the majority of the scholars did not adopt Ibn Masʿūd’s practice. Rather, they said that when an imam leads two men in prayer, he should stand ahead of them.","They also said that if the attribution of Ibn Masʿūd’s report to the Prophet ﷺ is authentic, it is possible that the Prophet ﷺ did this once or twice because of limited space, or that the practice was abrogated by stronger aḥādīth.","Al-Baghawī said:","“The view of the general body of scholars is that when the imam prays with two men, he stands ahead of them. It has been narrated from Ibn Masʿūd that he prayed with ʿAlqamah and al-Aswad, placing one of them on his right and the other on his left, and he narrated this from the Prophet ﷺ.”","End quote. See Sharḥ al-Sunnah (2/389).","Some scholars interpreted the ḥadīth of Ibn Masʿūd as meaning that the Prophet ﷺ may have done this on one occasion because of limited space, or they understood the practice to have been abrogated.","See: al-Sunan al-Kubrā (3/98)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (534/28)."},{"num":2304,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ قَالَ: دَعَتْ جدتي مُلَيْكَةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ فَأَكَلَ مِنْهُ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قُومُوا فلأصلِّي لَكُمْ قَالَ أَنَسٌ: فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدِ اسودَّ مِنْ طُولِ مَا لُبِس فَنَضَحْتُهُ بِمَاءٍ. فَقَامَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَفَفْتُ أنا وَالْيَتِيمَ وَرَاءَهُ، وَالْعَجُوزُ مِنْ وَرَائِنَا. فصَلَّى رَكْعَتَيْنِ ثُمَّ انْصَرَفَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة في السفر (31) عن إسحاق بن عبدالله بن أبي طلحة، عن أنس بن مالك فذكره، وعن مالك رواه البخاري في الصلاة (380)، ومسلم في المساجد (658).","grade":"متفق عليه","chapter_ar":"باب ما جاء في موقف الإمام مع الاثنين والمرأة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (31); al-Bukhari (380); Muslim (658)","chapter_en":"The imam’s position with two followers and a woman","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":26,"content":{"translation":{"en":["Anas ibn Malik said: My grandmother Mulaykah invited the Messenger of Allah ﷺ for food, and he ate from it. Then the Messenger of Allah ﷺ said: “Stand, so that I may lead you in prayer.” Anas said: I went to a mat we had that had darkened from long use and sprinkled it with water. The Messenger of Allah ﷺ stood on it, and I and an orphan stood behind him, and the elderly woman stood behind us. He prayed two units, then left."]},"buhuth":{"en":["This indicates that praying in congregation for voluntary prayer is permissible."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (31)، البخاري (380)، مسلم (658)."},{"num":2305,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: دَخَلَ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا؛ وَمَا هُوَ إِلَّا أَنَا، وَأُمِّي، وَأُمُّ حَرَامٍ خَالَتِي فَقَالَ: قُومُوا فلأصَلِّ بِكُمْ فَصَلَّى بِنَا. فَقَالَ رَجُلٌ لِثَابِتٍ: أَيْنَ جَعَلَ أَنَسًا مِنْهُ؟ قَالَ: جَعَلَهُ عَلَى يَمِينِهِ، ثُمَّ دَعَا لَنَا أَهْلَ الْبَيْتِ بِكُلِّ خَيْرٍ مِنْ خَيْرِ الدُّنْيَا وَالْآخِرَةِ، فَقَالَتْ أُمِّي: يَا رَسُولَ اللَّهِ! خُوَيْدِمُكَ ادعُ اللَّهَ لَهُ. قَالَ: فَدَعَا لِي بِكُلِّ خَيْرٍ. وَكَانَ فِي آخِرِ مَا دَعَا لِي بِهِ أَنْ قَالَ: اللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ وَبَارِكْ لَهُ فِيهِ .","وفي رواية: أن رسول الله صلى الله عليه وسلم صلى به وبأمه وخالته، قال: فأقامني عن يمينه، وأقام المرأة خلْفنا."],"takhrij":"صحيح: رواه مسلم في المساجد (660) عن سليمان، عن ثابت، عن أنس فذكر مثله، والرواية الثانية رواه من طريق موسى بن أنس، يُحدث عن أنس بن مالك.","grade":"صحيح","chapter_ar":"باب ما جاء في موقف الإمام مع الواحد والمرأة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (660). Also in Muslim (659) with additional detail about cleansing the mat.","chapter_en":"The imam’s position with one follower and a woman","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":27,"content":{"translation":{"en":["Anas said: The Prophet ﷺ entered upon us when only I, my mother, and my aunt Umm Haram were present. He said: “Stand so that I may pray with you.” So he led us in prayer. A man asked Thabit: “Where did he place Anas?” He said: “He placed him on his right.” Then he supplicated for us, the household, with every good of this world and the Hereafter. My mother said: “O Messenger of Allah, your little servant—supplicate to Allah for him.” So he supplicated for me with every good, and among the last of what he said was: “O Allah, increase his wealth and his children and bless him in it.” In another narration: “He placed me on his right and placed the woman behind us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (660). ورواه مسلم أيضا (659) بزيادة في تطهير الحصير."},{"num":2306,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ: قَالَ: ابْنُ عَبَّاسٍ: صَلَّيْتُ إِلَى جَنْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَائِشَةُ خَلْفَنَا تُصَلِّي مَعَنَا، وَأَنَا إِلَى جَنْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُصَلِّي مَعَهُ."],"takhrij":"حسن: رواه النسائي (804،841) قال: أخبرنا محمد بن إسماعيل بن إبراهيم، قال: حدثنا حجاج، قال: قال ابن جريج: أخبرني زياد، أن قَزعة مولى لعبد قيس أخبره، أنه سمع عكرمة مولى ابن عباس قال: قال ابن عباس فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في موقف الإمام مع الواحد والمرأة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Nasa’i (804, 841); Ibn Khuzaymah authenticated it (1537); Ibn Hibban (2204); Ahmad (2751)","chapter_en":"The imam’s position with one follower and a woman","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":27,"content":{"translation":{"en":["Ibn ‘Abbas said: I prayed beside the Prophet ﷺ, and ‘A’ishah was behind us praying with us, while I was beside the Prophet ﷺ praying with him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (804، 841)، وصححه ابن خزيمة (1537)، ورواه ابن حبان (2204)، وأحمد (2751)."},{"num":2307,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الأشعريّ قـــال: أَلاَ أُحَدِّثُكُمْ بِصَلاَةِ النّبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَ: فَأَقَامَ الصَّلاَةَ، وصفَّ الرِّجَالَ، وصَفَّ خَلْفَهُمُ الْغِلْمَانَ، ثُمَّ صلَّى بِهِمْ، فَذَكَرَ صَلاَتَهُ ثُمَّ قَالَ: هَكَذَا صَلاَةُ. قَالَ عَبْدُ الأَعْلَى: لاَ أَحْسَبُهُ إِلاَّ قَالَ: [صَلاَةُ] أُمَّتِي ."],"takhrij":"حسن: رواه أبو داود (677) حدثنا عيسى بن شاذان، ثنا عياش الرقام، ثنا عبد الأعلى، ثنا قرة بن خالد، ثنا بُديل، ثنا شهر بن حوشب، عن عبدالرحمن ابن غنم، قال: قال أبو مالك الأشعري فذكره.","grade":"حسن","chapter_ar":"باب مقام الصبيان من الصف خلف الرجال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (677)","chapter_en":"The position of boys in the row behind men","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":28,"content":{"translation":{"en":["Abu Malik al-Ash‘ari said: “Shall I not tell you about the prayer of the Prophet ﷺ?” He said: He established the prayer, arranged the men in rows, arranged the boys behind them, then led them in prayer… then he said: “This is the prayer”—and ‘Abd al-A‘la said: I think he said—“the prayer of my ummah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (677)."},{"num":2308,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الأَوَّلِ، ثُمَّ لَمْ يَجِدُوا إِلاَّ أَنْ يَسْتَهِمُوا عَلَيْهِ لاَسْتَهَمُوا، وَلَوْ يَعْلَمُونَ مَا فِي التَّهْجِيرِ لاَسْتَبَقُوا إِلَيْهِ، وَلَوْ يَعْلَمُونَ مَا فِي الْعَتَمَةِ وَالصُّبْحِ لأَتَوْهُمَا وَلَوْ حَبْوًا."],"takhrij":"متفق عليه: رواه مالك في الصلاة (3) عن سُمّي مولى أبي بكر بن عبدالرحمن، عن أبي صالح السمان، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (3); al-Bukhari (615); Muslim (437)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “If people knew what (reward) is in the call to prayer and in the first row, and they could not attain it except by drawing lots, they would draw lots for it. If they knew what (reward) is in going early (to the prayer), they would race to it. And if they knew what (reward) is in the night prayer (‘Isha) and the dawn prayer (Fajr), they would come to them even crawling.”"]},"buhuth":{"en":["“Al-tahjir” comes from “al-hajirah,” the intense midday heat, and it refers to going early at the beginning of the time for the noon prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3)، البخاري (615)، مسلم (437)."},{"num":2309,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا، وَشَرُّهَا آخِرُهَا، وَخَيْرُ صُفُوفِ النِّسَاءِ آخِرُهَا، وَشَرُّهَا أَوَّلُهَا."],"takhrij":"صحيح: رواه مسلم في الصلاة (440) من حديث سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (440). Also in Ahmad (10290) with the added opening phrase.","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The best rows of men are the first, and the worst are the last. And the best rows of women are the last, and the worst are the first.” Ahmad’s narration adds at the beginning: “Make your rows straight in prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (440). ورواه أحمد (10290) بزيادة في أوله."},{"num":2310,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَوْ تَعْلَمُونَ - أَوْ يَعْلَمُونَ - مَا فِي الصَّفِّ الْمُقَدَّمِ، لَكَانَتْ قُرْعَةً."],"takhrij":"صحيح: رواه مسلم في الصلاة (439) من حديث شعبة، عن قتادة، عن خِلاس، عن أبي رافع، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (439)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “If you knew (or if they knew) what is in the front row, it would be decided by drawing lots.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (439)."},{"num":2311,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى فِي أَصْحَابِهِ تَأَخُّرًا. فَقَالَ لَهُمْ: تَقَدَّمُوا فَائْتَمُّوا بِي، وَلْيَأْتَمَّ بِكُمْ مَنْ بَعْدَكُمْ. لَا يَزَالُ قَوْمٌ يَتَأَخَّرُونَ حَتَّى يُؤَخِّرَهُمُ اللهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (438) عن شيبان بن فُرُّوخ، ثنا أبو الأشهب، عن أبي نضرة العَبْدِي، عن أبي سعيد فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (438)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ saw some of his Companions staying back, so he said: “Come forward and follow me, and let those behind you follow you. People will keep staying back until Allah puts them back.”"]},"buhuth":{"en":["“Until Allah puts them back” means: away from His mercy, or from great favor, or from higher rank."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (438)."},{"num":2312,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَلَا أَدُلُّكُمْ عَلَى شيء يُكَفِّرُ اللهُ بِهِ الْخَطَايَا، وَيَزِيدُ فِي الْحَسَنَاتِ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: إِسْبَاغُ الْوُضُوءِ فِي الْمَكَارِهِ، وَكَثْرَةُ الخُطى إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ، مَا مِنْكُمْ مِنْ رَجُلٍ يَخْرُجُ مِنْ بَيْتِهِ مُتَطَهِّرًا فَيُصَلِّي مَعَ الْمُسْلِمِينَ الصَّلَاةَ الجامعة، ثُمَّ يَجْلِسُ فِي الْمَسْجِدِ يَنْتَظِرُ الصَّلَاةَ الْأُخْرَى إلا الْمَلِكِ يَقُولُ: اللهُمَّ اغْفِرْ لَهُ، اللهُمَّ ارْحَمْهُ، فَإِذَا قُمْتُمْ إِلَى الصَّلَاةِ فأعدلوا صُفُوفَكُمْ وأقيموا، وَسُدُّوا الْفُرَجَ، فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي، فَإِذَا قَالَ إِمَامُكُمُ: اللهُ أَكْبَرُ، فَقُولُوا: اللهُ أَكْبَرُ، وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللهُمَّ رَبَّنَا لَكَ الْحَمْدُ، وَإِنَّ خَيْرَ الصُّفُوفِ الْمُقَدَّمُ، وَشَرُّهَا الْمُؤَخَّرُ، وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ، وَشَرُّهَا الْمُقَدَّمُ. يَا مَعْشَرَ النِّسَاءِ إِذَا سَجَدَ الرِّجَالُ فاخْفِضْنَ أَبْصَارَكُنَّ، لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ الْأُزُرِ ."],"takhrij":"حسن: رواه أبو يعلى المقصد العلى (برقم 255) حدثنا زهير، ثنا يحيى بن أبي بكير، ثنا زهير بن محمد، عن عبدالله بن محمد بن عقيل، عن سعيد بن المسيب، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good: Narrated by Abū Yaʿlā; its basis is also in Musnad Aḥmad (11007).","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that he heard the Messenger of Allah ﷺ say:“Shall I direct you to that by which Allah erases sins and increases good deeds?” They said:“Yes, O Messenger of Allah.”He said:“Performing wuḍūʾ thoroughly despite difficulties, taking many steps to these mosques, and waiting for one prayer after another.There is no man among you who leaves his house in a state of purification, prays the prayer with the Muslims, and then remains sitting in the place waiting for the next prayer, except that the angels say:‘O Allah, forgive him. O Allah, have mercy upon him.’When you stand for prayer, straighten your rows, make them even, and close the gaps, for indeed I can see you from behind my back.When your imam says, ‘Allāhu akbar,’ then say, ‘Allāhu akbar.’ When he bows, then bow. When he says, ‘Allah hears the one who praises Him,’ then say, ‘O Allah, our Lord, to You belongs all praise.’Indeed, the best rows of the men are the front rows and the worst of them are the rear rows; and the best rows of the women are the rear rows and the worst of them are the front rows.O company of women, when the men prostrate, lower your gazes so that you do not see the private parts of the men because of the shortness of their lower garments.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى، وأصله في مسند أحمد (11007)."},{"num":2313,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَيْرُ صُفُوفِ الرِّجَالِ مُقَدَّمُهَا، وَشَرُّهَا مُؤَخَّرُهَا، وَخَيْرُ صُفُوفِ النِّسَاءِ مُؤَخَّرُهَا، وَشَرُّهَا مُقَدَّمُهَا."],"takhrij":"حسن: رواه ابن ماجه (1001) عن علي بن محمد، قال: حدثنا وكيع، عن سفيان، عن عبدالله بن محمد بن عقيل، عن جابر فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (1001)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn ‘Abdullah reported that the Messenger of Allah ﷺ said: “The best rows of men are the front, and the worst are the back; and the best rows of women are the back, and the worst are the front.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1001)."},{"num":2314,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن عَوْفٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ وَمَلاَئِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الأَوَّلِ ."],"takhrij":"حسن: رواه ابن ماجه (999) عن محمد بن المُصفَّى الحِمْصي، ثنا أنس بن عِياض، ثنا محمد بن عمرو بن علقمة، عن إبراهيم بن عبدالرحمن بن عوف، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (999)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["‘Abd al-Rahman ibn ‘Awf reported that the Messenger of Allah ﷺ said: “Allah and His angels send blessings upon the first row.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (999)."},{"num":2315,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَخَلَّلُ الصَّفَّ مِنْ نَاحِيَةٍ إِلَى نَاحِيَةٍ، يَمْسَحُ صُدُورَنَا وَمَنَاكِبَنَا وَيَقُولُ: لاَ تَخْتَلِفُوا فَتَخْتَلِفَ قُلُوبُكُمْ. وَكَانَ يَقُولُ إِنَّ اللَّهَ وَمَلاَئِكَتَهُ يُصَلُّونَ عَلَى الصُّفُوفِ الأُوَلِ."],"takhrij":"صحيح: رواه أبو داود (664)، والنسائي (811) كلاهما من طريق أبي الأحوص، عن منصور، عن طلحة بن مُصَرِّف، عن عبدالرحمن بن عوسجة، عن البراء فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (664); al-Nasa’i (811); Ibn Hibban (2157)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: The Messenger of Allah ﷺ would move through the rows from side to side, wiping our chests and shoulders, and saying: “Do not differ (in your rows), lest your hearts differ.” And he used to say: “Allah and His angels send blessings upon the front rows.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[565],"tks":"صحيح: رواه أبو داود (664)، النسائي (811)، ابن حبان (2157)."},{"num":2316,"demo":false,"sanad":"","matn":["عَنْ عِرْبَاضِ بْنِ سَارِيَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْتَغْفِرُ لِلصَّفِّ الْمُقَدَّمِ، ثَلاَثًا، وَلِلثَّانِي، مَرَّةً."],"takhrij":"صحيح: أخرجه ابن ماجه (996) قال: حدثنا أبو بكر بن أبي شيبة قال: حدّثنا يزيد بن هارون، قال: أنبأنا هشام الدستوائي، عن يحيى بن أبي كثير، عن محمد بن إبراهيم، عن خالد بن معدان، عن العرباض فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (996); al-Hakim (788)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Al-‘Irbad ibn Sariyah reported that the Messenger of Allah ﷺ would seek forgiveness for the front row three times, and for the second row once."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (996)، الحاكم (788)."},{"num":2317,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ، وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ، أَوِ الصُّفُوفِ الْأُولَى."],"takhrij":"حسن: رواه أحمد (18364) والبزار الكشف (508) كلاهما من طريق حسين بن واقد، حدثني سماك بن حرب، عن النعمان بن بشير فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (18364); al-Bazzar (al-Kashf, 508)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: I heard the Prophet ﷺ say: “Indeed Allah, Mighty and Majestic, and His angels send blessings upon the first row—or upon the first rows.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18364)، والبزار في كشف الأستار (508)."},{"num":2318,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى وَمَلائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الأَوَّلِ."],"takhrij":"حسن: رواه البزار ـ\"كشف الأستار\" ـ (507) عن العباس بن عبدالعظيم العنبري، ثنا عبد الرزاق، أنا معمر، عن عبدالله بن محمد بن عقيل، عن جابر، فذكر الحديث .","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bazzar, Kashf al-Astar (507)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn ‘Abdullah reported that the Prophet ﷺ said: “Indeed Allah, Blessed and Exalted, and His angels send blessings upon the first row.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (507)."},{"num":2319,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَزَالُ قَوْمٌ يَتَأَخَّرُونَ عَنِ الصَّفِّ الأَوَّلِ حَتَّى يُؤَخِّرَهُمُ اللَّهُ فِي النَّارِ."],"takhrij":"حسن إلا قوله: في النار : رواه أبو داود (679) من طريق عبدالرزاق، عن عكرمة بن عمار، عن يحيى بن أبي كثير، عن أبي سلمة، عن عائشة فذكرت الحديث. وهو في مصنف عبدالرزاق (2/52).","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصف الأول","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good\nAbu Dawud (679); also in Musannaf ‘Abd al-Razzaq (2/52); and through this route: Ibn Khuzaymah (1559), Ibn Hibban (2156)","chapter_en":"The virtue of the first row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":29,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said: “People will continue to stay back from the first row until Allah puts them back in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (679)، ورواه عبد الرزاق في المصنف (2/52)، ومن طريقه ابن خزيمة (1559)، وابن حبان (2156)."},{"num":2320,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ سَوُّوا صُفُوفَكُمْ، فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ إِقَامَةِ الصَّلاَةِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (723)، ومسلم في الصلاة (433) كلاهما من حديث شُعبة، قال: سمعت قتادة، يحدث عن أنس بن مالك فذكره. واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (723) — wording his; Muslim (433)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “Straighten your rows, for straightening the rows is part of establishing the prayer.”"]},"buhuth":{"en":["Muslim’s wording is: “Straightening the row is part of completing the prayer.” It appears the narrators reported the meaning, since “establishing the prayer” and “completing the prayer” are close in meaning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (723)، واللفظ له، مسلم (433)."},{"num":2321,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: أُقِيمَتِ الصَّلاَةُ، فَأَقْبَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَجْهِهِ فَقَالَ: أَقِيمُوا صُفُوفَكُمْ وَتَرَاصُّوا، فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي."],"takhrij":"متفق عليه: رواه البخاري في الأذان (719)، ومسلم في الصلاة (434) كلاهما من أوجه عن أنس بن مالك واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (719) — wording his; Muslim (434). Also in al-Bukhari (725) with additional wording; and in ‘Abd al-Razzaq (2/44).","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Anas said: The prayer was established, and the Messenger of Allah ﷺ turned to face us and said: “Straighten your rows and stand close together, for I can see you from behind my back.” In a narration in al-Bukhari: One of us would press his shoulder to his companion’s shoulder and his foot to his companion’s foot. In ‘Abd al-Razzaq’s narration: “Keep checking these rows, for I can see you from behind me.”"]},"buhuth":{"en":["“Stand close together” means to be tightly aligned with no gaps, and it may emphasize “straighten your rows.” “Straighten” means to align evenly and close openings. The majority understood “I can see you from behind my back” literally, as a special honor and ability granted to the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (719)، واللفظ له، ومسلم (434). ورواه البخاري أيضا (725) بلفظ زائد، وعبد الرزاق (2/44)."},{"num":2322,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ قَدِمَ الْمَدِينَةَ، فَقِيلَ لَهُ: مَا أَنْكَرْتَ مِنَّا مُنْذُ يَوْمِ عَهِدْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَنْكَرْتُ شَيْئًا إِلاَّ أَنَّكُمْ لاَ تُقِيمُونَ الصُّفُوفَ."],"takhrij":"صحيح: رواه البخاري في الأذان (724) من طريق بُشَير بن يسار الأنصاري، عن أنس بن مالك. فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (724)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik al-Ansari came to Madinah and was asked: “What have you found changed in us since the days you knew the Messenger of Allah ﷺ?” He said: “I have not found anything changed except that you do not straighten the rows.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (724)."},{"num":2323,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: اسْتَوُوا اسْتَوُوا، اسْتَوُوا فَوَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لأَرَاكُمْ مِنْ خَلْفِي، كَمَا أَرَاكُمْ مِنْ بَيْنِ يَدَىَّ."],"takhrij":"صحيح: رواه النسائي (813) قال: حدثنا أبو بكر بن نافع، قال: حدثنا بهز بن أسد، قال: حدثنا حمد بن سلمة، عن ثابت، عن أنس فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (813)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Anas said: The Prophet ﷺ used to say: “Be straight, be straight, be straight. By the One in whose hand is my soul, I can see you from behind me just as I can see you in front of me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (813)."},{"num":2324,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رُصُّوا صُفُوفَكُمْ، وَقَارِبُوا بَيْنَهَا، وَحَاذُوا بِالأَعْنَاقِ، فَوَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لأَرَى الشَّيْطَانَ يَدْخُلُ مِنْ خَلَلِ الصَّفِّ كَأَنَّهَا الْحَذَفُ."],"takhrij":"صحيح: أخرجه أبو داود (667)، والنسائي (815) كلاهما من طريق أبان، عن قتادة، عن أنس بن مالك فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (667); al-Nasa’i (815); Ibn Khuzaymah authenticated it (1545); Ibn Hibban (2166)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ said: “Pack your rows tightly, bring them close together, and align the necks (stand straight). By the One in whose hand is my soul, I see the devil entering through the gaps in the row as if they were small black sheep.”"]},"buhuth":{"en":["“Al-hadhaf” refers to small black sheep; singular: “hadhafah.” Another wording says: “as if they were the young of hadhaf.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (667)، والنسائي (815)، وصححه ابن خزيمة (1545)، ورواه ابن حبان (2166)."},{"num":2325,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتِمُّوا الصَّفَّ الْمُقَدَّمَ، ثُمَّ الَّذِي يَلِيهِ، فَمَا كَانَ مِنْ نَقْصٍ فَلْيَكُنْ فِي الصَّفِّ الْمُؤَخَّرِ."],"takhrij":"صحيح: أخرجه أبو داود (671) والنسائي (818) كلاهما من حديث سعيد، عن قتادة، عن أنس بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (671); al-Nasa’i (818); Ahmad (12352); Ibn Khuzaymah authenticated it (1546)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ said: “Complete the front row, then the one after it. Whatever deficiency remains, let it be in the back row.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (671)، والنسائي (818)، وأحمد (12352)، وصححه ابن خزيمة (1546)."},{"num":2326,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَذَكَرَ أَحَادِيثَ مِنْهَا ، وَقَالَ : أَقِيمُوا الصَّفَّ فِي الصَّلَاةِ، ، فَإِنَّ إِقَامَةَ الصَّفِّ مِنْ حُسْنِ الصَّلَاةِ."],"takhrij":"متفق عليه: أخرجه مسلم في الصلاة (435) عن محمد بن رافع، عن عبد الرزاق، حدثنا معمر، عن همام بن مُنَبِّه قال: هذا ما حدثنا أبو هريرة عن رسول الله صلى الله عليه وسلم فذكر أحاديث منها هذا.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMuslim (435); al-Bukhari (722)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Make the row straight in prayer, for straightening the row is part of the excellence of prayer.”"]},"buhuth":{"en":["The phrase “part of the excellence of prayer” is evidence that straightening the rows is a confirmed Sunnah: “excellence” indicates something beyond the bare minimum of validity. Only Ibn Hazm is well-known for holding it to be strictly obligatory."]}},"tuhfa":{},"voc":["ibnhibban",1571],"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (435)، البخاري (722)."},{"num":2327,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ يَقُولُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَتُسَوُّنَّ صُفُوفَكُمْ، أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ."],"takhrij":"متفق عليه: أخرجه البخاري في الأذان (717)، ومسلم في الصلاة (436) كلاهما من حديث شعبة، قال: أخبرني عمرو بن مرة، قال: سمعتُ سالم بن أبي الجعد، قال: سمعتُ النعمان بن بشير فذكر الحديث. ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (717); Muslim (436). Also Abu Dawud (662).","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: The Prophet ﷺ said: “You must straighten your rows, or Allah will cause discord between your faces.” In Muslim’s narration: The Messenger of Allah ﷺ used to straighten our rows as if he were straightening arrow-shafts… then one day he came out and stood, about to begin, and he saw a man whose chest was protruding out of the row, so he said: “Servants of Allah, you must straighten your rows, or Allah will cause discord between your faces.” Abu Dawud narrates: “Straighten your rows” three times… “By Allah, you will straighten your rows or Allah will cause discord between your hearts.” He said: I saw a man pressing his shoulder to his companion’s shoulder, his knee to his companion’s knee, and his heel to his companion’s heel. And in another authentic narration: The Messenger of Allah ﷺ would straighten our rows when we stood for prayer; once we were straight, he would say “Allāhu akbar.”"]},"buhuth":{"en":["Abu Dawud’s wording explains “discord between your faces” as meaning: discord, enmity, and hearts differing—this is how al-Nawawi explained it. Some also said it could be taken literally as a form of transformation, though the common scholarly explanation is the first.","“Qidah” are arrow-shafts (before the head and feathers are attached). The meaning is emphasis: he straightened the rows with great care, like straightening perfectly aligned arrow-shafts."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (717)، ومسلم (436)، ورواه أبو داود (662)."},{"num":2328,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُ مَنَاكِبَنَا فِي الصَّلَاةِ وَيَقُولُ: اسْتَوُوا، وَلَا تَخْتَلِفُوا، فَتَخْتَلِفَ قُلُوبُكُمْ. لِيَلِنِي مِنْكُمْ أُولُو الْأَحْلَامِ وَالنُّهَى، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ.","قَالَ أَبُو مَسْعُودٍ: فَأَنْتُمُ الْيَوْمَ أَشَدُّ اخْتِلَافًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (432) من طريق الأعمش، عن عُمارة ابن عمير التيمي، عن أبي مَعْمر، عن أبي مسعود فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (432)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Abu Mas‘ud said: The Messenger of Allah ﷺ used to wipe our shoulders in prayer and say: “Be straight and do not differ, lest your hearts differ. Let those of maturity and sound understanding stand closest to me, then those after them, then those after them.” Abu Mas‘ud said: “But today you are even more divided.”"]},"buhuth":{"en":["“People of maturity” means those with sound judgment (often understood as adults). “Al-nuha” means intellects. The instruction that such people stand closest to the imam is so they can understand and preserve the imam’s prayer, step in if something happens, and correct him if he forgets—among other practical benefits. (Explanation attributed to al-Khattabi.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (432)."},{"num":2329,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ:  خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا لِي أَرَاكُمْ رَافِعِي أَيْدِيكُمْ كَأَنَّهَا أَذْنَابُ خَيْلٍ شُمْسٍ!! اسْكُنُوا فِي الصَّلَاةِ!. قَالَ: ثُمَّ خَرَجَ عَلَيْنَا فَرَآنَا حَِلَقًا فَقَالَ: مَا لِي أَرَاكُمْ عِزِينَ!! قَالَ: ثُمَّ خَرَجَ عَلَيْنَا فَقَالَ: أَلَا تَصُفُّونَ كَمَا تَصُفُّ الْمَلَائِكَةُ عِنْدَ رَبِّهَا؟ فَقُلْنَا: يَا رَسُولَ اللَّهِ، وَكَيْفَ تَصُفُّ الْمَلَائِكَةُ عِنْدَ رَبِّهَا؟ قَالَ: يُتِمُّونَ الصُّفُوفَ الْأُوَلَ، وَيَتَرَاصُّونَ فِي الصَّفِّ."],"takhrij":"رواه مسلم في الصلاة (430) من حديث الأعمش، عن المسيب بن رافع، عن تميم بن طرفة، عن جابر بن سمرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (430)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ came out to us and said: “Why do I see you raising your hands as if they were the tails of restless horses? Be calm in prayer.” Then he came out and saw us in circles and said: “Why do I see you scattered in groups?” Then he came out and said: “Will you not line up as the angels line up before their Lord?” We said: “O Messenger of Allah, how do the angels line up before their Lord?” He said: “They complete the first rows and stand tightly together in the row.”"]},"buhuth":{"en":["“Shumus” refers to animals that are restless and do not stay still. “In circles” means they were sitting/standing in separate circles (groups). “Scattered” means divided into separate clusters. The narrations discourage disorder and division and command orderly rows and unity."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (430)."},{"num":2330,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَقِيمُوا الصُّفُوفَ، وَحَاذُوا بَيْنَ الْمَنَاكِبِ، وسُدُّوا الْخَلَلَ، وَلِينُوا بِأَيْدِي إِخْوَانِكُمْ، وَلاَ تَذَرُوا فُرُجات لِلشَّيْطَانِ، وَمَنْ وَصَلَ صفّاً وَصَلَهُ اللَّهُ، وَمَنْ قَطَعَ صفّاً قَطَعَهُ اللَّهُ ."],"takhrij":"صحيح: رواه أبو داود (666) حدثنا عيسى بن إبراهيم الغافقي، حدثنا ابن وهب، ح وحدثنا قتيبة بن سعيد، حدثنا الليث، وحديث ابن وهب أتم، عن معاوية بن صالح، عن أبي الزاهرية، عن كثير بن مرة، عن عبدالله بن عمر فذكر مثله. وهذا إسناد صحيح موصول.","grade":"صحيح","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (666). Al-Nasa’i (819) narrates it in a shorter form: “Whoever connects a row, Allah connects him; and whoever breaks a row, Allah cuts him off.”","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Straighten the rows, align the shoulders, close the gaps, be gentle and yield to the hands of your brothers (when they adjust you), and do not leave openings for Satan. Whoever connects a row, Allah will connect him; and whoever breaks a row, Allah will cut him off.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (666)، ورواه النسائي (819) بلفظ مختصر: «من وصل صفا وصله الله، ومن قطع صفا قطعه الله»."},{"num":2331,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ عليهم السلام، يُصَلُّونَ عَلَى الَّذِينَ يَصِلُونَ الصُّفُوفَ."],"takhrij":"حسن: أخرجه أحمد (24381) قال: حدثنا عبدالله بن الوليد، حدثنا سفيان، عن أسامة، عن عبدالله بن عروة، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (24381)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said: “Indeed Allah, Mighty and Majestic, and His angels, peace be upon them, send blessings upon those who connect the rows.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[564],"tks":"حسن: رواه أحمد (24381)."},{"num":2332,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ تَمَامِ الصَّلَاةِ إِقَامَةَ الصَّفِّ."],"takhrij":"حسن: رواه أحمد (14454) عن عبدالرزاق ـ وهو في المصنف (2/44) عن معمر، عن عبدالله بن محمد بن عقيل، عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (14454) via ‘Abd al-Razzaq (and it is in al-Musannaf 2/44)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: The Messenger of Allah ﷺ said: “Indeed, part of completing the prayer is straightening the row.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (14454)."},{"num":2333,"demo":false,"sanad":"","matn":["عَنْ بِلَالٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُسَوِّي مَنَاكِبَنَا فِي الصَّلَاةِ."],"takhrij":"حسن: رواه الطبراني في الصغير (988) عن محمد بن علي بن خلف الدمشقي، ثنا أحمد بن أبي الحواري، ثنا عبدالله بن نمير، عن الأعمش، عن عمران بن مسلم، عن سويد بن غفلة، عن بلال فذكر الحديث. مجمع البحرين (754).","grade":"حسن","chapter_ar":"باب ما جاء في تسوية الصفوف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Saghir (988) (also cited in Majma‘ al-Bahrayn, no. 754)","chapter_en":"Straightening the rows","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":30,"content":{"translation":{"en":["Bilal said: The Prophet ﷺ used to straighten our shoulders in prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الصغير (988) (ومذكور أيضا في مجمع البحرين, رقم 754)."},{"num":2334,"demo":false,"sanad":"","matn":["عَنْ عبدالحميد بن محمود قَالَ: صلَّيتُ مَعَ أَنَسِ بْنِ مَالِكٍ يَوْمَ الْجُمُعَةِ فَدُفِعْنَا إِلَى السَّوَارِي، فَتَقَدَّمْنَا وَتَأَخَّرْنَا، فَقَالَ أَنَسٌ: كنَّا نَتَّقِي هَذَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ."],"takhrij":"حسن: رواه أبو داود (673) واللفظ له، والترمذي (229)، والنسائي (821) كلهم من طريق سفيان، عن يحيى بن هانئ، عن عبدالحميد بن محمود فذكر الحديث، ولفظهما: كنَّا مع أنس فصلَّينا مع أمير من الأمراء، فدفعوا حتى قمنا وصلَّينا بين الساريتين، فجلس أنس يتأخر وقال: فذكر كما ذكره أبو داود.","grade":"حسن","chapter_ar":"باب كراهية الصف بين السواري","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (673) — wording his; al-Tirmidhi (229); al-Nasa’i (821)","chapter_en":"Disliking forming a row between pillars","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":31,"content":{"translation":{"en":["‘Abd al-Hamid ibn Mahmud said: I prayed Jumu‘ah with Anas ibn Malik, and we were pushed toward the pillars. So we moved forward and back. Anas said: “We used to avoid this during the time of the Messenger of Allah ﷺ.”"]},"buhuth":{"en":["Al-Tirmidhi graded it as hasan (and in one report: sahih). Some scholars disliked rows between pillars (including Ahmad and Ishaq), while others permitted it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (673) واللفظ له، والترمذي (229)، والنسائي (821)."},{"num":2335,"demo":false,"sanad":"","matn":["عَنْ وَابِصَةَ بْنِ مَعْبَدٍ، أَنَّ رَجُلاً، صَلَّى خَلْفَ الصَّفِّ وَحْدَهُ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعِيدَ الصَّلاَةَ."],"takhrij":"حسن: رواه أبو داود (682)، والترمذي (231) كلاهما من طريق شُعبة، عن عمرو بن مرة، عن هلال بن يساف، عن عمرو بن راشد، عن وابصة بن معبد فذكر الحديث.","grade":"حسن","chapter_ar":"باب كراهية من يصلي وحده خلف الصف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (682); al-Tirmidhi (231)","chapter_en":"Disliking someone praying alone behind the row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":32,"content":{"translation":{"en":["Wabisah ibn Ma‘bad reported: A man prayed alone behind the row, so the Prophet ﷺ ordered him to repeat the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (682)، الترمذي (231)."},{"num":2336,"demo":false,"sanad":"","matn":["عَنْ علي بن شيبان، وَكَانَ مِنَ الْوَفْدِ قَالَ: خَرَجْنَا حَتَّى قَدِمْنَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْنَاهُ، وَصَلَّيْنَا خلْفَه، ثُمَّ صلَّينا وَرَاءَهُ صَلاَةً أُخْرَى، فَقَضَى الصَّلاَةَ. فَرَأَى رَجُلاً فَرْدًا يُصَلِّي خلْف الصَّفِّ قَالَ: فَوَقَفَ عَلَيْهِ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ انْصَرَفَ فَقَالَ: اسْتَقْبِلْ صَلاَتَكَ، ولا صَلاَةَ لِلَّذِي خَلْفَ الصفِّ ."],"takhrij":"صحيح: رواه ابن ماجه (1003) عن أبي بكر بن أبي شيبة، حدثنا ملازم بن عمرو، عن عبدالله بن بدر، قال: حدثني عبدالرحمن بن علي بن شيبان، عن أبيه على ابن شيبان فذكره، وهو في مصنف ابن أبي شيبة (5888).","grade":"صحيح","chapter_ar":"باب كراهية من يصلي وحده خلف الصف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1003); Ibn Abi Shaybah (2/193); Ibn Khuzaymah authenticated it (1569)","chapter_en":"Disliking someone praying alone behind the row","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":32,"content":{"translation":{"en":["‘Ali ibn Shayban—who was among a delegation—said: We came to the Prophet ﷺ, pledged allegiance to him, and prayed behind him. Then we prayed another prayer behind him. When he finished, he saw a man praying alone behind the row. The Prophet of Allah ﷺ stood over him after finishing and said: “Repeat your prayer, for there is no prayer for the one who prays behind the row.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1003)، ابن أبي شيبة (5888)، ابن خزيمة وصححه (1569)."},{"num":2337,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، أَنَّهُ انْتَهَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ رَاكِعٌ، فَرَكَعَ قَبْلَ أَنْ يَصِلَ إِلَى الصَّفِّ، فَذَكَرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: زَادَكَ اللَّهُ حِرْصًا، وَلاَ تَعُدْ."],"takhrij":"صحيح: رواه البخاري في الأذان (783) عن موسى بن إسماعيل، قال: حدثنا همام، عن الأعلم -وهو زياد- عن الحسن، عن أبي بكرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا أدرك الرجل الإمام في الركوع فقد أدرك الركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (783). Abu Dawud (684) also narrates it with the wording that he bowed behind the row, then walked to the row, and the Prophet ﷺ said the same.","chapter_en":"If a person catches the imam in bowing, he has caught that unit (rak‘ah)","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":33,"content":{"translation":{"en":["Abu Bakrah reported that he came to the Prophet ﷺ while he was in bowing, so he bowed before reaching the row. He mentioned that to the Prophet ﷺ, and he said: “May Allah increase you in eagerness, but do not do that again.”"]},"buhuth":{"en":["It is also authentically reported that Zayd ibn Thabit bowed when he found the people already in bowing, then moved forward until he reached the row. Likewise, with Ibn Mas‘ud: he bowed in the middle of the mosque when the imam bowed, then they moved forward while bowing until they reached the row; afterward Ibn Mas‘ud told him he had caught the unit.","This is evidence for the majority view: whoever catches the imam in bowing has caught the rak‘ah—because the Prophet ﷺ did not instruct Abu Bakrah to make up that unit, and clarification is not normally delayed beyond the time of need."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (783). أبو داود (684) ورواه أيضا بلفظ أنه ركع دون الصف ثم مشى إلى الصف، فقال له النبي ﷺ مثل ذلك."},{"num":2338,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا جِئْتُمْ وَالْإِمَامُ رَاكِعٌ فَارْكَعُوا، وَإِنْ كَانَ سَاجِدًا فَاسْجُدُوا، وَلَا تَعْتَدُّوا بِالسُّجُودِ إِذَا لَمْ يَكُنْ مَعَهُ الرُّكُوعُ."],"takhrij":"صحيح: رواه البيهقي (2576) عن أبي عبد الله الحافظ، قال: أخبرني محمد بن أحمد بن بالويه، ثنا محمد بن غالب، حدثني عمرو بن مرزوق، أخبرنا شعبة، عن عبدالعزيز بن رفيع، عن رجل، عن النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب إذا أدرك الرجل الإمام في الركوع فقد أدرك الركعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bayhaqi (2/89)","chapter_en":"If a person catches the imam in bowing, he has caught that unit (rak‘ah)","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":33,"content":{"translation":{"en":["A man reported from the Prophet ﷺ: “If you come while the imam is bowing, then bow; and if he is prostrating, then prostrate—but do not count the prostration if it was not accompanied by bowing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي (2576)."},{"num":2339,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ فِي حُجْرَتِهِ، وَجِدَارُ الْحُجْرَةِ قَصِيرٌ، فَرَأَى النَّاسُ شَخْصَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ أُنَاسٌ يُصَلُّونَ بِصَلاَتِهِ، فَأَصْبَحُوا فَتَحَدَّثُوا بِذَلِكَ، فَقَامَ لَيْلَةَ الثَّانِيَةِ، فَقَامَ مَعَهُ أُنَاسٌ يُصَلُّونَ بِصَلاَتِهِ، صَنَعُوا ذَلِكَ لَيْلَتَيْنِ أَوْ ثَلاَثَةً، حَتَّى إِذَا كَانَ بَعْدَ ذَلِكَ جَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَخْرُجْ، فَلَمَّا أَصْبَحَ ذَكَرَ ذَلِكَ النَّاسُ، فَقَالَ: إِنِّي خَشِيتُ أَنْ تُكْتَبَ عَلَيْكُمْ صَلاَةُ اللَّيْلِ."],"takhrij":"صحيح: رواه البخاري في الأذان (729) من طريق يحيى بن سعيد الأنصاريّ، عن عمرة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الرجل يأتم بالإمام وبينهما جدار","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (729)","chapter_en":"Following the imam while a wall is between them","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":34,"content":{"translation":{"en":["‘A’ishah, the Mother of the Believers, said: The Messenger of Allah ﷺ used to pray at night in his room, and the wall of the room was short, so people saw the outline of the Prophet ﷺ. Some men stood and prayed following his prayer. In the morning they spoke about it. The next night he stood again and some people prayed following him. They did that for two or three nights. Then afterward the Messenger of Allah ﷺ remained seated and did not come out. In the morning the people mentioned that, and he said: “I feared that the night prayer would be made obligatory upon you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (729)."},{"num":2340,"demo":false,"sanad":"","matn":["عَنْ أُمِّ وَرَقَةَ بِنْتِ نَوْفَلٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا غَزَا بَدْرًا، قَالَتْ: قُلْتُ لَهُ يَا رَسُولَ اللَّهِ ائْذَنْ لِي فِي الْغَزْوِ مَعَكَ أُمَرِّضُ مَرْضَاكُمْ لَعَلَّ اللَّهَ أَنْ يَرْزُقَنِي شَهَادَةً. قَالَ قِرِّي فِي بَيْتِكِ فَإِنَّ اللَّهَ تَعَالَى يَرْزُقُكِ الشَّهَادَةَ.","قَالَ: فَكَانَتْ تُسَمَّى الشَّهِيدَةَ. قَالَ: وَكَانَتْ قَدْ قَرَأَتِ الْقُرْآنَ، فَاسْتَأْذَنَتِ النَّبِيَّ صلى الله عليه وسلم أَنْ تَتَّخِذَ فِي دَارِهَا مُؤَذِّنًا. فَأَذِنَ لَهَا، قَالَ: وَكَانَتْ قد دَبَّرَتْ غُلاَمًا لَهَا وَجَارِيَةً، فَقَامَا إِلَيْهَا بِاللَّيْلِ فَغَمَّاهَا بِقَطِيفَةٍ لَهَا حَتَّى مَاتَتْ وَذَهَبَا. فَأَصْبَحَ عُمَرُ فَقَامَ فِي النَّاسِ، فَقَالَ: مَنْ كَانَ عِنْدَهُ مِنْ هَذَيْنِ عِلْمٌ، أَوْ مَنْ رَآهُمَا فليجيء بِهِمَا، فَأَمَرَ بِهِمَا فَصُلِبَا. فَكَانَا أَوَّلَ مَصْلُوبٍ بِالْمَدِينَةِ.","وفي رواية: وكان رسول الله صلى الله عليه وسلم يزورها في بيتها، وجعل لها مؤذِّناً يؤذِّنُ لها، وأمرها أن تؤم أهلَ دارها. قال عبدالرحمن: فأنا رأيتُ مؤذنها شيخاً كبيراً."],"takhrij":"حسن: رواه أبو داود (591) وأحمد (27283) والدارقطني (1/403) كلهم من حديث الوليد بن عبدالله بن جُميع، قال: حدَّثَتْني جدتي وعبدالرحمن ابن خلاد الأنصاري، عن أم ورقة بنت نوفل فذكرت الحديث. كذا ذكره أبو داود عبدَ الرحمن بن خلاد مقرونا،","grade":"حسن","chapter_ar":"باب ما جاء في إمامة النساء للنساء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (591, 592); Ahmad (27283); al-Daraqutni (1/403); Ibn Khuzaymah (1676)","chapter_en":"Women leading women in prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":35,"content":{"translation":{"en":["Umm Waraqah bint Nawfal reported that when the Prophet ﷺ went out for Badr, she said: “O Messenger of Allah ﷺ, permit me to go out with you so I may nurse your wounded—perhaps Allah will grant me martyrdom.” He said: “Remain in your house, for Allah will grant you martyrdom.” So she was called “the martyr.” She had recited the Qur’an, and she asked the Prophet ﷺ for permission to appoint a caller to prayer in her house, and he granted her permission. She had also arranged for a male servant and a female servant to be freed after her death; they came to her at night and smothered her with a cloak until she died, then fled. ‘Umar addressed the people in the morning and ordered that whoever knew of them or saw them bring them, and he ordered them crucified—so they were the first to be crucified in Madinah.","In another narration: The Messenger of Allah ﷺ used to visit her in her home, he appointed a caller to prayer for her, and he instructed her to lead the people of her household in prayer. ‘Abd al-Rahman said: I saw her caller to prayer as an elderly man."]},"buhuth":{"en":["Imam Ahmad recommended that a woman may lead other women in congregational prayer, and this is also reported as the view of ‘A’ishah and Umm Salamah, and held by al-Shafi‘i, Ishaq, and others (as mentioned in al-Mughni 3/37)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (591، 592)، أحمد (27283)، الدارقطني (1/403)، ابن خزيمة (1676)."},{"num":2341,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ: كَانَ رِجَالٌ يُصَلُّونَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَاقِدِي أُزْرِهِمْ عَلَى أَعْنَاقِهِمْ كَهَيْئَةِ الصِّبْيَانِ، وَقَالَ لِلنِّسَاءِ: لاَ تَرْفَعْنَ رُءُوسَكُنَّ حَتَّى يَسْتَوِيَ الرِّجَالُ جُلُوسًا."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (362) عن مسدد قال: حدثنا يحيى (وهو ابن سعيد) عن سفيان قال: حدثني أبو حازم، عن سهل فذكره.","grade":"متفق عليه","chapter_ar":"باب أمر النساء أن لا يرفعنَ رؤوسهُنَّ من السجود حتى يرفع الرجالُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (362); Muslim (441)","chapter_en":"Women are instructed not to raise their heads from prostration until the men have raised theirs","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":36,"content":{"translation":{"en":["Sahl ibn Sa‘d said: Men used to pray with the Prophet ﷺ while tying their waist-wrappers up around their necks, like children (because of tight clothing). And he said to the women: “Do not raise your heads until the men have settled into sitting upright.”"]},"buhuth":{"en":["Muslim’s report includes the call: “O women, do not raise your heads,” and it is mentioned that the caller may have been the Prophet ﷺ himself, or Bilal conveying it from him. Ibn Khuzaymah and Ibn Hibban narrate from Abu Hazim (from Sahl) that women were instructed in the Prophet’s time not to raise their heads until men had fully sat, due to tight clothing."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2555],"tks":"متفق عليه: رواه البخاري (362)، مسلم (441)."},{"num":2342,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلاَ تَرْفَعْ رَأْسَهَا حَتَّى يَرْفَعَ الرِّجَالُ رُءُوسَهُمْ."],"takhrij":"صحيح: رواه أبو داود (851) حدثنا محمد بن المتوكل العسقلاني، حدثنا عبدالرزاق، أنبانا معمر، عن عبدالله بن مسلم أخي الزهري، عن مولى لأسماء بنت أبي بكر، عنها فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب أمر النساء أن لا يرفعنَ رؤوسهُنَّ من السجود حتى يرفع الرجالُ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (851)","chapter_en":"Women are instructed not to raise their heads from prostration until the men have raised theirs","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب الإمامة","group_en":"Chapters on leading the prayer","part_no":9,"group_no":7,"chapter_no":36,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: I heard the Messenger of Allah ﷺ say: “Whoever among you believes in Allah and the Last Day should not raise her head until the men have raised their heads.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (851)."},{"num":2343,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: صَلاَةُ الْجَمَاعَةِ تَفْضُلُ صَلاَةَ الفذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (1) عن نافع، عن عبدالله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (1); al-Bukhari (645); Muslim (650)","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Prayer in congregation surpasses praying alone by twenty-seven degrees.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1)، البخاري (645)، مسلم (650)."},{"num":2344,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  صَلَاةُ الْجَمَاعَةِ أَفْضَلُ مِنْ صَلَاةِ أَحَدِكُمْ وَحْدَهُ بِخَمْسَةٍ وَعِشْرِينَ جُزْءًا."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (2) عن ابن شهاب، عن سعيد ابن المسيب، عن أبي هريرة فذكره. ورواه مسلم في المساجد (649/275) عن يحيى بن يحيى، عن مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (2); Muslim (649/275); al-Bukhari (648)","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Congregational prayer is better than the prayer of one of you alone by twenty-five parts.” And in it: “The angels of the night and the angels of the day gather at the dawn prayer.” Then Abu Hurayrah would say: “Recite if you wish: ‘Indeed the recitation at dawn is witnessed.’” (17:78)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2)، مسلم (649/275)، البخاري (648)."},{"num":2345,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلاَةُ الرَّجُلِ فِي الْجَمَاعَةِ تُضَعَّفُ عَلَى صَلاَتِهِ فِي بَيْتِهِ، وَفِي سُوقِهِ خَمْسًا وَعِشْرِينَ ضِعْفًا، وَذَلِكَ أَنَّهُ إِذَا تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ، لاَ يُخْرِجُهُ إِلاَّ الصَّلاَةُ، لَمْ يَخْطُ خَطْوَةً إِلاَّ رُفِعَتْ لَهُ بِهَا دَرَجَةٌ، وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ، فَإِذَا صَلَّى لَمْ تَزَلِ الْمَلاَئِكَةُ تُصَلِّي عَلَيْهِ مَا دَامَ فِي مُصَلاَّهُ. اللَّهُمَّ صَلِّ عَلَيْهِ، اللَّهُمَّ ارْحَمْهُ. وَلاَ يَزَالُ أَحَدُكُمْ فِي صَلاَةٍ مَا انْتَظَرَ الصَّلاَةَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (647) واللفظ له، ومسلم في المساجد (649) كلاهما عن الأعمش، قال: سمعتُ أبا صالح يقول: سمعتُ أبا هريرة فذكر الحديث، وزاد مسلم: ما لم يؤذِ فيه. ما لم يُحدثْ فيه .","grade":"متفق عليه","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (647) — wording his; Muslim (649)","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “A man’s prayer in congregation is multiplied over his prayer in his home and in his market by twenty-five times. That is because when he performs wudu and perfects his wudu, then goes out to the mosque, with nothing taking him out except the prayer, he does not take a step except that he is raised one degree by it and one sin is removed from him. When he prays, the angels continue to invoke blessings for him as long as he remains in his prayer-place: ‘O Allah, bless him; O Allah, have mercy on him.’ And one of you remains ‘in prayer’ so long as he is waiting for the prayer.” Muslim adds: “So long as he does not harm anyone there, and so long as he does not break his wudu.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (647) - واللفظ له، مسلم (649)."},{"num":2346,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: صَلاَةُ الْجَمَاعَةِ تَفْضُلُ صَلاَةَ الْفَذِّ بِخَمْسٍ وَعِشْرِينَ دَرَجَةً."],"takhrij":"صحيح: رواه البخاري في الأذان (646) عن عبدالله بن يوسف، أخبرنا الليث، حدثني ابن الهاد، عن عبدالله بن خَبَّاب، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (646)","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that he heard the Prophet ﷺ say: “Congregational prayer surpasses praying alone by twenty-five degrees.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (646)."},{"num":2347,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: تَفْضُلُ صَلاةُ الْجَمَاعَةِ عَلَى صَلاةِ الْفَذِّ، أَوْ صَلاةِ الرَّجُلِ وَحْدَهُ خَمْسًا وَعِشْرِينَ صَلاةً."],"takhrij":"حسن: رواه البزار -الكشف (459) عن عبدالملك بن محمد الرقاشي، ثنا حجاج بن المنهال، ثنا حماد بن سلمة، عن عاصم، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ said: “Congregational prayer surpasses praying alone—or a man’s prayer by himself—by twenty-five prayers.”"]},"buhuth":{"en":["al-Bazzar (al-Kashf, 459)","As for the reports mentioning twenty-five and others mentioning twenty-seven, there is no contradiction. It is possible that it was first set as twenty-five, then two more were added, making it twenty-seven—Allah is the Possessor of great bounty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار ( 459)."},{"num":2348,"demo":false,"sanad":"","matn":["عَنْ أُبَىِّ بْنِ كَعْبٍ، قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا الصُّبْحَ فَقَالَ: أَشَاهِدٌ فُلاَنٌ. قَالُوا: لاَ. قَالَ: أَشَاهِدٌ فُلاَنٌ. قَالُوا: لاَ. قَالَ: إِنَّ هَاتَيْنِ الصَّلاَتَيْنِ أَثْقَلُ الصَّلَوَاتِ عَلَى الْمُنَافِقِينَ، وَلَوْ تَعْلَمُونَ مَا فِيهِمَا لأَتَيْتُمُوهُمَا وَلَوْ حَبْوًا عَلَى الرُّكَبِ، وَإِنَّ الصَّفَّ الأَوَّلَ عَلَى مِثْلِ صَفِّ الْمَلاَئِكَةِ، وَلَوْ عَلِمْتُمْ مَا فَضِيلَتُهُ لاَبْتَدَرْتُمُوهُ، وَإِنَّ صَلاَةَ الرَّجُلِ مَعَ الرَّجُلِ أَزْكَى مِنْ صَلاَتِهِ وَحْدَهُ، وَصَلاَتُهُ مَعَ الرَّجُلَيْنِ أَزْكَى مِنْ صَلاَتِهِ مَعَ الرَّجُلِ، وَمَا كَثُرَ فَهُوَ أَحَبُّ إِلَى اللَّهِ تَعَالَى."],"takhrij":"حسن: رواه أبو داود (554) عن حفص بن عمر، والنسائي (844) عن خالد بن الحارث، كلاهما عن شعبة، عن أبي إسحاق، عن عبدالله بن أبي بصير، عن أبيّ بن كعب،","grade":"حسن","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (554); al-Nasa’i (844); Ibn Khuzaymah (1476–1477)","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Ubayy ibn Ka‘b said: The Messenger of Allah ﷺ led us in the dawn prayer one day, then he said: “Is so-and-so present?” They said: “No.” He said: “Is so-and-so present?” They said: “No.” He said: “Indeed these two prayers are the heaviest prayers upon the hypocrites. If you knew what is in them, you would come to them even crawling on your knees. And the first row is like the row of the angels; if you knew its virtue, you would rush to it. And a man’s prayer with another man is purer than his prayer alone; and his prayer with two men is purer than his prayer with one man. And the more numerous it is, the more beloved it is to Allah, Exalted is He.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (554)، والنسائي (844)، وابن خزيمة (1476–1477)."},{"num":2349,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فضلُ صَلاةِ الرَّجُلِ فِي الْجَمْعِ عَلَى صَلاتِهِ -يَعْنِي وَحْدَهُ- خَمْسًا وَعِشْرِينَ صَلاةً ."],"takhrij":"صحيح: رواه البزار كشف الأستار (455) حدثنا محمد بن المثنى وعمرو بن علي قالا: ثنا محمد بن جعفر، ثنا شعبة، عن قتادة، عن عُقبة بن وسَّاج، عن أبي الأحوص، عن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب فضل صلاة الجماعة على صلاة الفذّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bazzar, Kashf al-Astar (455)","chapter_en":"The virtue of congregational prayer over praying alone","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Prophet ﷺ said: “The superiority of a man’s prayer in congregation over his prayer (meaning: alone) is twenty-five prayers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (455)."},{"num":2350,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ! لَقَدْ هَمَمْتُ أَنْ آمُرَ بِحَطَبٍ فَيُحْطَبَ، ثُمَّ آمُرَ بِالصَّلاَةِ فَيُؤَذَّنَ لَهَا، ثُمَّ آمُرَ رَجُلاً فَيَؤُمَّ النَّاسَ، ثُمَّ أُخَالِفَ إِلَى رِجَالٍ، فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ، وَالَّذِي نَفْسِي بِيَدِهِ! لَوْ يَعْلَمُ أَحَدُهُمْ أَنَّهُ يَجِدُ عَرْقًا سَمِينًا، أَوْ مِرْمَاتَيْنِ حَسَنَتَيْنِ لَشَهِدَ الْعِشَاءَ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (3) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الأذان (644) عن عبدالله بن يوسف، أخبرنا مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في وجوب صلاة الجماعة والتشديد في تركها بغير عذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (3); al-Bukhari (644); Muslim (651)","chapter_en":"The obligation of congregational prayer and stern warning for leaving it without excuse","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “By the One in whose hand is my soul! I considered ordering that firewood be gathered, then ordering the prayer and calling the adhan for it, then ordering a man to lead the people, then going to men (who stay back) and burning their houses over them. By the One in whose hand is my soul! If one of you knew he would find a meaty bone—or two good morsels—he would attend ‘Isha.”"]},"buhuth":{"en":["“Al-mirmah” is explained as what is between the two hooves of a sheep (a small piece of meat), and it is also said to mean a kind of arrow used for throwing—this is mentioned in the scholarly explanations."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3)، البخاري (644)، مسلم (651)."},{"num":2351,"demo":false,"sanad":"","matn":["عن أُمِّ الدَّرْدَاءِ تَقُولُ: دَخَلَ عَلَىَّ أَبُو الدَّرْدَاءِ وَهْوَ مُغْضَبٌ، فَقُلْتُ: مَا أَغْضَبَكَ؟ فَقَالَ: وَاللَّهِ مَا أَعْرِفُ مِنْ أُمَّةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا إِلاَّ أَنَّهُمْ يُصَلُّونَ جَمِيعًا."],"takhrij":"صحيح: رواه البخاري في الأذان (650) عن عمر بن حفص، قال: حدثنا أبي، قال: حدثنا الأعمش، قال: سمعتُ سالماً قال: سمعتُ أم الدرداء، فذكرت مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في وجوب صلاة الجماعة والتشديد في تركها بغير عذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (650)","chapter_en":"The obligation of congregational prayer and stern warning for leaving it without excuse","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Umm al-Darda’ said: Abu al-Darda’ entered upon me while angry. I said: “What has upset you?” He said: “By Allah, I do not recognize anything from the community of Muhammad ﷺ except that they still pray together (in congregation).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (650)."},{"num":2352,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قالَ لِقَوْمٍ يَتَخَلَّفُونَ عَنِ الْجُمُعَةِ: لَقَدْ هَمَمْتُ أَنْ آمرَ رَجُلًا يُصَلِّي بِالنَّاسِ، ثُمَّ أحرِّقُ عَلَى رِجَالٍ يتخلَّفُون عَنِ الْجُمُعَةِ بُيُوتَهُمْ ."],"takhrij":"صحيح: رواه مسلم في المساجد (652) عن أحمد بن عبدالله بن يونس، حدثنا زهير، حدثنا أبو إسحاق، عن أبي الأحوص، سمعه منه، عن عبدالله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وجوب صلاة الجماعة والتشديد في تركها بغير عذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (652)","chapter_en":"The obligation of congregational prayer and stern warning for leaving it without excuse","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Prophet ﷺ said regarding people who stay back from Friday prayer: “I considered ordering a man to lead the people in prayer, then burning the houses of men who stay back from Jumu‘ah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3222],"tks":"صحيح: رواه مسلم (652)."},{"num":2353,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ أَنَّهُ قَالَ: مَنْ سَرَّه أَنْ يَلْقَى اللهَ غداً مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ حَيْثُ يُنادَى بِهِنَّ، فَإِنَّ اللَّهَ شَرَعَ لِنَبِيِّكُمْ سُنن الْهُدَى، وإنَّهن مِنْ سُنَنِ الْهُدَى، وَلَوْ أَنَّكُمْ صلَّيتُم فِي بُيُوتِكُمْ كَمَا يُصلِّي هَذَا الْمُتَخَلِّفُ فِي بَيْتِهِ لَتَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ. وَلَوْ تَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ لَضَلَلْتُمْ. وَمَا مِنْ رَجُلٍ يَتَطَهَّرُ فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَعْمِدُ إِلَى مَسْجِدٍ مِنْ هَذِهِ الْمَسَاجِدِ إِلَّا كَتَبَ اللهُ لَهُ بِكُلِّ خَُطْوَةٍ يَخْطُوهَا حَسَنَةً، وَيَرْفَعُهُ بِهَا دَرَجَةً، ويحطُّ عَنْهُ بِهَا سَيِّئَةً. وَلَقَدْ رَأَيْتُنَا وَمَا يَتَخَلَّفُ عَنْهَا إِلَّا مُنَافِقٌ مَعْلُومُ النِّفَاقِ، وَلَقَدْ كَانَ الرَّجُلُ يُوتى بِهِ يُهَادَى بَيْنَ الرَّجُلَيْنِ حَتَّى يُقامَ فِي الصفِّ."],"takhrij":"صحيح: أخرجه مسلم في المساجد (654) عن أبي بكر بن أبي شيبة، حدّثنا الفضل بن دُكين، عن أبي العُميس، عن علي بن الأقمر، عن أبي الأحوص، عن عبدالله بن مسعود قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وجوب صلاة الجماعة والتشديد في تركها بغير عذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (654)","chapter_en":"The obligation of congregational prayer and stern warning for leaving it without excuse","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: Whoever would be pleased to meet Allah tomorrow as a Muslim, let him maintain these prayers where the call is made for them. Allah has legislated for your Prophet ﷺ the ways of guidance, and they are from the ways of guidance. If you prayed in your homes like this one who stays behind prays in his home, you would abandon the Sunnah of your Prophet ﷺ, and if you abandoned the Sunnah of your Prophet ﷺ you would go astray. No man purifies himself and perfects purification, then goes to one of these mosques, except that Allah writes for him a good deed for every step, raises him by a degree, and removes from him a sin. We used to see that none stayed back from it except a hypocrite whose hypocrisy was known. A man would even be brought supported between two men until he was placed in the row."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (654)."},{"num":2354,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ ثَلاَثَةٍ فِي قَرْيَةٍ وَلاَ بَدْوٍ لاَ تُقَامُ فِيهِمُ الصَّلاَةُ إِلاَّ قَدِ اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ، فَعَلَيْكَ بِالْجَمَاعَةِ، فَإِنَّمَا يَأْكُلُ الذِّئْبُ الْقَاصِيَةَ."],"takhrij":"حسن: رواه أبو داود (547)، والنسائي (848) كلاهما من طريق زائدة ابن قدامة قال: حدثنا السائب بن حبيش الكلاعي، عن معدان بن أبي طلحة اليعمري قال: قال لي أبو الدرداء: أين مسكنك؟ قلت: في قرية دُوين حمص، فقال أبو الدرداء: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في وجوب صلاة الجماعة والتشديد في تركها بغير عذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (547); al-Nasa’i (848); Ibn Khuzaymah (1486); al-Hakim (900)","chapter_en":"The obligation of congregational prayer and stern warning for leaving it without excuse","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Abu al-Darda’ said: I heard the Messenger of Allah ﷺ say: “No three people in a village or in the desert who do not establish prayer among themselves except that Satan gains mastery over them. So stick to congregation, for the wolf only eats the one that strays from the flock.”"]},"buhuth":{"en":["Juristic takeaway: Ahmad, al-Bukhari, al-Awza‘i, Abu Thawr, Ibn Khuzaymah, Dawud al-Zahiri, and others held congregational prayer to be obligatory, though Ahmad stated it is not a condition for the prayer’s validity—so if someone leaves it without excuse and prays alone, the prayer is valid but he is sinful for leaving an obligation. Abu Hanifah, Malik, al-Shafi‘i, and others held that congregational prayer is an emphasized Sunnah, and that it is superior to praying alone by twenty-five or twenty-seven degrees as authentically reported."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (547)، والنسائي (848)، وابن خزيمة (1486)، والحاكم (900)."},{"num":2355,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ أَعْمَى فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّهُ لَيْسَ لِي قَائِدٌ يَقُودُنِي إِلَى الْمَسْجِدِ، فَسَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُرَخِّصَ لَهُ فَيُصَلِّيَ فِي بَيْتِهِ. فَرَخَّصَ لَهُ. فَلَمَّا وَلَّى دَعَاهُ فَقَالَ: هَلْ تَسْمَعُ النِّدَاءَ بِالصَّلَاةِ؟ فَقَالَ: نَعَمْ. قَالَ: فَأَجِبْ."],"takhrij":"صحيح: رواه مسلم في المساجد (653) من طريق مروان الفَزاري، عن","grade":"صحيح","chapter_ar":"باب في حضور الجماعة على من سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (653)","chapter_en":"Attending the congregation for the one who hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: A blind man came to the Prophet ﷺ and said: “O Messenger of Allah, I have no guide to lead me to the mosque.” He asked the Messenger of Allah ﷺ to grant him a concession to pray at home, so he granted it. When the man turned to leave, the Prophet ﷺ called him back and said: “Do you hear the call to prayer?” He said: “Yes.” He said: “Then respond.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (653)."},{"num":2356,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أُمِّ مَكْتُومٍ، أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنِّي رَجُلٌ ضَرِيرُ الْبَصَرِ، شَاسِعُ الدَّارِ، وَلِي قَائِدٌ لاَ يُلاَئِمُنِي. فَهَلْ لِي رُخْصَةٌ أَنْ أُصَلِّيَ فِي بَيْتِي؟ قَالَ: هَلْ تَسْمَعُ النِّدَاءَ. قَالَ: نَعَمْ. قَالَ: لاَ أَجِدُ لَكَ رُخْصَةً."],"takhrij":"حسن: رواه أبو داود (552)، وابن ماجة (792) كلاهما من طريق عاصم بن بهدلة، عن أبي رَزين، عن ابن أم مكتوم فذكره.","grade":"حسن","chapter_ar":"باب في حضور الجماعة على من سمع النداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (552); Ibn Majah (792)","chapter_en":"Attending the congregation for the one who hears the call","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Ibn Umm Maktum asked the Prophet ﷺ and said: “O Messenger of Allah, I am blind, my home is far, and I have a guide who does not suit me. Do I have a concession to pray in my home?” He said: “Do you hear the call?” He said: “Yes.” He said: “I do not find a concession for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (552)، ابن ماجه (792)."},{"num":2357,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مُرُوا أَوْلَادَكُمْ بِالصَّلَاةِ وَهُمْ أَبْنَاءُ سَبْعِ سِنِينَ، ، وَاضْرِبُوهُمْ عَلَيْهَا وَهُمْ أَبْنَاءُ عَشْرٍ سِنِينَ، ، وَفَرِّقُوا بَيْنَهُمْ فِي الْمَضَاجِعِ."],"takhrij":"حسن: رواه أبو داود (495) عن مؤمل بن هشام -يعني اليشكري- حدثنا إسماعيل، عن سوار أبي حمزة، قال أبو داود: وهو سوار بن داود أبو حمزة المزني الصيرفي، عن عمرو بن شُعيب، عن أبيه، عن جده فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في أمر الصبي بالصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (495)","chapter_en":"Commanding a child to pray","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr said: The Messenger of Allah ﷺ said: “Command your children to pray when they are seven years old, strike them for it when they are ten years old, and separate them in their beds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (495)."},{"num":2358,"demo":false,"sanad":"","matn":["عَنْ سَبْرَةَ الجهني قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مُرُوا الصبيَّ بِالصَّلاَةِ إِذَا بَلَغَ سَبْعَ سِنِينَ، وَإِذَا بَلَغَ عَشْرَ سِنِينَ فَاضْرِبُوهُ عَلَيْهَا ."],"takhrij":"حسن: رواه أبو داود (494)، والترمذي (407) كلاهما من طريق عبد الملك بن الربيع بن سَبْرَةَ، عن أبيه، عن جده فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في أمر الصبي بالصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (494); al-Tirmidhi (407) (Tirmidhi said: Hasan Sahih)","chapter_en":"Commanding a child to pray","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Sabrah al-Juhani said: The Messenger of Allah ﷺ said: “Command a child to pray when he reaches seven years, and when he reaches ten years, strike him for it.”"]},"buhuth":{"en":["This instruction is for training and habituation, not because prayer is legally obligatory upon a child; leaving it at that stage is not a sin upon him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (494)، والترمذي (407)، وقال الترمذي: حسن صحيح."},{"num":2359,"demo":false,"sanad":"","matn":["عن جابر بْنِ يَزِيدَ بْنِ الأسود الخزاعي، الْعَامِرِيُّ، عَنْ أَبِيهِ، قَالَ: شَهِدْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَجَّتَهُ، فَصَلَّيْتُ مَعَهُ صَلاَةَ الصُّبْحِ فِي مَسْجِدِ الْخَيْفِ. قَالَ: فَلَمَّا قَضَى صَلاَتَهُ وَانْحَرَفَ إِذَا هُوَ بِرَجُلَيْنِ فِي أُخْرَى الْقَوْمِ لَمْ يُصَلِّيَا مَعَهُ، فَقَالَ: عَلَىَّ بِهِمَا. فَجِيءَ بِهِمَا تُرْعَدُ فَرَائِصُهُمَا فَقَالَ: مَا مَنَعَكُمَا أَنْ تُصَلِّيَا مَعَنَا. فَقَالاَ: يَا رَسُولَ اللَّهِ إِنَّا كُنَّا قَدْ صَلَّيْنَا فِي رِحَالِنَا. قَالَ: فَلاَ تَفْعَلاَ، إِذَا صَلَّيْتُمَا فِي رِحَالِكُمَا، ثُمَّ أَتَيْتُمَا مَسْجِدَ جَمَاعَةٍ، فَصَلِّيَا مَعَهُمْ؛ فَإِنَّهَا لَكُمَا نَافِلَةٌ."],"takhrij":"صحيح: رواه أبو داود (575)، والترمذي (219)، والنسائي (858) كلهم من طرق عن يعلى بن عطاء، عن جابر بن يزيد به مثله.","grade":"صحيح","chapter_ar":"باب من صلّى وحده ثم أدرك جماعةً يصلّيها معهم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (575); al-Tirmidhi (219) (Hasan Sahih); al-Nasa’i (858)","chapter_en":"One who prayed alone then catches a congregation: he prays with them","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn Yazid ibn al-Aswad al-Khuza‘i narrated from his father: I attended the pilgrimage of the Prophet ﷺ and prayed Fajr with him at Masjid al-Khayf. When he finished and turned away, he saw two men at the far end of the people who had not prayed with him. He said: “Bring them to me.” They were brought, trembling. He said: “What prevented you from praying with us?” They said: “O Messenger of Allah, we already prayed in our places.” He said: “Do not do that. If you pray in your places, then you come to a mosque where there is a congregation, then pray with them; it will be a voluntary prayer for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (575)، والترمذي (219) وقال: حسن صحيح، والنسائي (858)."},{"num":2360,"demo":false,"sanad":"","matn":["عن بُسْر بْنِ مِحْحَنٍ، مِحْجَنٍ عَنْ أَبِيهِ، مِحْجَنٍ أَنَّهُ كَانَ فِي مَجْلِسٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُذِّنَ بِالصَّلاَةِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى. ثُمَّ رَجَعَ، وَمِحْجَنٌ فِي مَجْلِسِهِ لَمْ يُصَلِّ مَعَهُ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مَنَعَكَ أَنْ تُصَلِّيَ مَعَ النَّاسِ؟ أَلَسْتَ بِرَجُلٍ مُسْلِمٍ. فَقَالَ: بَلَى يَا رَسُولَ اللَّهِ، وَلَكِنِّي قَدْ صَلَّيْتُ فِي أَهْلِي. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا جِئْتَ فَصَلِّ مَعَ النَّاسِ، وَإِنْ كُنْتَ قَدْ صَلَّيْتَ."],"takhrij":"صحيح: رواه مالك في صلاة الجماعة (8) عن زيد بن أسلم، عن رجل من بني الدِيل يقال له: بُسْر بن محجَن فذكره. ورواه النسائي (857) عن قتيبة، عن مالك به.","grade":"صحيح","chapter_ar":"باب من صلّى وحده ثم أدرك جماعةً يصلّيها معهم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMalik (8); al-Nasa’i (857); al-Hakim (890) (authenticated)","chapter_en":"One who prayed alone then catches a congregation: he prays with them","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Busr ibn Mahjan narrated from his father that he was sitting with the Messenger of Allah ﷺ when the call to prayer was made. The Messenger of Allah ﷺ stood and prayed, then returned, while Mahjan remained seated and had not prayed with the people. The Messenger of Allah ﷺ said: “What prevented you from praying with the people? Are you not a Muslim man?” He said: “Yes, O Messenger of Allah, but I already prayed with my family.” The Messenger of Allah ﷺ said: “When you come, pray with the people—even if you have already prayed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (8)، والنسائي (857)، والحاكم (890) وصححه."},{"num":2361,"demo":false,"sanad":"","matn":["عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، - يَعْنِي مَوْلَى مَيْمُونَةَ - قَالَ: أَتَيْتُ ابْنَ عُمَرَ عَلَى الْبَلاَطِ وَهُمْ يُصَلُّونَ، فَقُلْتُ: أَلاَ تُصَلِّي مَعَهُمْ؟ قَالَ: قَدْ صَلَّيْتُ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ تُصَلُّوا صَلاَةً فِي يَوْمٍ مَرَّتَيْنِ."],"takhrij":"حسن: رواه أبو داود (579)، والنسائي (860) كلاهما من طريق حسين المعلم، عن عمرو بن شُعيب، عن سليمان بن يسار فذكر مثله.","grade":"حسن","chapter_ar":"باب من قال: لا يُصلَّى مكتوبة في يوم مرتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (579); al-Nasa’i (860); Ibn Khuzaymah (1641); Ahmad (4689)","chapter_en":"Those who said: a prescribed (obligatory) prayer is not prayed twice in one day","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Sulayman ibn Yasar (the freedman of Maymunah) said: I came to Ibn ‘Umar at al-Bilat while they were praying. I said: “Will you not pray with them?” He said: “I have already prayed. I heard the Messenger of Allah ﷺ say: ‘Do not pray a prayer twice in one day.’”"]},"buhuth":{"en":["Ibn ‘Abd al-Barr explained (and Ahmad and Ishaq agreed) that this prohibition means repeating an obligatory prayer again as an obligation. However, if someone prays again with the congregation intending it as voluntary—following the instruction of the Prophet ﷺ “it will be voluntary for you”—then this is not considered praying the obligatory prayer twice, because the first is obligatory and the second is voluntary."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (579)، والنسائي (860)، وابن خزيمة (1641)، وأحمد (4689)."},{"num":2362,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  مَنْ تَوَضَّأَ لِلصَّلَاةِ فَأَسْبَغَ الْوُضُوءَ، ثُمَّ مَشَى إِلَى الصَّلَاةِ الْمَكْتُوبَةِ، فَصَلَّاهَا مَعَ النَّاسِ، أَوْ مَعَ الْجَمَاعَةِ، أَوْ فِي الْمَسْجِدِ غَفَرَ اللَّهُ لَهُ ذُنُوبَهُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (232: 13) من طرق عن عبدالله بن وهب، عن عمرو بن الحارث، أنّ الحكم بن عبدالله القرشي حدّثه، أنّ نافع ابن جبير وعبدالله بن أبي سلمة حدّثاه أنّ معاذ بن عبدالرحمن حدثهما عن حمران مولى عثمان بن عفان، عن عثمان، فذكره. وانفرد مسلم بهذا اللفظ، وقد مضى حديث عثمان في الطهارة.","grade":"صحيح","chapter_ar":"باب ما جاء في إقامة الجماعة مرتين في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (232/13)","chapter_en":"Establishing a congregation twice in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["‘Uthman ibn ‘Affan said: I heard the Messenger of Allah ﷺ say: “Whoever performs wudu for prayer and perfects it, then walks to the obligatory prayer and prays it with the people, or with the congregation, or in the mosque—Allah will forgive his sins.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (232: 13)."},{"num":2363,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: جَاءَ رَجُلٌ وَقَدْ صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَيُّكُمْ يَتَّجِرُ عَلَى هَذَا. فَقَامَ رَجُلٌ فَصَلَّى مَعَهُ.","وفي رواية: أَلَا مَنْ يَتَصَدَّقُ عَلَى هَذَا فَيُصَلِّيَ مَعَهُ ..","وفي رواية: فتصدق عليه أبو بكر فصلى معه."],"takhrij":"حسن: رواه أبو داود (574)، والترمذي (220) واللفظ له، كلاهما من طريق سليمان الأسود الناجي البصري، عن أبي المتوكل، عن أبي سعيد فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في إقامة الجماعة مرتين في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (574); al-Tirmidhi (220) (Tirmidhi said: Hasan)","chapter_en":"Establishing a congregation twice in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: A man came after the Messenger of Allah ﷺ had already prayed, so he said: “Who will earn reward with this man?” Then a man stood and prayed with him. In another narration: “Who will give charity to this man by praying with him?” And in another: “Abu Bakr gave charity to him and prayed with him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (574)، والترمذي (220)، وقال الترمذي: حسن."},{"num":2364,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: أَنَّ رَجُلًا جَاءَ، وَقَدْ صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ يُصَلِّي وَحْدَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ يَتَّجِرُ عَلَى هَذَا فَلْيُصَلِّي مَعَهُ؟"],"takhrij":"حسن: رواه الدارقطني (1081) عن يحيى بن محمد بن صاعد، ثنا عمر بن محمد بن الحسن الأسدي، ثنا أبي، نا حماد بن سلمة، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إقامة الجماعة مرتين في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Daraqutni (1/276)","chapter_en":"Establishing a congregation twice in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Malik reported that a man came after the Messenger of Allah ﷺ had prayed, and the man began praying alone. The Messenger of Allah ﷺ said: “Who will earn reward with this man by praying with him?”"]},"buhuth":{"en":["A number of Companions (including Ibn Mas‘ud) and many from the Successors and others held this view. It is also Imam Ahmad’s position: repeating a congregation in a mosque is not disliked if the regular imam has already led, and then another group arrives. As for mosques in markets and along travel routes, there is no dispute that congregations may be repeated there."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارقطني (1081)."},{"num":2365,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ صَلاَةٌ أَثْقَلَ عَلَى الْمُنَافِقِينَ مِنَ الْفَجْرِ وَالْعِشَاءِ، وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لأَتَوْهُمَا وَلَوْ حَبْوًا، لَقَدْ هَمَمْتُ أَنْ آمُرَ الْمُؤَذِّنَ فَيُقِيمَ، ثُمَّ آمُرَ رَجُلاً يَؤُمُّ النَّاسَ، ثُمَّ آخُذَ شُعَلاً مِنْ نَارٍ فَأُحَرِّقَ عَلَى مَنْ لاَ يَخْرُجُ إِلَى الصَّلاَةِ بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (657)، ومسلم في المساجد (651/252) كلاهما من طريق الأعمش، قال: حدثني أبو صالح، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب فضل صلاتي العشاء والفجر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (657) (wording his); Muslim (651/252). Muslim’s wording includes: “then I would go with men carrying bundles of firewood to people who do not attend the prayer and burn their houses.”","chapter_en":"The virtue of ‘Isha and Fajr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “There is no prayer heavier upon the hypocrites than Fajr and ‘Isha. If they knew what is in them, they would come to them even crawling. I considered ordering the caller to establish the prayer, then ordering a man to lead the people, then taking flaming torches and burning (the houses) of those who do not come out to the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (657) واللفظ له، ومسلم (651/252). وفي لفظ مسلم: «ثم أنطلق معي برجال معهم حزم من حطب إلى قوم لا يشهدون الصلاة فأحرق عليهم بيوتهم»."},{"num":2366,"demo":false,"sanad":"","matn":["عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ قَالَ:  دَخَلَ عُثْمَانُ بْنُ عَفَّانَ الْمَسْجِدَ بَعْدَ صَلَاةِ الْمَغْرِبِ، فَقَعَدَ وَحْدَهُ، فَقَعَدْتُ إِلَيْهِ، فَقَالَ: يَا ابْنَ أَخِي، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ صَلَّى الْعِشَاءَ فِي جَمَاعَةٍ فَكَأَنَّمَا قَامَ نِصْفَ اللَّيْلِ، وَمَنْ صَلَّى الصُّبْحَ فِي جَمَاعَةٍ فَكَأَنَّمَا صَلَّى اللَّيْلَ كُلَّهُ."],"takhrij":"صحيح: رواه مسلم في المساجد (656) عن إسحاق بن إبراهيم، أخبرنا المغيرة بن سلمة المخزومي، حدثنا عبدالواحد (وهو ابن زياد) حدثنا عثمان بن حكيم، حدثنا عبدالرحمن بن أبي عمرة فذكره،","grade":"صحيح","chapter_ar":"باب فضل صلاتي العشاء والفجر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (656)","chapter_en":"The virtue of ‘Isha and Fajr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["‘Abd al-Rahman ibn Abi ‘Amrah said: ‘Uthman ibn ‘Affan entered the mosque after Maghrib and sat alone, so I sat with him. He said: “O my nephew, I heard the Messenger of Allah ﷺ say: ‘Whoever prays ‘Isha in congregation, it is as if he stood (in prayer) for half the night; and whoever prays Fajr in congregation, it is as if he prayed the entire night.’”"]},"buhuth":{"en":["In the narration of Abu Dawud (555) and al-Tirmidhi (221): “Whoever attends ‘Isha in congregation has the reward of standing half a night; and whoever prays ‘Isha and Fajr in congregation has the reward like standing a whole night.” Al-Tirmidhi graded it hasan sahih."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (656)."},{"num":2367,"demo":false,"sanad":"","matn":["عن جندب بْنِ عبدالله يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ، فَلَا يَطْلُبَنَّكُمُ اللهُ مِنْ ذِمَّتِهِ بِشَيْءٍ فَيُدْرِكَهُ، فَيَكُبَّهُ فِي نَارِ جَهَنَّمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (657) عن نصر بن علي الجهضمي، حدثنا بشر (يعني ابن مفضَّل) عن خالد، عن أنس بن سيرين، سمعتُ جندبَ بن عبدالله يقول فذكره.","grade":"صحيح","chapter_ar":"باب فضل صلاتي العشاء والفجر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (657)","chapter_en":"The virtue of ‘Isha and Fajr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Jundub ibn ‘Abdullah reported that the Messenger of Allah ﷺ said: “Whoever prays Fajr is under the protection of Allah, so let none of you cause Allah to call him to account regarding His protection in any way, lest He seize him and cast him into the Fire of Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (657)."},{"num":2368,"demo":false,"sanad":"","matn":["عَنْ سَمُرَّةَ بْنِ جُنْدُبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ صَلَّى صَلَاةَ الْغَدَاةِ، فَهُوَ فِي ذِمَّةِ اللَّهِ، فَلَا تُخْفِرُوا اللهَ فِي ذِمَّتِهِ."],"takhrij":"صحيح: رواه ابن ماجه (3946)، وأحمد (20113) –واللفظ له، كلاهما من حديث روح بن عبادة، حدثنا أشعث (هو ابن عبدالملك الحمراني، عن الحسن، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب فضل صلاتي العشاء والفجر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (3946); Ahmad (20113) (wording his)","chapter_en":"The virtue of ‘Isha and Fajr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet ﷺ said: “Whoever prays the morning prayer is under Allah’s protection—so do not violate Allah regarding His protection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3946)، أحمد (20113) (واللفظ له)."},{"num":2369,"demo":false,"sanad":"","matn":["عن أَبِي مَالِكٍ الأشجعي، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ صَلَّى الصُّبْحَ فَهُوَ فِي ذِمَّةِ اللَّهِ، وَحِسَابُهُ عَلَى اللَّهِ."],"takhrij":"حسن: رواه الطبراني في الكبير (8188) عن علي بن سعيد الرازي، حدثنا الهيثم بن اليمان الرازي، حدثنا إسماعيل بن زكريا، عن أبي مالك الأشجعي، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب فضل صلاتي العشاء والفجر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Kabir (8/381)","chapter_en":"The virtue of ‘Isha and Fajr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Abu Malik al-Ashja‘i narrated from his father that the Messenger of Allah ﷺ said: “Whoever prays Fajr is under Allah’s protection, and his reckoning is upon Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (8188)."},{"num":2370,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ يَتَعَاقَبُونَ فِيكُمْ مَلاَئِكَةٌ بِاللَّيْلِ وَمَلاَئِكَةٌ بِالنَّهَارِ، وَيَجْتَمِعُونَ فِي صَلاَةِ الْفَجْرِ. وَصَلاَةِ الْعَصْرِ، ثُمَّ يَعْرُجُ الَّذِينَ بَاتُوا فِيكُمْ، فَيَسْأَلُهُمْ وَهْوَ أَعْلَمُ بِهِمْ: كَيْفَ تَرَكْتُمْ عِبَادِي؟ فَيَقُولُونَ: تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ، وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (82) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب فضل صلاتي الصبح والعصر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (82); al-Bukhari (555); Muslim (632)","chapter_en":"The virtue of Fajr and ‘Asr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Angels take turns among you—angels by night and angels by day. They gather at the ‘Asr prayer and the Fajr prayer. Then those who spent the night among you ascend, and Allah asks them—though He knows best—‘How did you leave My servants?’ They say: ‘We left them while they were praying, and we came to them while they were praying.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12670],"tks":"متفق عليه: رواه مالك (82)، البخاري (555)، مسلم (632)."},{"num":2371,"demo":false,"sanad":"","matn":["عن جرير بْنِ عبدالله وَهُوَ يَقُولُ:  كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ نَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ، فَقَالَ: أَمَا إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ. لَا تُضَامُّونَ فِي رُؤْيَتِهِ. فَإِنِ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا - يَعْنِي الْعَصْرَ وَالْفَجْرَ. -، ثُمَّ قَرَأَ جَرِيرٌ: ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا."],"takhrij":"متفق عليه: رواه البخاري في مواقيت الصلاة (554)، ومسلم في المساجد (633) كلاهما من حديث مروان بن معاوية الفزاري، أخبرنا إسماعيل بن أبي خالد، حدثنا قيس بن أبي حازم، قال: سمعت جرير بن عبدالله فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب فضل صلاتي الصبح والعصر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (554); Muslim (633)","chapter_en":"The virtue of Fajr and ‘Asr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Jarir ibn ‘Abdullah said: We were sitting with the Messenger of Allah ﷺ when he looked at the moon on the night of the full moon and said: “You will surely see your Lord just as you see this moon; you will not be crowded or harmed in seeing Him. So if you are able not to be overcome (and miss) a prayer before sunrise and a prayer before sunset—meaning Fajr and ‘Asr—then do so.” Then Jarir recited: “And glorify the praise of your Lord before the rising of the sun and before its setting.” (20:130)"]},"buhuth":{"en":["“You will not be crowded” means people will not have to press in on one another or ask to be shown; each will see clearly. “If you are able…” is a condition whose implied conclusion is: then do it. “You will see Him as you see this moon” is a comparison of certainty and clarity of seeing—not a comparison of what is seen. This vision is for believers, not for disbelievers and hypocrites, according to the majority of Sunni scholarship."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12739],"tks":"متفق عليه: رواه البخاري (554)، مسلم (633)."},{"num":2372,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ صلَّى البَرْدَين دَخَلَ الْجَنَّةَ ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (574)، ومسلم في المساجد (635) كلاهما عن هُدْبة بن خالد، حدثنا همام بن يحيى، حدثني أبو جمرة الضُبَعِيُّ، عن أبي بكر بن أبي موسى، عن أبيه فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب فضل صلاتي الصبح والعصر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (574); Muslim (635)","chapter_en":"The virtue of Fajr and ‘Asr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said: “Whoever prays the two cool prayers enters Paradise.”"]},"buhuth":{"en":["“The two cool prayers” refers to Fajr and ‘Asr. They are called that because they occur at the cooler ends of the day, when the air is pleasant and the heat eases."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (574)، مسلم (635)."},{"num":2373,"demo":false,"sanad":"","matn":["عن عُمَارَةَ بْنِ رُؤَيبة، عَنْ أَبِيهِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  لَنْ يَلِجَ النَّارَ أَحَدٌ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ، وَقَبْلَ غُرُوبِهَا - يَعْنِي الْفَجْرَ وَالْعَصْرَ. -. فَقَالَ لَهُ رَجُلٌ مِنْ أَهْلِ الْبَصْرَةِ: آنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ. قَالَ الرَّجُلُ: وَأَنَا أَشْهَدُ أَنِّي سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي."],"takhrij":"صحيح: رواه مسلم في المساجد (634) من أوجه عن أبي بكر بن عُمارة ابن رُؤَيْبَة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب فضل صلاتي الصبح والعصر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (634)","chapter_en":"The virtue of Fajr and ‘Asr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["‘Umarah ibn Ru’aybah said: I heard the Messenger of Allah ﷺ say: “No one who prays before sunrise and before sunset will enter the Fire”—meaning Fajr and ‘Asr. A man from Basrah said to him: “Did you hear this from the Messenger of Allah ﷺ?” He said: “Yes.” The man said: “And I testify that I heard it from the Messenger of Allah ﷺ—my ears heard it and my heart retained it.”"]}},"tuhfa":{},"full":1,"rep":[12740],"tks":"صحيح: رواه مسلم (634)."},{"num":2374,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ فَضَالَةَ، عَنْ أَبِيهِ، قَالَ: عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ فِيمَا عَلَّمَنِي: وَحَافِظْ عَلَى الصَّلَوَاتِ الْخَمْسِ. قَالَ: قُلْتُ: إِنَّ هَذِهِ سَاعَاتٌ لِي فِيهَا أَشْغَالٌ، فَمُرْنِي بِأَمْرٍ جَامِعٍ إِذَا أَنَا فَعَلْتُهُ أَجْزَأَ عَنِّي؟ فَقَالَ: حَافِظْ عَلَى الْعَصْرَيْنِ. وَمَا كَانَتْ مِنْ لُغَتِنَا؟ فَقُلْتُ: وَمَا الْعَصْرَانِ؟ فَقَالَ: صَلاَةٌ قَبْلَ طُلُوعِ الشَّمْسِ، وَصَلاَةٌ قَبْلَ غُرُوبِهَا."],"takhrij":"صحيح: رواه أبو داود (428) عن عمرو بن عون، أنا خالد، عن دواد ابن أبي هند، عن أبي حرب بن أبي الأسود، عن عبدالله بن فَضالة فذكره.","grade":"صحيح","chapter_ar":"باب فضل صلاتي الصبح والعصر في الجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (428); Ibn Hibban (1742) (authenticated); al-Hakim (717)","chapter_en":"The virtue of Fajr and ‘Asr in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn Fadalah narrated from his father: The Messenger of Allah ﷺ taught me, and among what he taught me was: “Guard the five prayers.” I said: “These are times in which I have responsibilities; command me with something comprehensive—if I do it, it will suffice me.” He said: “Guard the two ‘asrs.” (It was not our usual expression), so I said: “What are the two ‘asrs?” He said: “A prayer before sunrise and a prayer before sunset.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (428)، ابن حبان (1742) (صححه)، الحاكم (717)."},{"num":2375,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ أَذَّنَ بِالصَّلاَةِ فِي لَيْلَةٍ ذَاتِ بَرْدٍ وَرِيحٍ ثُمَّ قَالَ أَلاَ صَلُّوا فِي الرِّحَالِ. ثُمَّ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْمُرُ الْمُؤَذِّنَ إِذَا كَانَتْ لَيْلَةٌ ذَاتُ بَرْدٍ وَمَطَرٍ يَقُولُ: أَلاَ صَلُّوا فِي الرِّحَالِ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (10) عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (10); al-Bukhari (666); Muslim (697)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar gave the call to prayer on a night of cold and wind and said: “Pray in your dwellings.” Then he said: The Messenger of Allah ﷺ used to instruct the caller to prayer—when it was a cold, rainy night—to say: “Pray in your dwellings.”"]},"buhuth":{"en":["They also narrate: Nafi‘ said that Ibn ‘Umar called the adhan on a cold night at a place called Dajnan, then said: “Pray in your dwellings.” He reported that the Prophet ﷺ would have the mu’adhdhin call the adhan, then immediately add: “Pray in your dwellings,” on cold or rainy nights while traveling.","“Dajnan” is the name of a mountain (it is said: near Makkah; and it is also said: between Makkah and Madinah)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (10)، البخاري (666)، مسلم (697)."},{"num":2376,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن الْحَارِثِ قَالَ: خَطَبَنَا ابْنُ عَبَّاسٍ فِي يومٍ رَدْغٍ فَلَمَّا بَلَغَ الْمُؤَذِّنُ: حيّ عَلَى الصَّلاَةِ فَأَمَرَهُ أَنْ ينادى: الصَّلاَةُ فِي الرِّحَالِ، فَنَظَرَ الْقَوْمُ بَعْضُهُمْ إِلَى بَعْضٍ فَقَالَ: فَعَلَ هَذَا مَنْ هُوَ خَيْرٌ مِنْهُ، وَإِنَّهَا عَزْمةٌ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (616) ومسلم في صلاة المسافرين (699) كلاهما عن عبدالحميد صاحب الزيادي، عن عبدالله بن الحارث فذكره، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (616) — wording his; Muslim (699)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["‘Abdullah ibn al-Harith said: Ibn ‘Abbas delivered a sermon to us on a day of heavy wetness/mud. When the caller reached “Come to prayer,” Ibn ‘Abbas told him to announce: “Prayer is in your dwellings.” People looked at one another, so he said: “This was done by someone better than me (meaning the Prophet ﷺ), and it is a firm instruction.”"]},"buhuth":{"en":["Other Bukhari wordings mention that they seemed to disapprove, so he clarified: “Someone better than me did this,” and he said he disliked putting them in hardship so they would have to walk through mud and slippery ground.","“A day of radgh” is explained as wet muddy conditions (or little water that makes the ground messy). “‘Azmah” means a firm command (opposite of a concession). “Dahd” means slippery ground."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (616) - واللفظ له، مسلم (699)."},{"num":2377,"demo":false,"sanad":"","matn":["عَنْ مَحْمُودِ بْنِ الرَّبِيعِ الأَنْصَارِيِّ أنَّ عِتْبَانَ بْنَ مَالِكٍ وَهُوَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّنْ شَهِدَ بَدْرًا مِنَ الأَنْصَارِ أَنَّهُ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ قَدْ أَنْكَرْتُ بَصَرِي وَأَنَا أصلِّي لِقَوْمِي، فَإِذَا كَانَتِ الأَمْطَارُ سالَ الْوَادِي الَّذِي بَيْنِي وَبَيْنَهُمْ لَمْ أستَطِع أَنْ آتىَ مَسْجِدَهُمْ فأُصلِّي بِهِمْ. وودِدْتُ يَا رَسُولَ اللَّهِ أنَّكَ تَأْتِينِي فتُصَلِّي فِي بَيْتِي فأَتخذَهُ مُصلًّى. قَالَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَأَفْعَلُ إِنْ شاءَ اللَّهُ . قَالَ عِتبانُ: فَغَدَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ حينَ ارتَفَعَ النَّهَارُ فَاسْتَأْذَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فأَذِنتُ لَهُ، فَلَمْ يَجْلِسْ حَتَّى دخلَ الْبَيْتَ ثُمَّ قَالَ: أينَ تُحِبُّ أَنْ أصلِّيَ مِنْ بَيتِكَ؟ قَالَ: فَأَشَرْتُ لَهُ إِلَى نَاحِيَةٍ مِنَ الْبَيْتِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فكبَّرَ، فَقُمْنَا فصفَفْنا فصلَّى رَكعتَينِ ثُمَّ سلَّمَ. فَذَكَرَ الْحَدِيثَ. وهو فِي كِتَابِ الإيمان بِطُولِهِ. قَالَ ابنُ شِهابٍ: ثمَّ سَأَلتُ الْحُصينَ بنَ مُحَمَّدٍ الأنصاري -وهو أحدُ بَنِي سَالِمٍ وهو من سَرَاتِهِمْ- عن حَدِيثِ محمود بْنِ الرَّبِيعِ، فصدَّقه بِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (425)، ومسلم في المساجد (263) كلاهما من طريق ابن شهاب، قال: أخبرني محمود بن الربيع فذكر مثله واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (425) — wording his; Muslim (33)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Mahmud ibn al-Rabi‘ al-Ansari reported that ‘Itban ibn Malik—one of the Companions of the Messenger of Allah ﷺ, among the Ansar who witnessed Badr—came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my eyesight has weakened, and I lead my people in prayer. When it rains, the valley between me and them flows, and I cannot reach their mosque to lead them in prayer. I would love, O Messenger of Allah, if you would come and pray in my house so that I may take it as a prayer-place.” The Messenger of Allah ﷺ said to him: “I will do so, if Allah wills.” ‘Itban said: The Messenger of Allah ﷺ and Abu Bakr came the next morning after the day had risen. The Messenger of Allah ﷺ asked permission to enter, and I gave him permission. He did not sit until he entered the house, then he said: “Where in your house would you like me to pray?” I pointed to a side of the house. The Messenger of Allah ﷺ stood and said “Allahu akbar,” and we stood and formed a row behind him. He prayed two rak‘ahs, then gave salam. The narration continues, and its full form is in the Book of Faith. Ibn Shihab said: Then I asked al-Husayn ibn Muhammad al-Ansari—one of Banu Salim and one of their prominent men—about the report of Mahmud ibn al-Rabi‘, and he confirmed it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (425) - واللفظ له، مسلم (263)."},{"num":2378,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَمُطِرْنَا فَقَالَ: لِيُصَلِّ مَنْ شَاءَ مِنْكُمْ فِي رَحْلِهِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (698) من طريق زهير أبي خيثمة، قال: حدثنا أبو الزبير، عن جابر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (698)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Jabir said: We went out with the Messenger of Allah ﷺ on a journey and we were rained upon, so he said: “Let whoever wishes among you pray in his lodging.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (698)."},{"num":2379,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أَوْسٍ، يَقُولُ: أَنْبَأَنَا رَجُلٌ، مِنْ ثَقِيفٍ أَنَّهُ سَمِعَ مُنَادِيَ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْنِي فِي لَيْلَةٍ مَطِيرَةٍ فِي السَّفَرِ يَقُولُ: حَىَّ عَلَى الصَّلاَةِ، حَىَّ عَلَى الْفَلاَحِ، صَلُّوا فِي رِحَالِكُمْ."],"takhrij":"صحيح: رواه النسائي (653) عن قتيبة قال: حدثنا سفيان، عن عمرو ابن دينار، عن عمرو بن أوس فذكر مثله.","grade":"صحيح","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (653); Ahmad (15433)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["‘Amr ibn Aws said: A man from Thaqif informed us that he heard the caller of the Prophet ﷺ—on a rainy night while traveling—saying: “Come to prayer, come to success—pray in your dwellings.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (653)، وأحمد (15433)."},{"num":2380,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمَلِيحِ، قَالَ: خَرَجْتُ فِي لَيْلَةٍ مَطِيرَةٍ، فَلَمَّا رَجَعْتُ اسْتَفْتَحْتُ فَقَالَ أَبِي: مَنْ هَذَا؟ قَالَ: أَبُو الْمَلِيحِ. قَالَ: لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْحُدَيْبِيَةِ، وَأَصَابَتْنَا سَمَاءٌ لَمْ تَبُلَّ أَسَافِلَ نِعَالِنَا، فَنَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلُّوا فِي رِحَالِكُمْ."],"takhrij":"صحيح: رواه ابن ماجة (936) قال: حدثنا أبو بكر بن أبي شيبة، قال: حدثنا إسماعيل بن إبراهيم، عن خالد الحذاء، عن أبي قِلابة، عن أبي المَليح فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (936); Ibn Abi Shaybah (2/234); Abu Dawud (1059)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Abu al-Malih said: I went out on a rainy night, and when I returned and asked to be let in, my father said: “Who is that?” I said: “Abu al-Malih.” He said: “I saw us with the Messenger of Allah ﷺ on the day of al-Hudaybiyah; we were touched by rain that did not even soak the bottoms of our sandals, and the caller of the Messenger of Allah ﷺ announced: ‘Pray in your dwellings.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (936)، ابن أبي شيبة (6265)، أبو داود (1059)."},{"num":2381,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، قَالَ: أَصَابَتْنَا السَّمَاءُ، وَنَحْنُ مَعَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَادَى: الصَّلَاةُ فِي الرِّحَالِ."],"takhrij":"حسن: رواه الإمام أحمد (20170) عن معاذ بن هشام، قال: حدثني أبي، عن قتادة، عن الحسن، عن سمرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب الرخصة في ترك الجماعة عند المطر والعذر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (20170); al-Bazzar (Kashf al-Astar, 464); al-Tabarani in al-Kabir (6822)","chapter_en":"Concession to miss the congregation due to rain and valid excuses","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Samurah ibn Jundub said: Rain fell upon us while we were with the Prophet ﷺ, so he called out: “Prayer is in your dwellings.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20170)، والبزار في كشف الأستار (464)، والطبراني في المعجم الكبير (6822)."},{"num":2382,"demo":false,"sanad":"","matn":["عن مَحْمُودِ بْنِ الرَّبِيعِ الأَنْصَارِيِّ أَنَّ عِتْبَانَ بْنَ مَالِكٍ، ـ وَهُوَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّنْ شَهِدَ بَدْرًا مِنَ الأَنْصَارِ ـ أَنَّهُ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، قَدْ أَنْكَرْتُ بَصَرِي، وَأَنَا أُصَلِّي لِقَوْمِي، فَإِذَا كَانَتِ الأَمْطَارُ سَالَ الْوَادِي الَّذِي بَيْنِي وَبَيْنَهُمْ، لَمْ أَسْتَطِعْ أَنْ آتِيَ مَسْجِدَهُمْ فَأُصَلِّيَ بِهِمْ، وَوَدِدْتُ يَا رَسُولَ اللَّهِ أَنَّكَ تَأْتِينِي فَتُصَلِّيَ فِي بَيْتِي، فَأَتَّخِذَهُ مُصَلًّى. قَالَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَأَفْعَلُ إِنْ شَاءَ اللَّهُ.","قَالَ عِتْبَانُ: فَغَدَا رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ حِينَ ارْتَفَعَ النَّهَارُ فَاسْتَأْذَنَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَأَذِنْتُ لَهُ، فَلَمْ يَجْلِسْ حَتَّى دَخَلَ الْبَيْتَ ثُمَّ قَالَ: أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ؟ قَالَ: فَأَشَرْتُ لَهُ إِلَى نَاحِيَةٍ مِنَ الْبَيْتِ، فَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَكَبَّرَ، فَقُمْنَا فَصَفَفْنَا فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ، فذكر الحديث كما مضى فِي الباب السابق."],"takhrij":"متفق عليه: رواه البخاريّ في الصّلاة (425)، ومسلم في المساجد (263) كلاهما من طريق ابن شهاب، قال: أخبرني محمود بن الربيع فذكر مثله، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صلاة الجماعة في البيوت للضرورة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (425) — wording his; Muslim (33)","chapter_en":"Congregational prayer in homes due to necessity","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Mahmud ibn al-Rabi‘ al-Ansari reported that ‘Itban ibn Malik—one of the Companions of the Messenger of Allah ﷺ from the Ansar who witnessed Badr—came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my eyesight has weakened, and I lead my people in prayer. When it rains, the valley between me and them floods, and I cannot reach their mosque to lead them. I would love, O Messenger of Allah, if you would come and pray in my house so that I may take it as a prayer-place.” The Messenger of Allah ﷺ said: “I will do so, if Allah wills.” ‘Itban said: The Messenger of Allah ﷺ and Abu Bakr came in the forenoon. The Messenger of Allah ﷺ asked permission to enter, and I gave him permission. He did not sit until he entered the house, then he said: “Where would you like me to pray in your house?” I indicated a side of the house. The Messenger of Allah ﷺ stood and said “Allāhu akbar”; we stood and formed rows, and he prayed two units, then gave salam. The narration continues as previously mentioned in the preceding chapter."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (425) - واللفظ له، مسلم (263)."},{"num":2383,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً، مِنَ الأَنْصَارِ أَرْسَلَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَعَالَ فَخُطَّ لِي مَسْجِدًا فِي دَارِي أُصَلِّي فِيهِ. وَذَلِكَ بَعْدَ مَا عَمِيَ، فَجَاءَ فَفَعَلَ."],"takhrij":"حسن: رواه ابن ماجه (755) عن يحيى بن الفَضْل الخرقي، قال: حدثنا أبو عامر، قال: حدثنا حماد بن سلمة، عن عاصم، عن أبي صالح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صلاة الجماعة في البيوت للضرورة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (755); Ibn Hibban (4798)","chapter_en":"Congregational prayer in homes due to necessity","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported: A man from the Ansar sent to the Messenger of Allah ﷺ: “Come and mark out a place of prayer for me in my home so that I may pray in it.” This was after he had become blind, so the Prophet ﷺ came and did so."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (755)، ابن حبان (4798)."},{"num":2384,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قُدِّمَ الْعَشَاءُ، فَابْدَءُوا بِهِ قَبْلَ أَنْ تُصَلُّوا صَلاَةَ الْمَغْرِبِ، وَلاَ تَعْجَلُوا عَنْ عَشَائِكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان من طريق عُقيل (672)، ومسلم في المساجد من طريق عمرو بن الحارث (557) كلاهما من حديث ابن شهاب الزهري، قال: حدثني أنس بن مالك فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب تناول العَشاء إذا قُدِّمَ وإن أقيمت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (672); Muslim (557)","chapter_en":"Eating dinner if it is served, even if the prayer is established","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ said: “If dinner is served, then begin with it before you pray Maghrib, and do not rush your dinner.”"]},"buhuth":{"en":["“Do not rush your dinner” means: eat what you need in a calm, settled manner, as clarified by the narration of Ibn ‘Umar."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14355],"tks":"متفق عليه: رواه البخاري (672)، مسلم (557)."},{"num":2385,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا وُضِعَ عَشَاءُ أَحَدِكُمْ، وَأُقِيمَتِ الصَّلاَةُ فَابْدَءُوا بِالْعَشَاءِ، وَلاَ يَعْجَلْ حَتَّى يَفْرُغَ مِنْهُ. وَكَانَ ابْنُ عُمَرَ يُوضَعُ لَهُ الطَّعَامُ وَتُقَامُ الصَّلاَةُ فَلاَ يَأْتِيهَا حَتَّى يَفْرُغَ، وَإِنَّهُ لَيَسْمَعُ قِرَاءَةَ الإِمَامِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (673)، ومسلم في المساجد (559) كلاهما من طريق أبي أسامة، عن عبيدالله، عن نافع، عن ابن عمر فذكره. واللفظ للبخاري، ولفظ مسلم: ولا يعجلنَّ حتى يفرغ منه .","grade":"متفق عليه","chapter_ar":"باب تناول العَشاء إذا قُدِّمَ وإن أقيمت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (673) — wording his; Muslim (559)","chapter_en":"Eating dinner if it is served, even if the prayer is established","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “If the dinner of one of you is set out and the prayer is established, then begin with dinner, and do not hurry until you finish it.” Ibn ‘Umar used to have food placed for him while the prayer was being established, and he would not go until he finished—despite hearing the imam’s recitation."]}},"tuhfa":{},"full":1,"rep":[14354],"tks":"متفق عليه: رواه البخاري (673) - واللفظ له، مسلم (559)."},{"num":2386,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَمِعْتُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا وُضع الْعَشَاءُ، وَأُقِيمَتِ الصَّلاَةُ فابدأوا بِالْعَشَاءِ ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (671)، ومسلم في المساجد (558) كلاهما من طريق هشام، عن أبيه، عن عائشة فذكرته، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تناول العَشاء إذا قُدِّمَ وإن أقيمت الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (671); Muslim (558)","chapter_en":"Eating dinner if it is served, even if the prayer is established","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: I heard the Prophet ﷺ say: “If dinner is served and the prayer is established, then begin with dinner.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (671)، مسلم (558)."},{"num":2387,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ صَلَاةَ بِحَضْرَةِ الطَّعَامِ، وَلاَ هُوَ يُدَافِعُهُ الأَخْبَثَانِ ."],"takhrij":"صحيح: رواه أبو داود (89) عن أحمد بن حنبل ومسدد ومحمد بن عيسى قالوا: حدثنا يحيى بن سعيد، عن أبي حزْرَة، حدثنا عبدالله بن محمد. قال ابن عيسى في حديثه: (ابن أبي بكر) ثم اتفقوا أخو القاسم بن محمد قال: كنا عند عائشة، فجيء بطعامها، فقام القاسم يُصَلِّي فقالت عائشة: سمعت رسول الله صلى الله عليه وسلم يقول: فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب لا يُصَلّي الرجل وهو حاقن","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (89). Its core wording is in Sahih Muslim (560): “There is no prayer when food is present, nor while he is being pressed by the two filthy matters.”","chapter_en":"A man should not pray while needing to relieve himself","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah said: I heard the Messenger of Allah ﷺ say: “Prayer is not (to be performed) when food is present, nor while one is being pressed by the two filthy matters (i.e., needing to relieve himself).”"]},"buhuth":{"en":["“The two filthy matters” refers to urine and feces.","This indicates that the presence of food can be a valid excuse for missing the congregation, because it removes focus and humility, which are the core of prayer. Muslim’s wording is general and applies to all prayers."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1355],"tks":"صحيح: رواه أبو داود (89)، وأصل الحديث في صحيح مسلم (560): «لا صلاة بحضرة طعام، ولا وهو يدافعه الأخبثان»."},{"num":2388,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا ثُوِّبَ بالصلاة، فَلَا تَأْتُوهَا وَأَنْتُمْ تَسْعَون. وَأْتُوهَا وَعَلَيْكُمُ السَّكِينَةُ، فَمَا أَدْرَكْتُمْ فصلُّوا، وَمَا فَاتَكُمْ فأتِمُّوا، فَإِنَّ أَحَدَكُمْ فِي صَلَاةٍ مَا كَانَ يَعْمِدُ إِلَى الصَّلَاةِ ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (4) عن العلاء بن عبدالرحمن بن يعقوب، عن أبيه، وإسحاق بن عبدالله، أنهما أخبراه أنهما سمعا أبا هريرة يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب إتيان الصلاة بوقار وسكينة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (4); al-Bukhari (636, 908); Muslim (602)","chapter_en":"Recommended: going to prayer with dignity and calmness","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “When the prayer is announced (i.e., the iqamah is made), do not come to it running. Come to it with calmness. Whatever you catch, pray; and whatever you miss, complete. For one of you is considered in prayer as long as he is heading to the prayer.”"]},"buhuth":{"en":["“Thuwiba” means: the iqamah was made (as explained in other narrations). The iqamah is called “tathwib” because it is a renewed call to prayer after the call of the adhan."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12915],"tks":"متفق عليه: رواه مالك (4)، البخاري (636, 908)، مسلم (602)."},{"num":2389,"demo":false,"sanad":"","matn":["عن أَبِي قَتَادَةَ عَنْ أَبِيهِ، قَالَ: بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ سَمِعَ جَلَبَةَ رِجَالٍ، فَلَمَّا صَلَّى قَالَ: مَا شَأْنُكُمْ. قَالُوا: اسْتَعْجَلْنَا إِلَى الصَّلاَةِ. قَالَ: فَلاَ تَفْعَلُوا، إِذَا أَتَيْتُمُ الصَّلاَةَ فَعَلَيْكُمْ بِالسَّكِينَةِ، فَمَا أَدْرَكْتُمْ فَصَلُّوا، وَمَا فَاتَكُمْ فَأَتِمُّوا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (635)، ومسلم في المساجد (603) كلاهما من طريق يحيى بن أبي كثير، قال أخبرني عبدالله بن أبي قتادة، أن أباه أخبره فذكر الحديث. كذا رواه مسلم، ورواه البخاري بالعنعنة.","grade":"متفق عليه","chapter_ar":"باب استحباب إتيان الصلاة بوقار وسكينة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (635); Muslim (603)","chapter_en":"Recommended: going to prayer with dignity and calmness","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["Abu Qatadah said: While we were praying with the Messenger of Allah ﷺ, he heard the noise of men. When he finished, he said: “What is the matter with you?” They said: “We hurried to the prayer.” He said: “Do not do that. When you come to prayer, keep calmness. Whatever you catch, pray; and whatever you miss, complete.”"]},"buhuth":{"en":["“Jalabah” means their raised sounds while moving."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13565],"tks":"متفق عليه: رواه البخاري (635)، مسلم (603)."},{"num":2390,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا جَاءَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلْيَمْشِ عَلَى هِينَتِهِ، فَلْيُصَلِّ مَا أَدْرَكَ، وَلْيَقْضِ مَا سَبَقَهُ."],"takhrij":"حسن: رواه أبو يعلى (3802 تحقيق الأثري) عن مسروق بن المرزُبان، حدثنا يحيى بن زكريا، عن حُميد، عن أنس فذكر مثله.","grade":"حسن","chapter_ar":"باب استحباب إتيان الصلاة بوقار وسكينة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Ya‘la (3802, tahqiq al-Athari); al-Tabarani in al-Awsat (2718)","chapter_en":"Recommended: going to prayer with dignity and calmness","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “When one of you comes to prayer, let him walk calmly. Let him pray whatever he catches, and make up what preceded him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (3802, تحقيق الأثري)، الطبراني في الأوسط (2718)."},{"num":2391,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (710) عن أحمد بن حنبل وهو في مسنده (9873)، قال: حدثنا محمد بن جعفر، حدثنا شعبةُ عن وَرْقاء، عن عمرو بن دينار، عن عطاء بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما يكره من الصلاة عند الإقامة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (710) (also from Ahmad in his Musnad (9873))","chapter_en":"What is disliked regarding prayer when the iqamah is made","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “When the prayer is established, there is no (other) prayer except the obligatory one.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2441],"tks":"صحيح: رواه مسلم (710)، ورواه أحمد أيضا في المسند (9873)."},{"num":2392,"demo":false,"sanad":"","matn":["أَنَّ عُمَرَ بْنَ الْخَطَّابِ يَوْمَ الْخَنْدَقِ جَعَلَ يَسُبُّ كُفَّارَ قُرَيْشٍ وَقَالَ: يَا رَسُولَ اللَّهِ، وَاللهِ مَا كِدْتُ أَنْ أُصَلِّيَ الْعَصْرَ حَتَّى كَادَتْ أَنْ تَغْرُبَ الشَّمْسُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَوَاللهِ إِنْ صَلَّيْتُهَا. فَنَزَلْنَا إِلَى بُطْحَانَ فَتَوَضَّأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَوَضَّأْنَا. فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ بَعْدَمَا غَرَبَتِ الشَّمْسُ، ثُمَّ صَلَّى بَعْدَهَا الْمَغْرِبَ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (596) وفي المواضع الأخرى، ومسلم في المساجد (631) كلاهما عن هشام (الدستوائي) عن يحيى بن أبي كثير، عن أبي سلمة بن عبدالرحمن، عن جابر بن عبدالله، عن عمر بن الخطاب فذكر مثله. واللفظ لمسلم، وقوله: فوالله إن صليتُها معناها ما صليتُها وإنما حلف النبي صلى الله عليه وسلم تطييباً لقلب عمر، فإنه شق عليه تأخير العصر إلى المغرب، فأخبره أنه لم يُصلها أيضاً. وجاء التصريح بذلك في حديث البخاري فقال فيه والله ما صَلّيتُها .","grade":"متفق عليه","chapter_ar":"باب ما جاء في أداء الصلوات الفائتة بالجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (596); Muslim (631) — wording Muslim’s","chapter_en":"Making up missed prayers in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":16,"content":{"translation":{"en":["‘Umar ibn al-Khattab said that on the day of al-Khandaq he began cursing the disbelievers of Quraysh and said: “O Messenger of Allah, by Allah, I nearly did not pray ‘Asr until the sun was about to set.” The Messenger of Allah ﷺ said: “By Allah, I have not prayed it either.” So we went down to Buthan; the Messenger of Allah ﷺ performed wudu and we performed wudu. Then the Messenger of Allah ﷺ prayed ‘Asr after the sun had set, and then prayed Maghrib after it."]},"buhuth":{"ar":["وفي مسلم والبخاري: «فوالله ما صليتها». قالوا: قال ذلك تطييباً لقلب عمر لأنه شق عليه تأخير العصر حتى قرب المغرب، فأخبره أنه لم يصلها أيضاً."],"en":["Both Muslim and al-Bukhari have the explicit negative wording: “By Allah, I have not prayed it.” Scholars mention he said this to comfort ‘Umar, since it distressed him that ‘Asr was delayed until close to Maghrib—so the Prophet ﷺ informed him that he too had not prayed it yet."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (596)، ومسلم (631)، واللفظ لمسلم."},{"num":2393,"demo":false,"sanad":"","matn":["عن أَبِي قَتَادَةَ قَالَ: فَبَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسِيرُ حَتَّى ابْهَارَّ اللَّيْلُ وَأَنَا إِلَى جَنْبِهِ، قَالَ: فَنَعَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَالَ عَنْ رَاحِلَتِهِ، فَأَتَيْتُهُ فَدَعَمْتُهُ مِنْ غَيْرِ أَنْ أُوقِظَهُ. حَتَّى اعْتَدَلَ عَلَى رَاحِلَتِهِ. قَالَ: ثُمَّ سَارَ حَتَّى تَهَوَّرَ اللَّيْلُ، مَالَ عَنْ رَاحِلَتِهِ. قَالَ: فَدَعَمْتُهُ. مِنْ غَيْرِ أَنْ أُوقِظَهُ. حَتَّى اعْتَدَلَ عَلَى رَاحِلَتِهِ، قَالَ: ثُمَّ سَارَ حَتَّى إِذَا كَانَ مِنْ آخِرِ السَّحَرِ مَالَ مَيْلَةً هِيَ أَشَدُّ مِنَ الْمَيْلَتَيْنِ الْأُولَيَيْنِ. حَتَّى كَادَ يَنْجَفِلُ، فَأَتَيْتُهُ فَدَعَمْتُهُ. فَرَفَعَ رَأْسَهُ، فَقَالَ: مَنْ هَذَا؟ قُلْتُ: أَبُو قَتَادَةَ، قَالَ: مَتَى كَانَ هَذَا مَسِيرَكَ مِنِّي؟ قُلْتُ: مَا زَالَ هَذَا مَسِيرِي مُنْذُ اللَّيْلَةِ، قَالَ: حَفِظَكَ اللهُ بِمَا حَفِظْتَ بِهِ نَبِيَّهُ، ثُمَّ قَالَ: هَلْ تَرَانَا نَخْفَى عَلَى النَّاسِ؟ ثُمَّ قَالَ: هَلْ تَرَى مِنْ أَحَدٍ؟ قُلْتُ: هَذَا رَاكِبٌ، ثُمَّ قُلْتُ: هَذَا رَاكِبٌ آخَرُ، حَتَّى اجْتَمَعْنَا فَكُنَّا سَبْعَةَ رَكْبٍ، قَالَ: فَمَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الطَّرِيقِ. فَوَضَعَ رَأْسَهُ. ثُمَّ قَالَ: احْفَظُوا عَلَيْنَا صَلَاتَنَا، فَكَانَ أَوَّلَ مَنِ اسْتَيْقَظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالشَّمْسُ فِي ظَهْرِهِ، قَالَ: فَقُمْنَا فَزِعِينَ، ثُمَّ قَالَ: ارْكَبُوا، فَرَكِبْنَا. فَسِرْنَا حَتَّى إِذَا ارْتَفَعَتِ الشَّمْسُ، نَزَلَ. ثُمَّ دَعَا بِمِيضَأَةٍ كَانَتْ مَعِي، فِيهَا شَيْءٌ مِنْ مَاءٍ، قَالَ: فَتَوَضَّأَ مِنْهَا وُضُوءًا دُونَ وُضُوءٍ، قَالَ: وَبَقِيَ فِيهَا شَيْءٌ مِنْ مَاءٍ، ثُمَّ قَالَ لِأَبِي قَتَادَةَ: احْفَظْ عَلَيْنَا مِيضَأَتَكَ، فَسَيَكُونُ لَهَا نَبَأٌ، ثُمَّ أَذَّنَ بِلَالٌ بِالصَّلَاةِ. فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ، ثُمَّ صَلَّى الْغَدَاةَ، فَصَنَعَ كَمَا كَانَ يَصْنَعُ كُلَّ يَوْمٍ، قَالَ: وَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكِبْنَا مَعَهُ، قَالَ: فَجَعَلَ بَعْضُنَا يَهْمِسُ إِلَى بَعْضٍ: مَا كَفَّارَةُ مَا صَنَعْنَا بِتَفْرِيطِنَا فِي صَلَاتِنَا؟ ثُمَّ قَالَ: أَمَا لَكُمْ فِيَّ أُسْوَةٌ؟، ثُمَّ قَالَ: أَمَا إِنَّهُ لَيْسَ فِي النَّوْمِ تَفْرِيطٌ، إِنَّمَا التَّفْرِيطُ عَلَى مَنْ لَمْ يُصَلِّ الصَّلَاةَ حَتَّى يَجِيءَ وَقْتُ الصَّلَاةِ الْأُخْرَى، فَمَنْ فَعَلَ ذَلِكَ فَلْيُصَلِّهَا حِينَ يَنْتَبِهُ لَهَا، فَإِذَا كَانَ الْغَدُ فَلْيُصَلِّهَا عِنْدَ وَقْتِهَا ثُمَّ قَالَ: مَا تَرَوْنَ النَّاسَ صَنَعُوا؟، قَالَ: ثُمَّ قَالَ: أَصْبَحَ النَّاسُ فَقَدُوا نَبِيَّهُمْ، فَقَالَ أَبُو بَكْرٍ وَعُمَرُ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَكُمْ. لَمْ يَكُنْ لِيُخَلِّفَكُمْ، وَقَالَ النَّاسُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَيْدِيكُمْ، فَإِنْ يُطِيعُوا أَبَا بَكْرٍ وَعُمَرَ يَرْشُدُوا.","قَالَ: فَانْتَهَيْنَا إِلَى النَّاسِ حِينَ امْتَدَّ النَّهَارُ وَحَمِيَ كُلَّ شَيْءٍ. وَهُمْ يَقُولُونَ: يَا رَسُولَ اللَّهِ! هَلَكْنَا. عَطَشْنَا. فَقَالَ: لاَ هَلَكَ عَلَيْكُمْ . ثُمَّ قَالَ: أَطْلِقُوا لِي غُمْرِي . قَالَ: وَدَعَا بِالْمَيْضَأَةِ. فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُبُّ وَأَبُو قَتَادَةَ يَسْقِيهِمْ. فَلَمْ يَعُدْ أَنْ رَأَى النَّاسَ مَاءً فِي الْمِيْضَأَةِ تَكَابُوا عَلَيْهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَحْسِنُوا الْمَلَأَ، كُلَّكُمْ سَيْرُوَى . قَالَ: فَفَعَلُوا. فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُبُّ وَأَسْقِيهِمْ. حَتَّى مَا بَقِيَ غَيْرِي وَغَيْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . قَالَ: ثُمَّ صَبَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِي: اشْرَبْ . فَقُلْتُ: لاَ أَشْرَبُ حَتَّى تَشْرَبَ يَا رَسُولَ اللَّهِ! قَالَ: إِنَّ سَاقِيَ الْقَوْمِ آخِرُهُمْ شُرْبًا قَالَ: فَشَرِبْتُ. وَشَرِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . قَالَ: فَأَتَى النَّاسُ الْمَاءَ جَامَيْنِ رُوَاءً. قَالَ: فَقَالَ عبدالله بْنُ رَبَاحٍ: إِنِّي لَأُحْدِثُ هَذَا الْحَدِيثَ فِي مَسْجِدِ الْجَامِعِ إِذْ قَالَ عِمْرَانُ بْنُ حُصَيْنٌ: انْظُرْ أَيُّهَا الْفَتَى كَيْفَ تُحَدِّثُ. فَإِنِّي أَحَدُ الرَّكَبِ تِلْكَ اللَّيْلَةَ. قَالَ، قُلْتُ: فَأَنْتَ أَعْلَمُ بِالْحَدِيثِ. فَقَالَ: مِمَّنْ أَنْتَ؟ قُلْتُ: مِنَ الأَنْصَارِ. قَالَ: حَدَثَ فَأَنْتُمْ أَعْلَمُ بِحَدِيثِكُمْ. قَالَ: فَحَدَّثْتُ الْقَوْمَ. فَقَالَ عِمْرَانُ: لَقَدْ شَهِدْتُ تِلْكَ اللَّيْلَةَ وَمَا شَعَرْتَ أَنَّ أُحُدًا حَفِظَهُ كَمَا حَفِظْتُهُ."],"takhrij":"متفق عليه: رواه مسلم في المساجد (681) عن شيبان بن فروخ، حدثنا سليمان (يعني ابن المغيرة) حدثنا ثابت، عن عبدالله بن رباح، عن أبي قتادة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أداء الصلوات الفائتة بالجماعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: narrated by Muslim (681) and al-Bukhari (595).","chapter_en":"Making up missed prayers in congregation","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":16,"content":{"translation":{"en":["Abu Qatadah said: The Messenger of Allah ﷺ addressed us and said: “You will travel through this evening and night, and you will reach the water tomorrow, if Allah wills.” So the people set out, each continuing on without turning aside for another. As the Messenger of Allah ﷺ continued traveling until the night reached its midpoint, I was beside him. The Messenger of Allah ﷺ became drowsy and leaned on his mount, so I supported him without waking him until he straightened. He then continued until most of the night had passed, and he leaned again, so I supported him without waking him until he straightened. Then, near the end of the pre-dawn time, he leaned more strongly than before, and he nearly fell, so I supported him. He raised his head and said, “Who is this?” I said, “Abu Qatadah.” He said, “How long have you been traveling close to me?” I said, “I have been at your side all night.” He said, “May Allah protect you for how you protected His Prophet.” Then he said, “Do you think we are hidden from the people?” Then he said, “Do you see anyone?” I said, “This is a rider,” then I said, “This is another rider,” until we gathered and became seven riders. The Messenger of Allah ﷺ turned off the road, rested his head, and said, “Watch over our prayer.” The first to awaken was the Messenger of Allah ﷺ, and the sun was above him. We stood up frightened. He said, “Mount up,” so we mounted and traveled until the sun rose higher, then he stopped. He called for a small water container that I had, with some water in it. He performed a light ablution from it, leaving some water. Then he said to Abu Qatadah, “Keep your water container safe for us; it will have news.” Then Bilal called the call to prayer. The Messenger of Allah ﷺ prayed two units, then prayed the dawn prayer as he normally did. Then the Messenger of Allah ﷺ rode and we rode with him. Some of us began whispering: “What is the expiation for what we did by neglecting our prayer?” He said, “Do you not have an example in me?” Then he said, “There is no negligence in sleep; negligence is only for the one who does not pray until the time of the next prayer comes. Whoever does that should pray when he wakes up; and the next day he should pray it at its proper time.” Then he said, “What do you think the people did?” He said, “Morning came and the people missed their Prophet. Abu Bakr and Umar said: The Messenger of Allah ﷺ is behind you; he would not leave you. And the people said: The Messenger of Allah ﷺ is ahead of you; if they obey Abu Bakr and Umar, they will be guided.”","We reached the people when the day had stretched on and everything had become hot. They were saying, “Messenger of Allah ﷺ, we are ruined; we are thirsty.” He said, “No ruin is upon you.” Then he said, “Bring me my small cup.” He called for the water container. The Messenger of Allah ﷺ began pouring, and Abu Qatadah gave them water. When people saw water in the container, they rushed toward it. The Messenger of Allah ﷺ said, “Show good conduct; all of you will be quenched.” So they did. The Messenger of Allah ﷺ continued pouring and giving them drink until none remained except me and the Messenger of Allah ﷺ. Then the Messenger of Allah ﷺ poured and said to me, “Drink.” I said, “I will not drink until you drink, Messenger of Allah ﷺ.” He said, “The one who serves the people is the last of them to drink.” So I drank, and the Messenger of Allah ﷺ drank. The people returned fully quenched and satisfied. Abdullah ibn Rabah said: I was narrating this report in the central mosque when Imran ibn Husayn said: “Young man, watch how you narrate, for I was one of the riders that night.” I said, “Then you know the report better.” He asked, “Who are you?” I said, “From the Helpers.” He said, “Narrate, for you know your report best.” I narrated to the people, and Imran said: “I witnessed that night, and I did not realize anyone preserved it as well as you preserved it.”"]},"buhuth":{"en":["“The night reached its midpoint”: the night became half over.","“Most of the night had passed”: the greater part of the night was gone.","“I supported him”: I steadied him as he leaned from drowsiness, like a support post.","“Bring me my small cup”: bring me a small drinking cup.","“Show good conduct”: show good manners and good behavior with one another.","“Fully quenched and satisfied”: rested and satisfied after drinking.","“He almost fell”: he nearly slipped or fell.","“Ablution lighter than a full ablution”: a brief, light ablution."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (681)، والبخاري ( 595)."},{"num":2394,"demo":false,"sanad":"","matn":["عَنْ عَمَّارِ بْنِ يَاسِرٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ الرَّجُلَ لَيَنْصَرِفُ، وَمَا كُتِبَ لَهُ إِلاَّ عُشْرُ صَلاَتِهِ، تُسْعُهَا، ثُمُنُهَا، سُبُعُهَا، سُدُسُهَا، خُمُسُهَا، رُبُعُهَا، ثُلُثُهَا، نِصْفُهَا."],"takhrij":"حسن: رواه أبو داود (796) قال: حدثنا قتيبة بن سعيد، عن بكر -يعني ابن مُضر، عن ابن عَجْلان، عن سعيد المقبري، عن عمر بن الحكم، عن عبدالله بن عَنَمة المزني، عن عمار بن ياسر فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في نقصان الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (796); Ahmad (18894); al-Tahawi in Mushkil al-Athar (1103)","chapter_en":"What has come regarding the reduction in what is recorded from prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["‘Ammar ibn Yasir said: I heard the Messenger of Allah ﷺ say: “A man may finish his prayer and leave, yet nothing is recorded for him except a tenth of it, or a ninth, or an eighth, or a seventh, or a sixth, or a fifth, or a quarter, or a third, or half.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15686],"tks":"حسن: رواه أبو داود (796)، والإمام أحمد ( 18894)، والطحاوي في مشكله (1103)."},{"num":2395,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا اسْتَأْذَنَتِ امْرَأَةُ أَحَدِكُمْ إِلَى الْمَسْجِدِ فَلَا يَمْنَعْهَا."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5238)، ومسلم في الصلاة (442) كلاهما من طريق سفيان بن عيينة، عن الزهري، عن سالم، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب خروج النساء لحضور الجماعات في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (5238); Muslim (442)","chapter_en":"Women going out to attend congregational prayers in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Messenger of Allah ﷺ said: “If the wife of any one of you asks permission to go to the mosque, he must not prevent her.”"]},"buhuth":{"en":["Hanzalah, in his narration from Salim, included the wording “at night.” Al-Bukhari narrated it with that restriction, but most narrators did not mention the phrase “at night,” as Muslim narrates from Ibn Numayr from his father from Hanzalah. Muslim also narrates that Ibn ‘Umar reported: The Messenger of Allah ﷺ said: “Do not prevent women from going out to the mosques at night.” Then one of Ibn ‘Umar’s sons said: “We will not let them go out, so they do not use it as a pretext for wrongdoing.” Ibn ‘Umar rebuked him and said: “I say: the Messenger of Allah ﷺ said, and you say: we will not let them.” In another narration he struck his chest and said: “I narrate to you from the Messenger of Allah ﷺ and you say: no.”","This son was named Bilal. Ka‘b ibn ‘Alqamah narrated from him from his father that the Messenger of Allah ﷺ said: “Do not prevent women from their share of the mosques when they ask your permission.” Bilal ibn ‘Abdullah ibn ‘Umar said: “By Allah, we will prevent them.” ‘Abdullah replied: “I say: the Messenger of Allah ﷺ said—and you say: we will prevent them.” (Narrated by Muslim.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5238)، مسلم (442)."},{"num":2396,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: كَانَتِ امْرَأَةٌ لِعُمَرَ تَشْهَدُ صَلاَةَ الصُّبْحِ وَالْعِشَاءِ فِي الْجَمَاعَةِ فِي الْمَسْجِدِ، فَقِيلَ لَهَا: لِمَ تَخْرُجِينَ، وَقَدْ تَعْلَمِينَ أَنَّ عُمَرَ يَكْرَهُ ذَلِكَ وَيَغَارُ؟ قَالَتْ: وَمَا يَمْنَعُهُ أَنْ يَنْهَانِي؟ قَالَ: يَمْنَعُهُ قَوْلُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الجمعة (900) عن يوسف بن موسى، حدثنا أبو أسامة، حدثنا عبيدالله بن عمر، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب خروج النساء لحضور الجماعات في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (900); Muslim (442) (in Muslim without the story of ‘Umar)","chapter_en":"Women going out to attend congregational prayers in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Umar said: A woman of ‘Umar used to attend the Fajr and ‘Isha prayers in congregation in the mosque. It was said to her: “Why do you go out, when you know that ‘Umar dislikes that and is jealous?” She said: “What prevents him from forbidding me?” It was said: “What prevents him is the statement of the Messenger of Allah ﷺ: ‘Do not prevent the female servants of Allah from the mosques of Allah.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (900)، مسلم (442) (وفي مسلم دون قصة عمر)."},{"num":2397,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَمْنَعُوا نِسَاءَكُمُ الْمَسَاجِدَ، وَبُيُوتُهُنَّ خَيْرٌ لَهُنَّ."],"takhrij":"صحيح: رواه أبو داود (567) عن عثمان بن أبي شيبة، حدثنا يزيد بن هارون، أخبرنا العوام بن حوشب، حدثني حبيب بن أبي ثابت، عن ابن عمر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب خروج النساء لحضور الجماعات في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (567); Ibn Khuzaymah (1684) (authenticated); al-Hakim (755)","chapter_en":"Women going out to attend congregational prayers in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “Do not prevent your women from the mosques, though their houses are better for them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (567)، ابن خزيمة (1684) (صححه)، الحاكم (755)."},{"num":2398,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ، وَلَكِنْ لِيَخْرُجْنَ وَهُنَّ تَفِلاَتٌ."],"takhrij":"حسن: رواه أبو داود (565) عن موسى بن إسماعيل، حدثنا حماد، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب خروج النساء لحضور الجماعات في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (565); Ibn Khuzaymah (1679); Ibn Hibban (2214)","chapter_en":"Women going out to attend congregational prayers in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Do not prevent the female servants of Allah from the mosques of Allah, but let them go out while they are not perfumed.”"]},"buhuth":{"en":["“Tafal” means an unperfumed state (i.e., not wearing fragrance). It is said: a woman is “tafilah” when she has not applied perfume; and “women tafilat” (plural)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (565)، ابن خزيمة (1679)، ابن حبان (2214)."},{"num":2399,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ، وَلْيَخْرُجْنَ وَهُنَّ تَفِلاتٌ."],"takhrij":"حسن: رواه أحمد (21673)، والطبراني في الكبير (5239)، والبزار كشف الأستار (445) كلهم من طرق عن عبدالرحمن بن إسحاق، عن محمد ابن عبدالله بن عمرو بن عثمان، عن بُسر بن سعيد، عن زيد بن خالد فذكر مثله.","grade":"حسن","chapter_ar":"باب خروج النساء لحضور الجماعات في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (21673); al-Bazzar (Kashf al-Astar, 445); Ibn Hibban (2211) (authenticated)","chapter_en":"Women going out to attend congregational prayers in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Zayd ibn Khalid reported that the Messenger of Allah ﷺ said: “Do not prevent the female servants of Allah from the mosques of Allah, and let them go out unperfumed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (21673)، البزار في كشف الأستار ( 445)، ابن حبان (2211) (صححه)."}]);